/**
 * Quiz de fixação na ótica do AGILISTA (Scrum Master / Agile Coach).
 * Usado só na trilha /agilidade. QA e Geral usam data/quizzes.ts.
 * Chave = id do tópico (ver data/roadmap.ts).
 */
import type { QuizQuestion } from "./quizzes";

export const QUIZZES_AGILE: Record<string, QuizQuestion[]> = {
  "ia-ml-dl": [{"question":"Segundo o artigo, qual é a relação entre IA, Machine Learning e Deep Learning?","options":["São três tecnologias concorrentes que resolvem o mesmo problema de formas rivais.","São como bonecas russas: IA é o guarda-chuva, ML é um sub-conjunto que aprende com dados e Deep Learning é um sub-conjunto de ML com redes neurais.","Deep Learning é o conceito mais amplo, e IA é apenas uma aplicação prática dele.","ML e Deep Learning são sinônimos, e IA é uma coisa totalmente à parte."],"answer":1,"explanation":"O artigo descreve os três termos como bonecas russas encaixadas: IA é o guarda-chuva, ML aprende padrões a partir de dados e Deep Learning é o sub-conjunto de ML baseado em redes neurais."},{"question":"Na planning, o time propõe 'usar IA para classificar os chamados por urgência'. Segundo o artigo, qual pergunta o Agilista deve fazer para reorganizar a conversa?","options":["'Qual modelo de rede neural vamos usar por dentro?'","'Quantos servidores isso vai consumir em produção?'","'Isso segue regras fixas ou aprende com exemplos?'","'Quem no time já sabe programar Deep Learning?'"],"answer":2,"explanation":"O artigo destaca que o Agilista não precisa saber como uma rede neural funciona, mas sim a pergunta que muda o tamanho, o risco e a forma de acompanhar o trabalho: 'regras fixas ou aprende com exemplos?'."},{"question":"O time confirma que a classificação de chamados vai 'aprender com o histórico'. Segundo o artigo, o que isso mexe na definição de pronto?","options":["'Pronto' deixa de ser binário ('funciona') e passa a ser uma meta combinada ('acerta o suficiente para valer a pena').","'Pronto' fica mais fácil, porque a IA se auto-corrige e nunca erra depois de aprender.","'Pronto' não muda: é entregar o classificador funcionando, como qualquer item de backlog.","'Pronto' passa a depender só da liberação de infraestrutura, sem critério de qualidade."],"answer":0,"explanation":"O artigo explica que algo que aprende com dados vai errar uma parte dos casos sempre, então a definição de pronto deixa de ser binária e vira uma taxa de acerto combinada com o PO."},{"question":"Ainda na iniciativa de classificar chamados que 'aprende com exemplos', como o artigo sugere que o Agilista ajude a desenhar a entrega?","options":["Escrever uma única história de 'classificador pronto' e fechar o escopo no planning.","Adiar a iniciativa até o time contratar um especialista em redes neurais.","Prometer ao stakeholder que a IA vai acertar sempre para não travar a aprovação.","Fatiar: uma primeira versão, uma medição da taxa de acerto com chamados reais e uma conversa com o PO sobre qual erro é tolerável — um marco de aprendizado antes do de entrega."],"answer":3,"explanation":"O artigo mostra o Agilista ajudando a fatiar a entrega em versão inicial, medição com dados reais e acordo sobre erro tolerável, colocando um marco de aprendizado antes do marco de entrega."},{"question":"Por que o artigo compara um sistema que aprende com dados a uma 'previsão do tempo' e não a uma 'calculadora'?","options":["Porque depende de internet, como as previsões meteorológicas.","Porque geralmente acerta, mas não é exato nem idêntico toda vez — ao contrário de um processo de regras fixas, que é previsível.","Porque é sempre impreciso e não serve para decisões sérias.","Porque só funciona em determinadas épocas do ano, como o clima."],"answer":1,"explanation":"O artigo usa a analogia para explicar que sistemas que aprendem com dados acertam a maioria das vezes mas erram uma parte, comportando-se como previsão do tempo, diferente da exatidão de uma calculadora com regras fixas."}],
  "llm": [{"question":"Segundo o artigo, o que um LLM de fato faz quando gera uma resposta?","options":["Consulta uma base de fatos verificados para garantir que a resposta seja verdadeira.","Prevê a continuação mais provável de um texto, e não 'a verdade' — por isso pode escrever com confiança algo que nunca aconteceu.","Aprende com a sua conversa em tempo real e memoriza as decisões do seu time.","Só reorganiza trechos que você mesmo colou, sem nunca inventar nada."],"answer":1,"explanation":"O artigo define o LLM como uma máquina de prever a continuação mais provável de um texto, o que explica por que ele pode afirmar com total confiança um prazo, decisão ou nome que nunca existiu."},{"question":"Por que o artigo diz que o LLM é uma ferramenta especialmente valiosa para o Agilista?","options":["Porque ele substitui o julgamento do Agilista sobre o que é prioridade.","Porque ele conhece o time, o projeto e as decisões sem precisar de contexto.","Porque boa parte do trabalho do Agilista é texto (atas, backlog, resumos, comunicação), e é exatamente nesse terreno que o LLM brilha.","Porque ele elimina a necessidade de revisar qualquer coisa antes de enviar."],"answer":2,"explanation":"O artigo aponta que o dia do Agilista é quase todo feito de texto — atas, itens de backlog, resumos, atualizações — e o LLM é um assistente de redação incansável para esse tipo de tarefa."},{"question":"Você pede um resumo à IA e recebe uma resposta genérica, sem cara do seu time. Segundo o artigo, qual é a causa mais provável?","options":["A pergunta foi feita sem contexto — a 'mesa de trabalho' da IA estava vazia.","O modelo está com defeito e precisa ser trocado por outro.","A IA está escondendo o que sabe sobre o seu projeto de propósito.","O assunto é complexo demais para qualquer LLM resolver."],"answer":0,"explanation":"O artigo afirma que o LLM só sabe o que você coloca na conversa; resposta genérica quase sempre significa pergunta sem contexto, não 'IA ruim'."},{"question":"Depois de um refinamento longo, o artigo sugere colar as anotações e pedir ao LLM uma descrição de item de backlog. Qual é a 'parte insubstituível' que continua sendo do Agilista?","options":["Formatar o texto com marcadores e títulos antes de enviar.","Escolher a fonte e a cor do documento final no Confluence.","Digitar as anotações de novo para o modelo não perder nada.","Validar se o rascunho reflete o que foi realmente combinado — o julgamento sobre o que é verdade e o que é prioridade."],"answer":3,"explanation":"O artigo descreve a dupla 'estagiário veloz, revisor criterioso': a IA acelera a redação, mas validar se o rascunho corresponde ao que foi combinado com o time continua sendo trabalho humano."},{"question":"Um colega afirma na daily: 'a IA me deu esse dado, então está certo'. Com base no artigo, qual resposta é a mais alinhada?","options":["'Confia total: o LLM é um oráculo, ele sabe a verdade.'","'Tudo o que sai do LLM é rascunho até você conferir, porque ele gera a continuação provável, não a verdade.'","'O LLM aprendeu com a nossa conversa, então já conhece o nosso projeto.'","'Se veio da IA, não precisa de contexto nenhum para estar correto.'"],"answer":1,"explanation":"O artigo reforça que, como o LLM gera a continuação mais provável e não a verdade, tudo o que sai dele é rascunho até ser conferido na fonte."}],
  "token": [{"question":"Segundo o artigo, qual imagem melhor descreve o que é um token para o Agilista?","options":["Um selo de qualidade que garante que a resposta da IA está correta.","Uma senha de acesso que libera o uso da ferramenta de IA.","O taxímetro da IA: tudo o que você envia e tudo o que ela responde é contado e, nas ferramentas pagas, cobrado.","Um limite de tempo por conversa, independente do tamanho do texto."],"answer":2,"explanation":"O artigo usa a imagem do taxímetro: o token é a unidade em que a IA conta o texto de entrada e de saída, e é a base do que as APIs cobram."},{"question":"De acordo com o artigo, quais são as duas consequências práticas de o texto ser medido em tokens?","options":["O custo cresce com o volume de texto e existe um teto do quanto a IA consegue ler de uma vez.","A IA fica mais lenta à noite e mais rápida de manhã.","O modelo aprende com cada conversa e cobra menos com o tempo.","A resposta sempre vem no mesmo tamanho, não importa o pedido."],"answer":0,"explanation":"O artigo destaca duas consequências concretas do 'taxímetro': o custo aumenta com o volume de texto e há um limite máximo do que a IA consegue ler de uma vez."},{"question":"Você quer um panorama dos aprendizados de todas as retros do semestre. Segundo o artigo, qual é a abordagem recomendada?","options":["Colar as atas inteiras do Confluence, com listas de presença e conversas paralelas, para não perder nada.","Copiar só as seções de 'ações e aprendizados' de cada retro — fazer curadoria do material.","Dividir cada ata em um chat diferente e nunca consolidar.","Pedir à IA que invente os aprendizados a partir do nome de cada retro."],"answer":1,"explanation":"O artigo recomenda curadoria: selecionar só as seções de ações e aprendizados gera resposta mais focada, mais barata e sem estourar o limite, em vez de um despejo de texto."},{"question":"O artigo compara curadoria de contexto com uma habilidade que o Agilista já domina. Qual?","options":["Estimar histórias em pontos de complexidade.","Facilitar uma retrospectiva com dinâmicas variadas.","Preparar a pauta de uma reunião: levar os três pontos que importam, não as 40 páginas.","Calcular a velocidade média do time nas últimas sprints."],"answer":2,"explanation":"O artigo diz que curadoria é algo que o Agilista já faz ao preparar uma pauta: ninguém leva 40 páginas para a reunião, leva os pontos que importam — o mesmo vale para o contexto da IA."},{"question":"Numa priorização de portfólio, alguém diz que 'o custo da IA depende do volume'. Segundo o artigo, que contribuição o Agilista que entende tokens pode dar?","options":["Pedir para tirar a IA da iniciativa, já que custo variável é sempre inviável.","Afirmar que o custo é fixo e não depende de nada.","Sugerir que o time só use o modelo mais caro para garantir qualidade.","Perguntar no refinamento quanto texto o produto vai ler e escrever por dia, porque isso é metade do caso de negócio."],"answer":3,"explanation":"O artigo mostra que, entendendo o taxímetro por texto processado, o Agilista pode estimar entrada e saída por dia no refinamento — uma contribuição que só quem entendeu o conceito consegue dar."}],
  "context-window": [{"question":"Segundo o artigo, qual é a melhor analogia para a janela de contexto?","options":["Um disco rígido permanente onde a IA guarda tudo para sempre.","Um quadro branco que vai enchendo: quando lota, o que foi escrito primeiro é apagado para dar lugar ao novo.","Uma agenda que a IA consulta para lembrar de compromissos futuros.","Um filtro que descarta as informações menos importantes automaticamente."],"answer":1,"explanation":"O artigo compara a janela de contexto à memória de trabalho: um quadro branco que, ao lotar, apaga o que foi escrito primeiro."},{"question":"A IA ignorou o início de um material longo que você colou. Segundo o artigo, qual é a conclusão correta?","options":["O material provavelmente estourou a janela de contexto; a solução é dividir o trabalho em partes.","A IA é burra e não serve para textos grandes.","O modelo está com defeito e precisa ser reiniciado.","A IA escolheu ignorar o início de propósito porque não era relevante."],"answer":0,"explanation":"O artigo alerta que ignorar parte do material é sintoma de quadro branco lotado, não de burrice — e a solução é dividir o trabalho e começar conversas novas para assuntos novos."},{"question":"O artigo aponta um 'detalhe traiçoeiro' quando o material não cabe na janela de contexto. Qual é?","options":["A IA avisa em vermelho que faltou espaço e para de responder.","A IA repete o mesmo trecho várias vezes até encher a resposta.","A IA devolve a pergunta pedindo um texto menor.","A IA raramente avisa: responde com confiança sobre o que enxergou e silencia sobre o resto, parecendo completa."],"answer":3,"explanation":"O artigo alerta que, quando o material não cabe, a IA raramente avisa — responde com confiança sobre o que viu e cala sobre o resto, e a resposta parece completa."},{"question":"Por causa do risco da janela de contexto, qual pergunta o artigo sugere que o Agilista aprenda a fazer?","options":["'A resposta está bem escrita?'","'A IA usou o modelo mais caro?'","'A IA viu tudo o que eu precisava que ela visse?'","'Quantos tokens isso consumiu no total?'"],"answer":2,"explanation":"O artigo diz que a pergunta certa não é 'a resposta está boa?', e sim 'a IA viu tudo o que eu precisava que ela visse?', por causa do silêncio sobre o que não coube."},{"question":"Você está montando o relatório executivo de uma iniciativa grande e colou 40 páginas de uma vez, mas a IA só cobriu bem o final. Segundo o artigo, qual tática resolve — e com que benefício extra?","options":["Desistir e escrever o relatório inteiro à mão.","Colar tudo de novo, mais rápido, para a IA não perder o início.","Trocar de ferramenta de IA até uma conseguir ler 40 páginas.","Pedir um resumo por épico, um de cada vez, e depois consolidar — resultado completo e auditável, com cada conclusão rastreável ao seu épico."],"answer":3,"explanation":"O artigo mostra a tática de resumir épico por épico e consolidar no fim: o resultado fica completo e auditável, permitindo apontar de qual épico veio cada número quando um stakeholder questionar na review."}],
  "prompt": [{"question":"Segundo o artigo, escrever um bom prompt exige, no fundo, uma habilidade que o Agilista já domina. Qual?","options":["Programação em linguagem natural.","Facilitação: assim como uma cerimônia sem pauta clara vira bagunça, uma pergunta vaga gera resposta vaga.","Estimativa de esforço em pontos de história.","Configuração técnica de parâmetros do modelo."],"answer":1,"explanation":"O artigo afirma que instruir bem a IA usa os mesmos músculos da facilitação: objetivo, contexto, formato e limites — os mesmos ingredientes de uma boa reunião."},{"question":"De acordo com o artigo, quais são os ingredientes de um bom prompt — os mesmos de uma boa reunião?","options":["Objetivo, contexto, formato e limites.","Velocidade, custo, tamanho e temperatura.","Épico, história, tarefa e sub-tarefa.","Data, hora, participantes e local."],"answer":0,"explanation":"O artigo lista objetivo ('o que precisa sair daqui'), contexto ('o que todos precisam saber'), formato ('como registrar') e limites ('o que está fora da pauta')."},{"question":"O artigo diz que uma segunda habilidade de facilitação transfere direto para prompts. Qual é?","options":["A pontualidade nas cerimônias.","A imparcialidade na condução de conflitos.","A iteração: nenhum facilitador acerta o formato de primeira; observa, ajusta e tenta de novo.","A gestão de dependências entre times."],"answer":2,"explanation":"O artigo destaca a iteração: a primeira resposta é um rascunho da conversa, não o veredito sobre a ferramenta — ajusta-se e tenta de novo, como no desenho de uma cerimônia."},{"question":"Quando um prompt fica bom, o que o artigo recomenda fazer com ele?","options":["Descartá-lo, porque cada tarefa exige começar do zero.","Compartilhá-lo publicamente para toda a empresa usar sem adaptar.","Mantê-lo em segredo para ter vantagem sobre outros agilistas.","Guardá-lo como patrimônio, assim como se mantêm templates de ata e planning no Confluence, para tarefas recorrentes."],"answer":3,"explanation":"O artigo compara um bom prompt a um template salvo no Confluence: prompts lapidados para tarefas recorrentes (status semanal, resumo de retro, quebra de épico) param de custar uma hora e passam a custar dez minutos de revisão."},{"question":"O artigo contrasta 'resuma essa retro' com um prompt forte. O que torna o segundo melhor?","options":["Ele especifica papel, tarefa, estrutura e tom (ex.: 'aja como facilitador ágil, agrupe por tema, liste 3 ações com responsável, resuma em 5 linhas em tom neutro').","Ele é mais curto e deixa a IA livre para decidir tudo.","Ele pede para a IA usar o modelo mais caro disponível.","Ele repete a mesma pergunta várias vezes para reforçar."],"answer":0,"explanation":"O artigo mostra que o prompt forte devolve algo usável quase direto porque especifica papel, tarefa, estrutura e tom — exatamente como ao passar o bastão para um co-facilitador."}],
  "temperature": [{"question":"Segundo o artigo, o que a temperatura controla numa resposta da IA?","options":["A velocidade com que a resposta é gerada.","O quanto a IA varia: baixa gera respostas consistentes e repetíveis; alta gera respostas criativas e diferentes a cada vez.","O custo em tokens de cada resposta.","O tamanho máximo do texto que a IA consegue ler."],"answer":1,"explanation":"O artigo descreve a temperatura como o botão que regula variação: baixa para consistência e repetibilidade, alta para criatividade e variedade."},{"question":"O artigo diz que o Agilista não vai mexer tecnicamente no botão de temperatura. Então por que o conceito importa?","options":["Porque ele precisa configurar cada modelo antes de usar.","Porque ele vai programar o comportamento da IA no time.","Porque o conceito orienta como usar a IA: escolher entre consistência e variedade conforme a tarefa, pedindo isso no próprio prompt.","Porque a temperatura define o preço da fatura no fim do mês."],"answer":2,"explanation":"O artigo afirma que, mesmo sem tocar em nenhum botão, entender o conceito orienta o uso e permite regular o comportamento no próprio pedido conforme a tarefa."},{"question":"Para o status semanal de fluxo que vai para os stakeholders, qual comportamento da IA o artigo recomenda buscar?","options":["Consistência: mesmo formato e tom toda semana, para o stakeholder não gastar energia decifrando.","Variedade máxima: um formato diferente a cada envio para não cansar.","Aleatoriedade, para descobrir novos jeitos de apresentar os números.","Não importa o comportamento, já que o texto é sempre revisado."],"answer":0,"explanation":"O artigo separa os dois tipos de tarefa: textos recorrentes como o status semanal pedem consistência, porque um formato diferente a cada envio faz o stakeholder gastar energia decifrando em vez de lendo."},{"question":"Você pede à IA '10 formatos diferentes e criativos de retrospectiva para um time desanimado'. Segundo o artigo, qual comportamento você quer aqui?","options":["Consistência, para todas as sugestões saírem no mesmo padrão.","Variedade: quanto mais diferentes entre si as sugestões, melhor — a divergência criativa é o próprio objetivo.","O menor número possível de opções para poupar tempo.","Que a IA repita ideias conhecidas para não arriscar."],"answer":1,"explanation":"O artigo classifica dinâmicas de retro como divergência criativa, em que a variedade é o objetivo — cada sugestão vindo de um canto diferente."},{"question":"O artigo amarra um cuidado final sobre temperatura e alucinação. Qual é?","options":["Quanto mais 'solta' a IA está, menor a chance de ela inventar detalhes.","A temperatura alta garante números mais precisos.","Quanto mais 'solta' a IA está, maior a chance de inventar detalhes — então, para textos com números, datas e compromissos, fique no modo consistente e confira as fontes.","Textos com datas e números devem sempre usar o modo mais criativo."],"answer":2,"explanation":"O artigo avisa que a IA mais 'solta' inventa mais detalhes, então para textos com números, datas e compromissos vale o modo consistente e conferir as fontes antes de enviar."}],
  "reasoning-models": [{"question":"Segundo o artigo, o que caracteriza os modelos de raciocínio (reasoning)?","options":["Respondem sempre mais rápido e mais barato que os modelos comuns.","Dedicam tempo para 'pensar' passo a passo antes de responder: demoram e custam mais, em troca de mais acerto em questões complexas.","Não cometem erros nem alucinam, porque raciocinam.","Só funcionam para tarefas simples de formatação de texto."],"answer":1,"explanation":"O artigo define os modelos de raciocínio como aqueles que analisam o problema passo a passo, demorando e custando mais em troca de mais acerto em questões complexas."},{"question":"Qual analogia o artigo usa para os dois modos de resposta da IA?","options":["A diferença entre uma resposta rápida na daily e um workshop de análise profunda: cada um tem sua hora.","A diferença entre uma bicicleta e um avião.","A diferença entre um estagiário e um diretor.","A diferença entre um quadro branco cheio e um vazio."],"answer":0,"explanation":"O artigo compara os modos à diferença entre uma resposta rápida na daily e um workshop de análise de causa raiz: os dois têm valor, o desperdício está em trocar um pelo outro."},{"question":"Segundo o artigo, quais são os dois desperdícios que entender os modos de raciocínio ajuda a evitar?","options":["Usar IA demais e usar IA de menos.","Escrever prompts longos e escrever prompts curtos.","Pagar caro por profundidade em tarefas banais e aceitar respostas rasas em análises que mereciam rigor.","Colar muito contexto e colar pouco contexto."],"answer":2,"explanation":"O artigo cita os dois erros clássicos: pagar caro por profundidade em tarefas banais e aceitar respostas rasas em análises que exigiam o modo de raciocínio."},{"question":"Você quer entender por que o lead time subiu nos últimos seis meses, desde a reorganização dos times. Segundo o artigo, qual é a melhor forma de usar o modo de raciocínio?","options":["Pedir só a primeira explicação plausível para agilizar a review.","Colar os dados de fluxo e o contexto e pedir para levantar hipóteses, avaliar cada uma contra os dados e listar que informação faltaria para confirmar.","Usar o modo rápido, porque análise de fluxo é tarefa banal.","Deixar a IA decidir sozinha a causa e comunicar aos stakeholders."],"answer":1,"explanation":"O artigo mostra o uso do modo de raciocínio para cruzar informações: levantar hipóteses, avaliar cada uma contra os dados e apontar o que falta para confirmar — um raciocínio auditável."},{"question":"O artigo dá um 'truque de facilitador' para usar com o modo de raciocínio. Qual é, e por quê?","options":["Pedir a resposta mais curta possível, para economizar tokens.","Aceitar a conclusão da IA sem questionar, porque o raciocínio parece impecável.","Pedir para a IA usar sempre o modelo mais caro, garantindo acerto.","Pedir 'liste as suposições que você fez', porque análise convincente não é análise correta — a premissa falsa precisa ser testada pelo time na retro."],"answer":3,"explanation":"O artigo ensina a pedir as suposições feitas, pois a IA pode encadear lógica impecável sobre uma premissa falsa; essas suposições viram pauta do teste de realidade com o time."}],
  "multimodal": [{"question":"Segundo o artigo, o que caracteriza um modelo multimodal?","options":["Ele processa mais de um tipo de entrada além de texto: enxerga imagens, lê PDFs e interpreta áudio.","Ele responde em vários idiomas ao mesmo tempo.","Ele roda em vários dispositivos simultaneamente.","Ele combina vários modelos pequenos numa única resposta."],"answer":0,"explanation":"O artigo define modelo multimodal como aquele que processa mais de um tipo de entrada além do texto — imagens, PDFs, áudio — permitindo mandar um print e perguntar o que há nele."},{"question":"Segundo o artigo, que tipo de trabalho a IA multimodal 'aposenta' para o Agilista?","options":["A facilitação das cerimônias presenciais.","A priorização do backlog junto com o PO.","O trabalho de escriba: digitar manualmente para o Jira ou o Confluence o conteúdo de post-its, prints e PDFs.","A análise de métricas de fluxo no eazyBI."],"answer":2,"explanation":"O artigo diz que a IA multimodal aposenta boa parte do trabalho de escriba: o que antes era 'transcrever à mão' vira 'anexar e pedir'."},{"question":"Depois de uma planning presencial, você fotografa a parede de post-its. Segundo o artigo, qual pedido é o mais bem desenhado?","options":["'Diga se a planning foi produtiva com base nesta foto.'","'Transcreva cada post-it como um item de lista, agrupado por coluna; marque com [?] os ilegíveis.'","'Invente os post-its que devem ter faltado na parede.'","'Descreva as cores dos post-its em ordem alfabética.'"],"answer":1,"explanation":"O artigo apresenta esse pedido como exemplo: transcrever cada post-it agrupado por coluna e marcar os ilegíveis, deixando o resultado pronto para colar no Jira."},{"question":"O artigo aponta dois cuidados ao usar IA multimodal com fotos de dinâmicas. Quais são?","options":["Usar a câmera de maior resolução e enviar em preto e branco.","Conferir a transcrição contra a foto (a IA pode 'ler' errado um post-it borrado com a mesma confiança) e checar se a ferramenta é aprovada, pois fotos carregam nomes e temas sensíveis.","Enviar sempre em lote e nunca revisar, para ganhar tempo.","Cortar as bordas da foto e traduzir tudo para inglês antes."],"answer":1,"explanation":"O artigo cita conferir a transcrição contra a foto (a IA inventa a versão de um post-it borrado com confiança) e lembrar que fotos de dinâmicas carregam nomes e temas sensíveis — vale perguntar se a ferramenta é aprovada."},{"question":"Segundo o artigo, o print de um dashboard de fluxo vira o quê quando enviado à IA multimodal?","options":["Uma decisão final e automática sobre mudar o processo do time.","Um relatório oficial pronto para enviar aos stakeholders sem revisão.","Um primeiro rascunho de leitura ('o que este gráfico sugere?') que o Agilista refina com seu conhecimento do contexto.","Um arquivo que a IA arquiva no Confluence automaticamente."],"answer":2,"explanation":"O artigo descreve o print do dashboard virando um primeiro rascunho de leitura que o Agilista refina com o conhecimento do contexto — a IA faz a primeira passada, o julgamento fica com a pessoa."}],
  "hallucination": [{"question":"Segundo o artigo, o que é uma alucinação da IA?","options":["Um erro de digitação no texto gerado.","Quando a IA inventa uma informação plausível — uma data, um número, uma decisão que nunca aconteceu — e afirma com total confiança.","Quando a IA se recusa a responder por falta de contexto.","Quando a IA repete a mesma frase várias vezes."],"answer":1,"explanation":"O artigo define alucinação como a IA gerando informação plausível mas falsa (data, número, decisão inexistente) com total convicção, porque prevê texto provável e não verdade."},{"question":"Por que o artigo diz que alucinação é 'O conceito mais importante' especialmente para o Agilista?","options":["Porque o Agilista programa a IA e precisa corrigir o código.","Porque alucinação torna a IA inútil para qualquer tarefa.","Porque o Agilista escreve para os outros (resumos executivos, comunicados) e um dado inventado que passa pelo texto dele queima a credibilidade dele, não a da IA.","Porque alucinação só acontece em ferramentas não aprovadas."],"answer":2,"explanation":"O artigo destaca que, como o Agilista vive de comunicação com stakeholders, um número inventado que chega a um diretor queima a credibilidade dele — por isso alucinação define como ele pode usar IA."},{"question":"Segundo o artigo, onde mora o maior risco de alucinação?","options":["Nos detalhes específicos — datas, percentuais, nomes, decisões — e não nas frases genéricas.","Nas frases genéricas e de opinião.","Nos títulos e cabeçalhos do documento.","Somente em textos muito longos."],"answer":0,"explanation":"O artigo aponta que o risco mora nos detalhes específicos (datas, percentuais, nomes, decisões), justamente o que a IA inventa com mais desenvoltura e o que o stakeholder confere."},{"question":"O artigo alerta sobre uma 'armadilha sutil': a pergunta carregada. Se você pergunta 'por que o time atrasou a entrega?', o que a IA tende a fazer?","options":["Recusar a pergunta por falta de dados.","Pedir a ata da retro antes de responder.","Responder apenas 'não sei'.","Construir uma explicação convincente para o atraso, mesmo que o atraso não tenha existido nos dados fornecidos."],"answer":3,"explanation":"O artigo alerta que uma pergunta que já pressupõe a resposta leva a IA a fabricar uma ficção bem escrita — pergunta carregada, ficção bem escrita."},{"question":"Segundo o artigo, qual é a rotina de defesa em duas camadas contra alucinação?","options":["Antes: ancorar a IA em material real (colar dados do Jira, ata, Confluence); depois: conferir todo fato específico contra a fonte antes de enviar.","Antes: usar o modelo mais caro; depois: enviar direto porque ele não erra.","Antes: escrever prompts curtos; depois: confiar na primeira resposta.","Antes: aumentar a temperatura; depois: pedir para a IA revisar a si mesma."],"answer":0,"explanation":"O artigo descreve a defesa em duas camadas: ancorar a IA em material real antes e conferir cada fato específico contra a fonte antes de enviar — a checagem de dez minutos é o preço da sua assinatura."}],
  "training-inference": [{"question":"Segundo o artigo, qual é a diferença entre treinamento e inferência?","options":["Treinamento é gerar a resposta ao seu prompt; inferência é o modelo aprender com você.","Treinamento é o processo caro em que o modelo aprende padrões dos dados (feito pelas empresas que o criam); inferência é o uso do modelo pronto para gerar resposta, toda vez que você manda um prompt.","São dois nomes para a mesma coisa.","Treinamento acontece a cada conversa; inferência acontece uma vez só."],"answer":1,"explanation":"O artigo define treinamento como o aprendizado caro e único feito pelas empresas criadoras, e inferência como o uso do modelo já pronto a cada prompt."},{"question":"Qual analogia o artigo usa para explicar que o modelo 'aprendeu tudo uma vez e não aprende com as suas conversas'?","options":["Um consultor recém-chegado: brilhante, mas não conhece seu time, seus processos, suas decisões — e esquece tudo ao fim de cada conversa.","Um taxímetro que conta o texto processado.","Um quadro branco que apaga o começo quando lota.","Uma bicicleta que entrega o envelope na esquina."],"answer":0,"explanation":"O artigo compara o modelo a um consultor recém-chegado: brilhante, leu o mundo, mas não conhece a sua empresa e esquece tudo ao fim de cada conversa."},{"question":"Segundo o artigo, quais duas frustrações comuns o conceito de treinamento vs inferência desmonta?","options":["'A IA é lenta demais' e 'a IA é cara demais'.","'A IA não entende português' e 'a IA não lê imagens'.","'Já expliquei isso mil vezes para a IA' e 'vamos usando que ela aprende com a gente'.","'A IA inventa dados' e 'a IA não sabe programar'."],"answer":2,"explanation":"O artigo desmonta duas frustrações: a IA não guarda a lição de uma conversa para a outra, então 'já expliquei mil vezes' segue valendo e 'ela aprende com a gente' não acontece."},{"question":"Segundo o artigo, por que os hábitos de documentação viram uma vantagem competitiva com IA?","options":["Porque a IA acumula conhecimento sobre o time a cada conversa e dispensa documentos.","Porque documentar treina o modelo permanentemente.","Porque quem documenta menos consegue prompts mais curtos.","Porque, como a ferramenta não acumula contexto, quem mantém boas páginas no Confluence tem 'pacotes de contexto' prontos para colar no início de cada conversa."],"answer":3,"explanation":"O artigo argumenta que, como o modelo não acumula conhecimento do seu contexto, quem documenta bem (processo, acordos, glossário) tem pacotes de contexto prontos para colar — o time que documenta bem conversa melhor com IA."},{"question":"Você cola a página do Confluence do SEU processo de discovery e a resposta melhora. Segundo o artigo, o que de fato aconteceu?","options":["Você não 'treinou' a IA; você a informou numa conversa específica — amanhã, num chat novo, ela volta à estaca zero.","Você treinou permanentemente o modelo para conhecer sua empresa.","A IA memorizou seu processo e nunca mais vai precisar da página.","A IA passou a compartilhar seu processo com outros usuários."],"answer":0,"explanation":"O artigo distingue informar de treinar: colar a página informa uma conversa específica; num chat novo a IA volta à estaca zero e será preciso colar de novo."}],
  "foundation-models": [{"question":"Segundo o artigo, qual é a diferença central entre modelos de fundação fechados e abertos, na ótica do Agilista?","options":["Fechados são gratuitos e abertos são pagos.","Quando o modelo é acessado como serviço externo, o texto que você envia sai da empresa; quando roda dentro de casa, fica.","Fechados só leem texto e abertos leem imagens.","Abertos são sempre mais inteligentes que os fechados."],"answer":1,"explanation":"O artigo resume o fio que cai no colo do Agilista: modelo como serviço externo faz o dado sair da empresa; modelo rodando dentro de casa mantém o dado dentro."},{"question":"Segundo o artigo, qual é a pergunta que o Agilista precisa fazer antes de colar algo numa ferramenta de IA?","options":["'Qual modelo é o mais rápido?'","'Quantos parâmetros esse modelo tem?'","'Para onde vai o dado que eu colo nessa ferramenta?'","'Esse modelo é aberto ou fechado tecnicamente?'"],"answer":2,"explanation":"O artigo diz que a escolha de arquitetura é dos times técnicos, mas o fio que é do Agilista se resume à pergunta 'para onde vai o dado que eu colo nessa ferramenta?'."},{"question":"Por que o artigo diz que essa preocupação com dados é 'especialmente sua' (do Agilista)?","options":["Porque o Agilista é o dono técnico da infraestrutura de IA.","Porque só o Agilista tem acesso às ferramentas de IA da empresa.","Porque o Agilista decide qual modelo a empresa vai comprar.","Porque poucas pessoas manuseiam material tão sensível: retros com desabafos, avaliações, PDPs, conflitos entre pessoas, discussões de reestruturação."],"answer":3,"explanation":"O artigo destaca que o Agilista maneja material especialmente sensível — retros, avaliações, PDPs, conflitos — que não pode virar entrada de qualquer ferramenta só por conveniência."},{"question":"O artigo diz que o cuidado com dados sensíveis 'não é motivo para paralisia, mas para método'. Quais são as duas verificações antes de usar IA com material de trabalho?","options":["Essa ferramenta é aprovada pela empresa? E este conteúdo específico precisa ir com nomes e detalhes, ou uma versão anonimizada resolve?","Esse modelo é o mais barato? E ele responde rápido o suficiente?","Quantos tokens isso vai custar? E cabe na janela de contexto?","O time já usou essa ferramenta antes? E o stakeholder aprovou?"],"answer":0,"explanation":"O artigo lista as duas verificações: se a ferramenta é aprovada e se o conteúdo precisa ir com nomes/detalhes ou uma versão anonimizada resolve — na maioria dos casos, isso destrava o uso em vez de proibi-lo."},{"question":"Você quer usar IA para consolidar as retros do trimestre, mas as atas têm desabafos e temas delicados de pessoas nomeadas. Segundo o artigo, qual efeito colateral valioso surge ao fazer a pergunta 'os dados saem daqui?' em voz alta numa reunião?","options":["O time passa a usar menos IA por medo.","A ferramenta bloqueia automaticamente conteúdo sensível.","Você normaliza a pergunta, e o time inteiro aprende a fazê-la antes de colar o próximo documento em qualquer ferramenta nova.","A liderança assume a responsabilidade por qualquer vazamento."],"answer":2,"explanation":"O artigo aponta o efeito colateral: fazer a pergunta em voz alta a normaliza, e o time inteiro aprende a fazê-la antes de colar o próximo documento em qualquer ferramenta nova."}],
  "copilots": [{"question":"Segundo o artigo, quando rascunhar código fica barato e rápido com copilots, o que acontece com o trabalho no fluxo do time?","options":["O trabalho desaparece e o time fica ocioso.","O trabalho não desaparece: muda de lugar — revisar o que foi gerado vira o novo gargalo, porque produzir ficou fácil e conferir continua custando atenção.","Todas as etapas aceleram na mesma proporção.","O gargalo some porque a IA também revisa sozinha."],"answer":1,"explanation":"O artigo explica que gerar código barato não elimina o trabalho, apenas o desloca: a revisão vira o novo gargalo, uma coluna à frente."},{"question":"Um mês após o time adotar um copilot, o eazyBI mostra que o tempo de desenvolvimento caiu mas a fila de revisão dobrou. Segundo o artigo, como o Agilista deve ler isso?","options":["Como uma aceleração pura: o time agora entrega o dobro.","Como erro de medição do eazyBI que deve ser ignorado.","Como motivo para remover a etapa de revisão do fluxo.","Como o gargalo mudando de lugar: o cycle time total quase não mudou, só trocou de etapa — history a levar aberta para a retro."],"answer":3,"explanation":"O artigo mostra que a queda no desenvolvimento com a fila de revisão dobrando significa que o gargalo trocou de etapa e o cycle time total mal mudou — algo a levar aberto para a retro, não escondido na média."},{"question":"Um stakeholder sugere que 'com IA agora dá para prometer o dobro'. Segundo o artigo, qual é a resposta honesta do Agilista?","options":["'Sim, a IA dobra a capacidade de entrega de forma linear.'","'A digitação acelerou; o entendimento do problema, a revisão e a validação, não — o ganho é real, mas não é linear.'","'Não há ganho nenhum, é só marketing de ferramenta.'","'Depende só de comprar mais licenças do copilot.'"],"answer":1,"explanation":"O artigo alerta que a digitação acelerou mas o entendimento, a revisão e a validação não — prometer linearidade é fabricar frustração para dois meses depois."},{"question":"Segundo o artigo, qual metáfora descreve o copilot e o que ela implica para o fluxo?","options":["Um oráculo confiável, cujo código pode ir direto para produção.","Uma calculadora exata, que nunca erra e dispensa revisão.","O estagiário talentoso: excelente para rascunhar, péssimo para receber confiança cega — quem assina embaixo continua sendo o dev.","Um substituto do dev, que elimina a necessidade de revisão humana."],"answer":2,"explanation":"O artigo chama o copilot de estagiário talentoso: ótimo para rascunhar, mas quem assina embaixo continua sendo o dev — por isso a revisão continua custando atenção humana."},{"question":"Diante do gargalo de revisão revelado na retro, qual decisão de fluxo o artigo mostra o time tomando?","options":["Ajustar o limite de WIP e criar um combinado novo: revisar antes de puxar item novo.","Aumentar as metas de entrega para aproveitar a aceleração.","Comprar mais licenças do copilot para gerar ainda mais código.","Remover a revisão para desafogar a fila."],"answer":0,"explanation":"O artigo mostra o time decidindo ajustar o limite de WIP e criar um combinado de revisar antes de puxar item novo — o Agilista transformou a adoção da ferramenta em aprendizado de fluxo."}],
  "slm": [{"question":"Segundo o artigo, o que é um SLM (Small Language Model)?","options":["Um modelo que só funciona em inglês.","Um modelo de linguagem menor, mais rápido e barato, que pode até rodar localmente — troca parte da capacidade geral por eficiência e privacidade.","Um modelo que aprende com cada conversa do time.","Uma versão de demonstração, sem uso em produção."],"answer":1,"explanation":"O artigo define SLM como um modelo menor, mais rápido e barato, capaz de rodar on-device, que troca parte da capacidade geral por eficiência e privacidade."},{"question":"Qual analogia o artigo usa para a escolha entre um modelo grande e um pequeno?","options":["'Não use um canhão para matar uma mosca' — para entregar um envelope na esquina, a bicicleta ganha do caminhão.","'Quem tem boca vai a Roma.'","'Dois pesos, duas medidas.'","'Um passo de cada vez.'"],"answer":0,"explanation":"O artigo resume o tema com 'não use um canhão para matar uma mosca' e a versão útil: para entregar um envelope na esquina, a bicicleta ganha do caminhão."},{"question":"Por que o artigo diz que o custo da IA 'não é rodapé de planilha' para o Agilista?","options":["Porque a IA é sempre gratuita e o custo é irrelevante.","Porque o custo é fixo e não afeta o caso de negócio.","Porque em produtos com volume alto de chamadas, o custo pode ser a diferença entre um caso de negócio que fecha e um que não fecha.","Porque o custo só importa para a área financeira, não para o time."],"answer":2,"explanation":"O artigo alerta que em produtos com alto volume de chamadas o custo pode decidir se o caso de negócio fecha, transformando o Agilista de espectador em facilitador dessa conversa."},{"question":"No planejamento de uma iniciativa, o custo estimado da IA quase inviabiliza o caso de negócio (os números assumem o modelo mais poderoso para tudo). Um dev diz que 'um modelo menor talvez resolva a parte simples'. Segundo o artigo, como o Agilista facilita a quebra?","options":["Descarta a iniciativa, já que o custo é alto.","Aprova o modelo caro para tudo, para não arriscar qualidade.","Manda o dev decidir sozinho sem envolver o time.","Ajuda a separar quais tarefas são estreitas e repetitivas (classificar, extrair, padronizar) das que exigem o modelo caro, e propõe rodar a parte simples no modelo pequeno e medir por duas sprints."],"answer":3,"explanation":"O artigo mostra o Agilista facilitando a quebra: separar tarefas repetitivas das que exigem o modelo caro e transformar a primeira fatia em 'rodar a parte simples no modelo pequeno e medir a qualidade real por duas sprints'."},{"question":"Segundo o artigo, com qual prática que o Agilista já defende a escolha entre modelos combina?","options":["Fatiar para aprender: uma fatia barata primeiro, medição real depois, upgrade só se os dados pedirem — a mesma lógica do MVP.","Estimar tudo em detalhe antes de começar qualquer coisa.","Escolher a tecnologia no PowerPoint, antes de qualquer experimento.","Evitar experimentos para não gastar o orçamento de IA."],"answer":0,"explanation":"O artigo diz que 'qual modelo usar' pode ser decidido por experimento: fatia barata, medição real, upgrade só se os dados pedirem — a mesma lógica do MVP aplicada à infraestrutura de IA."}],
  "when-rag-vs-ft": [{"question":"Segundo o artigo, quais são os três jeitos de fazer a IA trabalhar com o conhecimento da empresa?","options":["Comprar, alugar ou construir o modelo do zero.","Explicar na hora (colar a informação no pedido), dar um manual para consultar (a IA busca nos documentos) ou mandar fazer um curso (treinar uma versão especializada).","Usar modelo grande, médio ou pequeno.","Prompt curto, prompt médio ou prompt longo."],"answer":1,"explanation":"O artigo apresenta os três caminhos: prompt (explicar na hora), RAG (o manual consultável) e fine-tuning (treinar uma versão especializada — caro e demorado)."},{"question":"Segundo o artigo, por que entender que são 'três caminhos com tamanhos diferentes' importa para o Agilista, mesmo sem ele escolher a técnica?","options":["Porque muda como ele ajuda a quebrar e priorizar iniciativas de IA, dando um mapa para dimensioná-las.","Porque ele precisa configurar cada técnica no sistema.","Porque ele decide sozinho qual técnica o time vai usar.","Porque as três têm exatamente o mesmo custo e prazo."],"answer":0,"explanation":"O artigo diz que os três caminhos dão ao Agilista um mapa mental para dimensionar iniciativas de IA sem entender a engenharia — muda como ele quebra e prioriza."},{"question":"Segundo o artigo, quão diferentes são os prazos dos três caminhos?","options":["Os três levam mais ou menos o mesmo tempo.","Explicar na hora leva meses; treinar leva dias.","Explicar na hora se testa em dias; montar o 'manual consultável' leva semanas; treinar uma versão especializada custa meses e muito dinheiro.","Todos exigem no mínimo dois trimestres."],"answer":2,"explanation":"O artigo detalha os tamanhos: prompt se testa em dias, RAG leva semanas e fine-tuning custa meses e muito dinheiro."},{"question":"Segundo o artigo, qual critério simples indica que o 'manual consultável' (RAG) faz mais sentido que treinar o modelo?","options":["Quando o time quer economizar tokens.","Quando a informação muda toda hora (políticas, preços, catálogo), porque atualizar documento é fácil e re-treinar é caro.","Quando o problema é só 'pedir melhor'.","Quando não há documentos disponíveis."],"answer":1,"explanation":"O artigo diz que, se a informação muda toda hora, o manual consultável ganha, porque atualizar documento é fácil e re-treinar é caro."},{"question":"Na quebra da iniciativa 'assistente que responde dúvidas sobre políticas internas', o time diz que vai 'consultar documentos'. Segundo o artigo, qual gancho de facilitação o Agilista usa?","options":["'Vamos treinar uma versão especializada do modelo primeiro.'","'Melhor esperar seis meses e entregar tudo de uma vez.'","'Vamos usar o modelo mais caro para garantir qualidade.'","'Dá para começar com só 10 documentos, os mais consultados pelo RH, e medir se as respostas prestam?' — transformando o épico de seis meses em fatias com medição."],"answer":3,"explanation":"O artigo mostra o Agilista usando o gancho de começar com 10 documentos e medir, transformando um épico de seis meses numa sequência de fatias com aprendizado, em vez de uma aposta cega de dois trimestres."}],
  "harness-conceito": [{"question":"Segundo o artigo, o que é um harness e qual é a relação dele com o modelo (LLM)?","options":["É toda a estrutura em volta do modelo (montar prompt, injetar contexto, chamar ferramentas, tentar de novo, validar) — o modelo é só o motor; o harness é o chassi, a direção e os freios.","É um tipo mais avançado de modelo de IA.","É a interface visual onde o usuário digita o prompt.","É o processo de treinar o modelo com dados da empresa."],"answer":0,"explanation":"O artigo define harness como toda a estrutura que envolve o modelo para torná-lo útil: o LLM é o motor e o harness é o chassi, a direção e os freios."},{"question":"Segundo o artigo, contra qual expectativa perigosa em planning entender o harness protege o Agilista?","options":["'A IA é cara demais para o time.'","'O ChatGPT já existe, então é rápido' / 'é só plugar a IA'.","'A IA nunca vai funcionar no nosso contexto.'","'Precisamos treinar nosso próprio modelo do zero.'"],"answer":1,"explanation":"O artigo diz que entender o harness blinda contra a expectativa mais comum e perigosa em planning: 'o ChatGPT já existe, então é rápido'."},{"question":"Na retro, o time desabafa que 'a feature de IA é imprevisível e a gente perde tempo demais com ela'. Segundo o artigo, o que um Agilista que conhece o harness faz?","options":["Anota 'melhorar a IA' como ação da retro.","Registra que o modelo é ruim e sugere trocar de fornecedor.","Puxa a pergunta certa: 'dos últimos dez bugs dessa feature, quantos eram do modelo em si e quantos eram do código em volta — contexto, ferramentas, validação?'.","Remove a feature do backlog para evitar retrabalho."],"answer":2,"explanation":"O artigo mostra o Agilista puxando a pergunta que separa o modelo do código em volta, transformando 'melhorar a IA' num backlog endereçável de itens pequenos que cabem numa sprint."},{"question":"Segundo o artigo, por que um card no Jira escrito como 'IA responde errado' é um problema de fluxo disfarçado?","options":["Porque a IA nunca responde errado, então o card é falso.","Porque cards de IA não podem entrar no Jira.","Porque exige aprovação da liderança para ser priorizado.","Porque é impossível de estimar e priorizar, e tende a rolar de sprint em sprint — até virar 'montagem de contexto não inclui histórico da conversa', com escopo, dono e estimativa possíveis."],"answer":3,"explanation":"O artigo explica que 'IA responde errado' é impossível de estimar e priorizar; entender o harness reescreve o card com escopo, dono e estimativa claros."},{"question":"O PO chega na planning querendo 'um chatbot de atendimento em uma sprint, afinal a IA já está pronta'. Segundo o artigo, como o Agilista conduz a conversa?","options":["Facilita a quebra do harness em histórias: conectar com dados dos clientes, tratar quando a IA não sabe responder, conferir respostas antes de enviar, registrar erros — saindo do 'é só plugar a IA' para um plano realista.","Aceita a estimativa de uma sprint, já que a IA está pronta.","Diz que chatbots com IA são impossíveis de construir.","Manda o time chamar o modelo e entregar o que der."],"answer":0,"explanation":"O artigo mostra o Agilista facilitando a quebra do harness em histórias (dados, tratamento de falha, validação, registro de erros), tirando a conversa do 'é só plugar' para um plano realista — o grosso do trabalho é o harness, não chamar o modelo."}],
  "quantization-distillation": [{"question":"Um modelo na versão 'mini' (obtido por quantização ou destilação) é, na prática:","options":["Sempre pior em tudo, então nunca deve ser usado em produto","Mais barato e rápido, mas com alguma perda de capacidade que costuma aparecer nos casos mais difíceis","Idêntico ao modelo maior, apenas com outro nome comercial","Mais lento, porém mais preciso do que o modelo original"],"answer":1,"explanation":"As versões mini/lite/turbo trocam capacidade por eficiência, e a perda se concentra justamente nos casos difíceis onde ninguém olha primeiro."},{"question":"Na planning, o time propõe trocar o modelo do produto pela versão mini para cortar 80% do custo e alguém diz que 'é só mudar uma configuração'. Como agilista, sua contribuição é:","options":["Aprovar na hora, já que a economia é grande e a mudança é trivial","Vetar a proposta, porque mexer no modelo é sempre arriscado demais","Perguntar 'como vamos saber que a qualidade não caiu?' e transformar a revalidação em item de backlog visível","Encaminhar a decisão inteira para o time técnico, sem participar"],"answer":2,"explanation":"O papel do agilista é transformar pressa em trabalho visível: a pergunta sobre qualidade faz nascer o item de revalidação no board, em vez de virar surpresa em produção."},{"question":"Por que 'trocar o modelo pela versão mini' não é um item de cinco minutos no refinamento?","options":["Porque exige comprar novos servidores caros antes de configurar","Porque o time precisa reescrever todo o produto do zero","Porque a troca é irreversível e não pode ser testada","Porque carrega trabalho invisível de revalidação, que é o que estoura sprint, fura previsão e vira incidente"],"answer":3,"explanation":"A 'configuração' muda o comportamento do produto e esconde a perda onde ninguém olha; esse trabalho de revalidação precisa aparecer no backlog."},{"question":"A resposta madura para a troca de modelo raramente é binária. O que isso significa para o board?","options":["Que decisões por segmento (ex.: mini no FAQ, modelo maior no pagamento) geram mais de uma história, com dependências que você quer explícitas","Que basta uma única história genérica de 'migrar modelo'","Que a decisão deve ficar só na cabeça de uma pessoa para agilizar","Que o time deve sempre escolher o modelo mais barato para todos os fluxos"],"answer":0,"explanation":"Decidir por segmento gera múltiplas histórias com dependências; o agilista quer isso no board, não na cabeça de alguém."},{"question":"Semanas depois, a diretoria pergunta por que a economia demorou um sprint a mais. Qual resposta reflete um bom trabalho de facilitação?","options":["'O time é lento e não priorizou a economia'","'Ainda estamos avaliando, sem previsão'","'Confiamos que os testes passaram e migramos tudo de uma vez'","'Porque o time descobriu, antes do cliente, onde o modelo barato errava — e aqui estão os números por categoria'"],"answer":3,"explanation":"A validação estratificada com critério de aceite claro é a diferença entre economia planejada e surpresa em produção — e dá resposta com dado."}],
  "benchmarks": [{"question":"Na ótica do agilista, a melhor analogia para um benchmark de modelo (MMLU, SWE-bench) é:","options":["Um contrato que garante o funcionamento no seu produto","A nota de uma empresa no Glassdoor: um sinal útil, mas que não garante que vai funcionar para o SEU caso","Uma certificação obrigatória para usar o modelo","Uma métrica de fluxo do próprio time, como o cycle time"],"answer":1,"explanation":"Benchmark é a prova genérica de outra pessoa: filtra candidatos, mas não aprova ninguém no seu produto, idioma e domínio."},{"question":"A liderança vê a manchete 'modelo X é o número 1 do ranking' e pergunta por que o time ainda não migrou. A facilitação madura é:","options":["Parar o roadmap e sair correndo atrás do campeão da vez","Dizer 'não' à liderança e encerrar o assunto","Acordar um spike com prazo fechado para testar o modelo com casos reais e decidir com evidência","Migrar imediatamente, confiando na nota do ranking"],"answer":2,"explanation":"O entusiasmo vira um experimento com timebox: ninguém precisa dizer não, e a decisão sai com dados em vez de manchete."},{"question":"Por que proteger a previsibilidade do time contra o ciclo do hype é trabalho de facilitação?","options":["Porque cada manchete pode virar replanejamento que faz o time abandonar o que estava fazendo","Porque benchmarks nunca têm valor algum e devem ser ignorados","Porque o agilista deve escolher o modelo técnico sozinho","Porque migrar de modelo é proibido durante uma sprint"],"answer":0,"explanation":"Sem entender o que um benchmark mede, a pressão do hype vira replanejamento; entendendo, ela vira uma investigação curta com critério de saída."},{"question":"Que prática faz 'avaliar modelo novo' deixar de ser um épico imprevisível e virar item pequeno e recorrente?","options":["Confiar sempre no LMArena e migrar por votos de usuários","Manter um golden dataset, que transforma cada lançamento barulhento em rotina de uma tarde","Proibir qualquer avaliação de modelos novos","Esperar a diretoria decidir por conta própria"],"answer":1,"explanation":"Com um golden dataset de casos reais, testar o modelo da vez vira uma tarefa pequena que encaixa sem furar a sprint."},{"question":"Duas semanas após um spike de avaliação, qual resposta à diretoria mostra decisão com evidência?","options":["'Estamos avaliando, sem previsão'","'Confiamos no ranking, então vamos migrar tudo'","'O time é resistente a mudanças'","'Migramos a triagem de chamados, seguramos a geração de testes; aqui estão os dados, categoria por categoria'"],"answer":3,"explanation":"A decisão sai por segmento e com número, mantendo o roadmap intacto — reunião curta, decisão registrada."}],
  "prompt-engineering": [{"question":"Engenharia de prompt, na visão do artigo, é:","options":["Adivinhar a 'frase mágica' que faz a IA acertar por sorte","Montar deliberadamente as peças — papel, contexto, tarefa, restrições, formato — com iteração e medição","Escrever o prompt mais curto possível para economizar tokens","Uma habilidade exclusiva de quem programa"],"answer":1,"explanation":"Não é sorte nem jeito com tecnologia: é engenharia, estruturar as peças para que a saída venha no padrão do time de primeira."},{"question":"Antes do refinamento de um épico de integração de pagamentos, qual estrutura de prompt reflete boa engenharia de prompt?","options":["'Quebre esse épico em histórias, por favor'","'Me ajude com pagamentos'","[Papel] Agile Coach + [Contexto] épico com 3 times + [Tarefa] quebrar em histórias + [Restrições] entregável em uma sprint com dependências + [Formato] tabela","'Faça o que você achar melhor com esse épico'"],"answer":2,"explanation":"A anatomia completa (papel, contexto, tarefa, restrições, formato) entrega um rascunho no padrão do time, com 70% do trabalho estruturado."},{"question":"Por que o artigo recomenda tratar bons prompts como ativos, e não como achados de ocasião?","options":["Porque prompts caros só podem ser usados uma vez","Porque a IA esquece prompts antigos automaticamente","Porque cada pessoa deve escrever seu próprio prompt do zero toda semana","Porque guardá-los (como templates no Confluence) faz o time inteiro herdar o melhor pedido já feito — padronização de processo"],"answer":3,"explanation":"Escrever uma vez com capricho e guardar onde o time encontra evita que cada um reinvente o pedido — é padronização, a praia do agilista."},{"question":"Qual pedido extra 'multiplica o valor' de um prompt de quebra de épico no refinamento?","options":["'Liste as suposições que você fez sobre o épico' — elas costumam ser ótimas perguntas de refinamento","'Escreva o máximo de histórias possível, sem limite'","'Estime cada história em story points'","'Escreva tudo em inglês para ficar mais técnico'"],"answer":0,"explanation":"Pedir as suposições da IA revela pontos cegos que viram perguntas objetivas de refinamento."},{"question":"Com um rascunho de 70% pronto vindo da IA, para que o agilista usa a hora de reunião?","options":["Para reformatar o texto que a IA gerou","Para o que exige gente: discutir prioridade, riscos e o que ficou de fora","Para reescrever tudo do zero, pois a IA erra sempre","Para estimar as histórias em vez do time"],"answer":1,"explanation":"A engenharia de prompt reduz o retrabalho de edição e libera a reunião para a discussão que só as pessoas podem fazer."}],
  "zero-few-shot": [{"question":"Qual a diferença entre zero-shot e few-shot?","options":["Zero-shot usa modelo grande; few-shot usa modelo mini","Zero-shot é pedir sem exemplos; few-shot inclui alguns exemplos de entrada→saída no prompt para 'mostrar' o padrão","Zero-shot é gratuito; few-shot é pago","Zero-shot só funciona em inglês; few-shot em qualquer idioma"],"answer":1,"explanation":"Few-shot cola exemplos do padrão desejado no próprio prompt, aumentando muito a consistência da saída."},{"question":"Você quer que as histórias do discovery saiam no template da squad. Qual abordagem few-shot o artigo recomenda?","options":["Descrever o template em palavras detalhadas e esperar a IA acertar","Pedir para a IA inventar um formato novo a cada vez","Colar duas histórias bem escritas do Jira e pedir 'seguindo exatamente esse formato, escreva as histórias desta iniciativa'","Treinar (fine-tuning) um modelo só para isso"],"answer":2,"explanation":"Mostrar 2-3 exemplos bons é mais rápido e fiel que descrever o padrão; o refinamento vira revisão de conteúdo, não reescrita de forma."},{"question":"Por que a escolha dos exemplos em few-shot exige o cuidado de 'escolher referência para um colega novo'?","options":["Porque a IA imita com fidelidade, inclusive os defeitos: uma história mal escrita ensina o erro junto com o formato","Porque quanto mais exemplos, sempre melhor o resultado","Porque exemplos ruins deixam a IA mais lenta","Porque a IA descarta exemplos automaticamente se forem ruins"],"answer":0,"explanation":"A imitação é fiel; um exemplo ruim entre os bons ensina o defeito junto com a forma."},{"question":"Qual é o limite honesto do few-shot que o agilista deve lembrar?","options":["Que ele só funciona para relatórios de sprint","Que ele exige aprovação da liderança","Que ele deixa o prompt caro demais para usar","Que exemplos ensinam a forma, não os fatos: a regra de negócio da iniciativa você continua fornecendo à parte"],"answer":3,"explanation":"Few-shot transmite formato e estilo; o conhecimento específico do negócio precisa ser dado como contexto separado."},{"question":"Segundo a regra prática do artigo, quando você deve partir para os exemplos (few-shot)?","options":["Sempre, mesmo antes de tentar sem exemplo","Comece sem exemplo; quando o problema for de forma (formato, nomenclatura, estilo), aí cole exemplos","Nunca, pois zero-shot resolve tudo","Só quando a liderança pedir consistência"],"answer":1,"explanation":"A regra é começar zero-shot e recorrer a exemplos quando a falha for de forma, não de conteúdo."}],
  "chain-of-thought": [{"question":"Chain-of-Thought é a técnica de:","options":["Pedir ao modelo para raciocinar em etapas antes de dar a resposta final","Encadear várias IAs diferentes numa sequência","Guardar o histórico da conversa em cache","Responder sempre com a menor quantidade de palavras"],"answer":0,"explanation":"CoT faz o modelo raciocinar passo a passo, o que melhora tarefas de lógica, matemática e análise."},{"question":"Para o agilista, qual é o principal ganho de receber uma cadeia de raciocínio em vez de um veredito seco sobre 'por que o lead time subiu'?","options":["A resposta fica mais curta e rápida de ler","O raciocínio explícito é auditável: você vê a cadeia de argumentos e pode contestar um elo antes de levar a conclusão adiante","A IA passa a decidir sozinha as ações da retro","Elimina a necessidade de olhar os dados do Jira"],"answer":1,"explanation":"Além de reduzir erro, o rastro auditável deixa você contestar um passo específico antes de repassar a conclusão ao time ou stakeholder."},{"question":"Como o raciocínio explícito muda a natureza da conversa na retro?","options":["Transforma tudo em debate de opinião ('não acho que foi isso')","Faz o time aceitar a conclusão sem questionar","Sai de 'impressões sobre a sprint' para debate de argumento sobre um passo específico verificável","Elimina a necessidade de facilitação"],"answer":2,"explanation":"Uma cadeia explícita permite contestar um elo ('o passo 3 assume code review, mas o gargalo era ambiente') — debate de argumento, não de opinião."},{"question":"Antes da retro você pede à IA: 'agrupe os itens por tipo, compare o cycle time com a média do trimestre, identifique esperas e só então conclua as 3 causas'. Qual ressalva vale dobrada para quem reporta números?","options":["A cadeia pode ser uma narrativa plausível, não o processo real — confira na fonte os elos que citam dados antes de repassar","O CoT nunca erra, então pode repassar direto","Basta pedir uma resposta mais longa para garantir correção","Só modelos de reasoning podem ser auditados"],"answer":0,"explanation":"Um erro no passo 2 contamina tudo depois; o raciocínio auditável só vale se alguém auditar os números na fonte — e esse alguém é você."},{"question":"O que a análise encadeada leva para a retro que um palpite não leva?","options":["Uma decisão automática de ações","Uma lista de culpados do atraso","Menos dados para não confundir o time","Causas que dá para verificar passo a passo, com os dados na mesa"],"answer":3,"explanation":"O time valida a análise elo a elo e discute causas verificáveis, em vez de impressões."}],
  "roles": [{"question":"Na estrutura de papéis da API, o que é o 'system prompt'?","options":["A mensagem pontual que a pessoa digita a cada conversa","A instrução mestra que define comportamento e regras e governa toda a interação","A resposta que o modelo gera","Um registro de log das conversas anteriores"],"answer":1,"explanation":"O system prompt tem peso especial: é o 'acordo de trabalho' da IA, valendo sempre, independentemente de quem está na conversa."},{"question":"Qual analogia o artigo usa para explicar o system prompt ao agilista?","options":["O acordo de trabalho do time: regras combinadas que valem para todos, o tempo todo","Uma tarefa avulsa da sprint","O relatório de fim de sprint","Um impedimento a ser removido"],"answer":0,"explanation":"O que precisa valer sempre vive no system (o acordo); o pedido do momento vive no user."},{"question":"O time vai montar um assistente que ajuda a escrever histórias no Jira. Qual é o papel do agilista nesse desenho?","options":["Escrever o código de integração com o Jira","Escolher qual modelo de IA usar","Dizer quais regras de processo são inegociáveis e devem estar gravadas no system prompt","Nenhum — é decisão puramente técnica"],"answer":2,"explanation":"O desenvolvedor sabe onde colocar a regra; o agilista sabe qual regra proteger — o processo é seu domínio."},{"question":"Depois de definir as cláusulas ('nunca estime; se faltar o objetivo, pergunte antes'), como o agilista as valida?","options":["Confia que o desenvolvedor implementou certo","Espera reclamações do time depois do lançamento","Lê o código do system prompt","Testa como testaria um acordo novo: pede para estimar e confere que recusa; envia demanda sem objetivo e confere que pergunta antes"],"answer":3,"explanation":"Testar o comportamento revela se a regra segura; cláusula vaga não sustenta comportamento, nem em acordo de time nem em system prompt."},{"question":"Qual a 'última lição' do artigo sobre a obediência ao system prompt?","options":["Ela é aprendida e probabilística, não uma garantia — assistente de processo também pede inspeção e adaptação","Ela é uma garantia absoluta: o modelo nunca desvia do system","Ela só falha se o modelo for a versão mini","Ela vale apenas para o primeiro dia de uso"],"answer":0,"explanation":"Como qualquer acordo que o time parou de seguir, revisite as regras quando o comportamento derrapar."}],
  "structured-output": [{"question":"Saída estruturada (JSON mode) é o recurso que:","options":["Faz a IA responder mais rápido","Obriga o modelo a responder seguindo um schema/JSON definido por você, em vez de texto livre","Traduz a resposta para vários idiomas","Reduz o custo por chamada"],"answer":1,"explanation":"O JSON mode garante que a saída seja consumível por código de forma confiável, seguindo o schema definido."},{"question":"Para o agilista, qual é a diferença central que a saída em JSON destrava?","options":["Entre um texto curto e um texto longo","Entre uma IA cara e uma IA barata","Entre 'a IA me deu um texto' (que você reformata à mão) e 'a IA alimentou meu processo' (dado que entra direto na ferramenta)","Entre zero-shot e few-shot"],"answer":2,"explanation":"Dado estruturado vira issues no Jira via importação, linhas de planilha ou campos de dashboard — sem copiar e colar."},{"question":"O artigo diz que o schema funciona como 'um padrão de qualidade embutido'. Como assim?","options":["Exigir 'criterios_aceite' no schema faz nenhum item chegar ao backlog sem esse campo — é o Definition of Ready aplicado na origem","O schema corrige automaticamente o conteúdo errado","O JSON garante que as dependências estão certas","O schema estima as histórias sozinho"],"answer":0,"explanation":"O formato não permite a omissão do campo obrigatório, aplicando o DoR antes mesmo de o item existir no Jira."},{"question":"Você recebe da IA um array JSON impecável para importar em lote no Jira. Qual é o aviso central do artigo?","options":["JSON não pode ser importado no Jira","Só modelos grandes geram JSON válido","O JSON precisa ser reformatado à mão mesmo assim","Conformidade não é correção: o campo preenchido não garante que está certo — revise o conteúdo como revisaria a quebra feita por uma pessoa"],"answer":3,"explanation":"Um dado bonito baixa a guarda; a estrutura elimina retrabalho de formato, mas o julgamento sobre o conteúdo continua sendo seu e do time."},{"question":"Você pede a quebra de uma iniciativa como array JSON com {titulo, descricao, criterios_aceite, dependencia, time_sugerido}. Qual é o ganho de fluxo?","options":["Meia hora de cadastro manual vira um passo automático, e todos os itens seguem o mesmo padrão de campos","A IA cria os cards diretamente sem sua revisão","O refinamento deixa de ser necessário","O custo da chamada cai pela metade"],"answer":0,"explanation":"Você chega ao refinamento com o material pronto para o time criticar, e o padrão uniforme facilita filtrar, medir e reportar depois."}],
  "function-calling": [{"question":"No function calling / tool use, o papel do modelo é:","options":["Executar as funções diretamente no sistema","Decidir QUANDO chamar qual função e com quais parâmetros — mas quem executa é o código que você controla","Criar sozinho novas ferramentas conforme precisa","Substituir o time técnico na operação do Jira"],"answer":1,"explanation":"O modelo não executa: ele pede a execução e você roda. Você controla quais funções existem e o que cada uma pode fazer."},{"question":"Alguém propõe 'um assistente conectado ao Jira'. Segundo o artigo, qual é a pergunta certa do agilista?","options":["'A IA é confiável?'","'Qual modelo tem o melhor benchmark?'","'Quais funções vamos expor, e com quais permissões?'","'Quanto custa a chamada?'"],"answer":2,"explanation":"A fronteira entre o que a IA faz sozinha e o que exige um humano é decisão de processo — território do agilista."},{"question":"Por que 'ler é barato e reversível, mas escrever merece confirmação humana' no desenho de um assistente do Jira?","options":["Porque leitura é lenta e escrita é rápida","Porque só a escrita consome tokens","Porque o modelo não sabe ler issues","Porque escrita muda o estado do backlog (mover card, estimativa), enquanto leitura não altera nada"],"answer":3,"explanation":"É a mesma conversa sobre quem pode mover cards e editar o board — só que agora um dos participantes é um agente."},{"question":"No exemplo, o assistente busca 'o que está bloqueado há mais de 3 dias?'. Por que a resposta é confiável?","options":["Veio de uma ferramenta (buscarIssues com o filtro certo), não da imaginação do modelo","Porque o modelo tem os dados do Jira memorizados","Porque a IA sempre acerta filtros","Porque o assistente moveu os cards para confirmar"],"answer":0,"explanation":"Function calling permite ao modelo consultar a fonte real; a lista veio de uma ferramenta, não de um chute."},{"question":"Meses depois, alguém propõe dar mais autonomia ao assistente. Por que o desenho de permissões torna essa discussão saudável?","options":["Porque a autonomia total já estava garantida desde o início","Porque a discussão vira afrouxar permissões específicas, uma a uma — decisão revisável e auditável, não um salto de fé","Porque só o modelo pode decidir suas permissões","Porque permissões não mudam depois de definidas"],"answer":1,"explanation":"Definir o que a IA lê, comenta e altera transforma a autonomia em uma decisão granular, revisável e auditável."}],
  "react-pattern": [{"question":"O padrão ReAct (Reasoning + Acting) descreve um agente que:","options":["Responde tudo de uma vez, sem usar ferramentas","Alterna entre raciocinar, agir (chamar uma ferramenta) e observar o resultado, em loop, até concluir","Treina o modelo com dados do time","Comprime o prompt para economizar custo"],"answer":1,"explanation":"É o ciclo raciocinar → agir → observar que transforma um LLM que só responde em um agente que executa."},{"question":"O artigo diz que o ciclo do ReAct deve soar familiar ao agilista porque:","options":["É empirismo — o mesmo princípio de inspecionar e adaptar que sustenta qualquer framework ágil","É idêntico a um gráfico de burndown","É uma cerimônia nova a ser adotada","Substitui o papel do Scrum Master"],"answer":0,"explanation":"Um agente ReAct formula hipótese, age, observa e corrige o rumo — exatamente como o time trabalha."},{"question":"Entender o loop do ReAct dá ao agilista o quê, na prática?","options":["A capacidade de construir o orquestrador do agente","O direito de aprovar qualquer automação sozinho","Um mapa mental para facilitar a conversa de viabilidade e avaliar propostas de automação com realismo","A garantia de que o agente nunca vai travar"],"answer":2,"explanation":"Você passa a saber onde um agente pode travar, escolher a ferramenta errada ou entrar em círculos — sem comprar a promessa nem barrar por medo."},{"question":"O time propõe um agente que prepara a daily. Como o agilista facilita a discussão de viabilidade?","options":["Perguntando qual o preço da assinatura da ferramenta","Aprovando, já que economiza tempo do time","Pedindo o código do orquestrador para revisar","Perguntando pelo ciclo: e se um comentário for ambíguo? Quantos passos até desistir e pedir ajuda? Há teto de iterações?"],"answer":3,"explanation":"São as mesmas perguntas que você faria sobre um processo humano sem critério de saída, agora aplicadas ao loop do agente."},{"question":"Por que 'cada volta do loop consome contexto, custo e tempo' importa para o agilista?","options":["Porque faz as perguntas de processo (teto de iterações, critério de parada) se imporem naturalmente na conversa","Porque significa que agentes nunca valem a pena","Porque exige comprar mais servidores","Porque o agente sempre roda a noite inteira"],"answer":0,"explanation":"Sem critério de saída, um agente pode rodar queimando orçamento; o agilista traz limites, casos de 'não sei' e humano no circuito."}],
  "embeddings": [{"question":"O que é um embedding?","options":["Um resumo em texto de um documento","A representação de um texto como vetor de números, de modo que textos com significados parecidos fiquem 'próximos'","Uma cópia comprimida do modelo","Um filtro de busca do Jira"],"answer":1,"explanation":"É como a IA mede similaridade semântica (significado), não só palavras iguais."},{"question":"Por que a busca por embeddings é valiosa para o histórico do time (retros, atas, issues)?","options":["Porque comprime os documentos para ocupar menos espaço","Porque traduz tudo para inglês automaticamente","Porque busca por palavra exata com mais velocidade","Porque encontra 'esse impedimento já apareceu antes' mesmo quando ninguém usou o mesmo termo"],"answer":3,"explanation":"O acervo do time está cheio de coisas ditas com palavras diferentes que significam o mesmo — busca por significado destrava isso."},{"question":"Qual é o ganho prático mais valioso da busca por significado para o agilista?","options":["A detecção de padrões recorrentes: impedimento sistêmico aparece diluído, uma frase por retro, com fraseado novo cada vez","A geração automática de novas retros","A estimativa de story points","A substituição do Confluence"],"answer":0,"explanation":"Buscando por significado, o padrão emerge; e padrão com evidência é outra conversa com a liderança."},{"question":"Você agrupou 9 relatos de espera por aprovação vindos de 3 times. Qual alerta o artigo faz antes de levar isso a uma audiência que decide?","options":["Que a busca por embeddings é infalível","Que basta a contagem de 9, sem ler os trechos","Que similaridade não é verdade: 'deploy travou' e 'deploy não travou' podem cair perto — leia os trechos e confirme que dizem o que você vai afirmar","Que embeddings só funcionam com dados em inglês"],"answer":2,"explanation":"O tema domina o vetor e a negação pesa pouco; a busca acha os candidatos, mas quem valida o padrão é você."},{"question":"Como a busca por embeddings transforma um argumento com a liderança sobre impedimentos sistêmicos?","options":["Transforma 'sensação de que isso sempre acontece' em dado, com os trechos originais como fonte","Elimina a necessidade de conversar com a liderança","Prova que o impedimento não existe","Substitui a retro por um relatório automático"],"answer":0,"explanation":"Trazer 'apareceu em 9 retros de 3 times, escrito de 9 jeitos' com os trechos é o argumento que vira dado."}],
  "vector-db": [{"question":"Um banco de dados vetorial (Pinecone, pgvector, Chroma) serve para:","options":["Substituir o Jira como ferramenta de board","Armazenar embeddings e buscar os mais 'parecidos' rapidamente — o motor de busca por significado","Treinar modelos do zero","Guardar o código-fonte do time"],"answer":1,"explanation":"É a 'estante' onde os embeddings ficam: a memória de longo prazo de um assistente, indexada para busca por significado."},{"question":"Alguém propõe 'um assistente que conhece nossos processos e histórico'. Por que conhecer o banco vetorial ajuda o agilista?","options":["Para escrever as queries do banco","Para escolher o hardware do servidor","Para configurar os embeddings manualmente","Para participar da conversa de arquitetura com propriedade, em vez de só assinar embaixo"],"answer":3,"explanation":"É o componente por trás da 'memória' do assistente; conhecê-lo coloca o agilista nas decisões de arquitetura."},{"question":"Qual decisão de arquitetura o artigo diz ser 'genuinamente sua' (do agilista)?","options":["O que entra no índice: atas e acordos sim, avaliações de pessoas e one-on-ones não — a memória é curadoria, não acaso","Qual algoritmo de busca vetorial usar","Quantos bits terão os vetores","Qual provedor de nuvem contratar"],"answer":0,"explanation":"A memória do assistente é curadoria: acordos, DoR/DoD e decisões entram; anotações sensíveis e rascunhos não."},{"question":"O artigo alerta sobre 'stale index' (índice desatualizado). Por que isso é responsabilidade de facilitação?","options":["Porque o índice desatualizado deixa a busca mais lenta","Porque quando o time muda um acordo, alguém precisa garantir que a memória mudou junto — assistente com processo de 2 anos atrás é pior que nenhum","Porque índices antigos custam mais caro","Porque só o time técnico pode tocar no índice"],"answer":1,"explanation":"A curadoria não termina no lançamento; documentos atualizados podem continuar sendo servidos na versão antiga."},{"question":"Qual detalhe do artigo vale como 'regra de facilitação' sobre busca vetorial?","options":["A busca só funciona com documentos recentes","A busca nunca retorna itens irrelevantes","A busca sempre devolve os itens mais próximos, mesmo quando nenhum é de fato relevante — 'achou algo parecido' não é 'achou a resposta'","A busca substitui a leitura das atas"],"answer":2,"explanation":"O banco sempre retorna os vizinhos mais próximos; proximidade não garante relevância."}],
  "rag": [{"question":"RAG (Retrieval Augmented Generation) é a técnica de:","options":["Treinar o modelo do zero com os dados do time","Antes de responder, buscar trechos relevantes dos seus dados e injetá-los no prompt, para a IA responder com base na SUA verdade","Comprimir o modelo para rodar mais barato","Guardar o prompt fixo em cache"],"answer":1,"explanation":"RAG faz a IA responder com base nos seus documentos, reduzindo alucinação e trazendo conhecimento atualizado."},{"question":"Para o agilista, qual é a diferença que o RAG faz?","options":["Deixa a resposta mais curta","Reduz o custo por chamada","Separa um chatbot que 'acha' de um assistente que cita a decisão registrada na ata de março, com link","Elimina a necessidade de manter documentação"],"answer":2,"explanation":"RAG responde a partir dos SEUS documentos citando a fonte, em vez de 'achar' com conhecimento genérico."},{"question":"Antes de liberar um assistente RAG sobre o Confluence, como o agilista o testa como facilitador?","options":["Faz perguntas com resposta na base (ele acha e cita certo?), perguntas sem resposta (ele admite?) e confere se as fontes citadas batem","Pergunta só coisas que ele já sabe que a IA acerta","Confia que o time técnico já testou","Verifica apenas a velocidade de resposta"],"answer":0,"explanation":"O 'caso de ausência' é o teste mais revelador: um assistente que nunca diz 'não sei' é um risco disfarçado de conveniência."},{"question":"Por que 'a qualidade do Confluence virou a qualidade do assistente' é uma implicação direta para o agilista?","options":["Porque o assistente reescreve o Confluence sozinho","Porque o Confluence fica mais lento com RAG","Porque a IA ignora documentos antigos automaticamente","Porque ata desatualizada ou contraditória vira resposta errada com aparência de verdade — a higiene de documentação deixou de ser burocracia"],"answer":3,"explanation":"Se o assistente responde com base no Confluence, a documentação virou base de conhecimento de uma ferramenta consultada todo dia."},{"question":"Na planning, alguém pergunta 'por que decidimos não integrar com o legado?' e o assistente RAG responde citando a ata com link. Qual é o ganho de fluxo?","options":["A discussão que consumiria vinte minutos de reconstrução de memória se resolve em um","O time deixa de precisar de plannings","A decisão antiga é automaticamente revertida","O assistente decide sozinho a nova integração"],"answer":0,"explanation":"RAG evita relitigar decisões antigas porque a IA aponta o registro na hora certa, com a fonte."}],
  "context-engineering": [{"question":"Context engineering, como evolução da engenharia de prompt, é a disciplina de:","options":["Escrever a frase de abertura perfeita","Gerenciar TUDO que entra na janela de contexto — instruções, dados recuperados, histórico, ferramentas, memória — para maximizar a resposta sem desperdiçar tokens","Treinar o modelo com dados do time","Reduzir o custo por chamada com cache"],"answer":1,"explanation":"É curar tudo que entra no contexto para maximizar a qualidade da resposta, otimizando por densidade de sinal."},{"question":"O artigo diz que o agilista 'já faz context engineering sem saber'. Em que atividade?","options":["Quando prepara uma pauta de decisão, escolhendo o que os participantes precisam saber — nem menos, nem mais","Quando estima story points","Quando move cards no board","Quando escreve o código do assistente"],"answer":0,"explanation":"Curar a entrada de uma pauta é a mesma habilidade, agora aplicada à janela de contexto de uma máquina."},{"question":"Por que o mesmo pedido dá resultado ótimo numa semana e péssimo na outra?","options":["Porque o modelo muda de humor","Porque o benchmark do modelo caiu","Quase nunca é o modelo; é o que você anexou — a curadoria do contexto","Porque o cache foi invalidado"],"answer":2,"explanation":"A qualidade depende do que entra na janela de contexto; a curadoria dessa entrada é o diferencial."},{"question":"Quais são as duas regras que 'mais mudam a prática' segundo o artigo?","options":["Usar sempre o modelo mais caro e o prompt mais longo","Nunca usar RAG e sempre usar few-shot","Repetir o mesmo prompt e confiar no cache","Mais contexto não é melhor (o efeito 'lost in the middle') e contexto desatualizado é veneno — otimize por densidade de sinal e por frescor"],"answer":3,"explanation":"Despejar tudo dilui o sinal e a info enterrada é ignorada; uma versão antiga do objetivo gera relatório confiante e errado."},{"question":"Para o relatório mensal, você monta o contexto deliberadamente e deixa de fora 40 páginas de atas. Qual refinamento final o artigo recomenda?","options":["Pedir que a IA aponte explicitamente o que não conseguiu concluir com o material, em vez de preencher lacunas com suposição","Anexar tudo que puder ser útil para garantir cobertura","Usar sempre a versão mais antiga do objetivo para ter histórico","Não revisar, pois o contexto curado garante correção"],"answer":0,"explanation":"Falha declarada você resolve anexando a fonte que faltou; chute silencioso você só descobre quando o stakeholder pergunta a origem do número."}],
  "fine-tuning": [{"question":"Fine-tuning difere de RAG porque:","options":["É mais barato e rápido que RAG em qualquer caso","Continua o treino do modelo com seus exemplos, alterando o próprio modelo — enquanto RAG injeta dados no prompt","Não exige dados nem manutenção","Memoriza fatos que mudam com precisão"],"answer":1,"explanation":"Fine-tuning muda o modelo (mais caro, exige dados e manutenção); é usado quando prompt+RAG não bastam."},{"question":"Segundo a 'régua' do artigo, para que serve fine-tuning — e para que não serve?","options":["Molda comportamento/formato, mas não memoriza fatos voláteis; para conhecimento que muda, prompt ou RAG entrega mais rápido e barato","Serve para memorizar fatos que mudam toda semana","Serve para reduzir o custo por chamada","Serve para qualquer caso, sempre superando prompt e RAG"],"answer":0,"explanation":"Fine-tuning molda comportamento e vira dívida técnica viva; para conhecimento volátil, ele responde a uma realidade antiga com confiança."},{"question":"Uma área propõe 3 meses para 'treinar um modelo com nosso histórico de tickets'. Qual é o papel do agilista?","options":["Aprovar, pois soa estratégico e proprietário","Ser o dono da decisão técnica e escolher o método","Vetar qualquer uso de fine-tuning","Garantir que a decisão seja tomada na ordem certa e no tamanho certo, com perguntas de facilitação"],"answer":3,"explanation":"As perguntas — qual resultado observável? A alternativa barata já foi medida? Quem paga a manutenção? — são as mesmas de qualquer épico inflado."},{"question":"Como a iniciativa de 3 meses foi 'quebrada' no exemplo do artigo?","options":["Em três épicos técnicos de fine-tuning","Num piloto com RAG sobre os mesmos tickets, com critério de sucesso, entrando na próxima sprint; a iniciativa grande sai do roadmap até o piloto provar necessidade","Numa contratação de consultoria externa","Num adiamento indefinido sem experimento"],"answer":1,"explanation":"O portfólio ganha uma aposta pequena e reversível; se o fine-tuning se provar necessário, entra com evidência, não com entusiasmo."},{"question":"Qual argumento técnico o artigo acrescenta a favor de testar o baseline barato primeiro?","options":["Fine-tuning é sempre proibido por governança","RAG nunca funciona para tickets","Se o fine-tuning não superar um bom prompt como baseline, ele nem se justifica","O modelo mini já resolve qualquer caso"],"answer":2,"explanation":"Sem superar o baseline de um bom prompt, o fine-tuning não paga seu custo e sua manutenção."}],
  "prompt-caching": [{"question":"Prompt caching é o recurso que:","options":["Treina o modelo com o histórico de prompts","Armazena a parte fixa e grande do prompt (instruções, documentos) para que as próximas chamadas não a reprocessem do zero, reduzindo custo e tempo","Comprime o modelo para a versão mini","Guarda as respostas do usuário no Confluence"],"answer":1,"explanation":"A parte fixa é processada uma vez e relida por uma fração do preço; a parte variável paga preço cheio."},{"question":"Por que custo por chamada 'virou tema de planejamento' para o agilista cujo time constrói produto com IA?","options":["Porque aparece na review quando o consumo sobe, na conversa de orçamento quando escala e na meta de eficiência do quarter","Porque o agilista paga a conta pessoalmente","Porque cache é uma cerimônia ágil","Porque custo só importa para infraestrutura"],"answer":0,"explanation":"Custo deixou de ser assunto de infraestrutura; entender a alavanca do caching permite ao agilista acompanhar e traduzir essas conversas."},{"question":"Na review, o time comemora que o custo do assistente caiu 60% com caching e um stakeholder pergunta se dá para cortar mais 60%. Qual tradução do agilista mantém a expectativa realista?","options":["'Sim, é só ativar mais cache'","'Não dá para reduzir custo de IA'","'A parte fixa já está cacheada e custa uma fração; o que sobra é a parte variável, que cresce com o uso — mais economia viria de outra alavanca'","'Vamos trocar para a versão mini do modelo'"],"answer":2,"explanation":"Caching já capturou o ganho da parte fixa; economia adicional vem de prompts menores, menos chamadas ou outro desenho — não de 'mais cache'."},{"question":"Como o caching muda o formato das perguntas que o agilista ajuda a responder sobre custo?","options":["'Quanto custa a feature?' vira 'quanto do prompt é estável e cacheável, e quanto varia por usuário?'","'Qual o benchmark do modelo?'","'Quantos bits têm os pesos?'","'Quem escreveu o prompt?'"],"answer":0,"explanation":"Caching transforma um custo que crescia inteiro num custo com componente fixo barato e componente variável real."},{"question":"O custo de uma feature de IA saltou sem explicação entre um mês e outro. Qual hipótese o artigo diz ser legítima levar ao time?","options":["O modelo ficou mais burro","O benchmark do modelo caiu","O usuário está usando errado","'Algo invalidou o cache' — as falhas de caching são silenciosas: nada quebra, a conta só sobe"],"answer":3,"explanation":"Como as falhas de cache são silenciosas, 'algo invalidou o cache' é hipótese tão concreta quanto 'subiu o uso'."}],
  "streaming": [{"question":"Na review, o time discute por que os usuários abandonam o assistente do produto: a resposta completa demora 15 segundos. Como você, agilista, reenquadra o problema com o PM?","options":["O modelo precisa ser trocado por um mais rápido, pois 15 segundos é tempo total demais","A meta não é reduzir o tempo total, e sim fazer o primeiro conteúdo aparecer em ~2 segundos (latência percebida)","É um problema de infraestrutura de rede que foge do escopo do time","Deve-se cortar a qualidade da resposta para ganhar velocidade"],"answer":1,"explanation":"Streaming ataca a velocidade percebida (tempo até o primeiro token) sem mudar o modelo nem o tempo total; reenquadrar para 'primeiro conteúdo em 2s' resolve o abandono."},{"question":"O que é 'streaming' de respostas em produtos de IA?","options":["A saída sendo enviada token a token, aparecendo aos poucos na tela","Um modo que garante que a resposta completa chegue em menos tempo total","Um cache que guarda respostas anteriores para reuso","A execução do modelo em paralelo em vários servidores"],"answer":0,"explanation":"Streaming é o envio da saída token a token, o que melhora a percepção de velocidade mesmo quando a resposta completa demora o mesmo."},{"question":"Um stakeholder pede para escrever o item como 'deixar o assistente mais rápido'. Por que, como facilitador, você prefere outra formulação?","options":["Porque velocidade não é uma preocupação válida para o backlog","Porque o termo 'rápido' deve sempre ser evitado em histórias","Porque 'mais rápido' é um desejo, não um critério de aceite; 'primeiro conteúdo visível em até 2s no percentil 95' é mensurável","Porque o stakeholder não deveria opinar sobre critérios de aceite"],"answer":2,"explanation":"Streaming mostra que existe alavanca de entrega para o problema; um critério com percentil é auditável, enquanto 'mais rápido' é subjetivo."},{"question":"O time estima o item de streaming maior do que o stakeholder esperava. Qual argumento sustenta a estimativa?","options":["A estimativa está inflada e deveria ser reduzida na planning","Streaming exige treinar um novo modelo do zero","O tamanho vem de mudar a qualidade da resposta","Entregar um fluxo (com cancelamento no meio, queda de conexão, resposta truncada) é mais trabalhoso que entregar uma resposta pronta"],"answer":3,"explanation":"O objeto sob construção muda de natureza: um fluxo tem cenários novos (cancelamento, queda, truncamento) que exigem tratamento, o que justifica a estimativa."},{"question":"Por que 'tempo até o primeiro token' é tratado pelo time de produto como métrica de experiência de primeira classe?","options":["Porque mede exatamente o tempo total de processamento do modelo","Porque é a métrica que o fornecedor da IA cobra por contrato","Porque a latência percebida muda a adoção — um assistente que fica mudo 15s morre por abandono, não por qualidade","Porque só ela indica a precisão das respostas"],"answer":2,"explanation":"A distinção entre tempo real e tempo percebido afeta diretamente a adoção; por isso o primeiro token merece meta própria de experiência."}],
  "chunking-reranking": [{"question":"Na retro, aparecem reclamações de que 'a IA é ruim' ao buscar informações na base do time. Como você transforma isso em algo acionável para o time técnico?","options":["Registra 'a IA é ruim' como impedimento e escala para a liderança","Sugere trocar o modelo por um mais moderno","Coleta as perguntas exatas que falharam e reporta o padrão: 'a recuperação falha para perguntas sobre acordos de times específicos'","Pede ao time para ajustar o chunking e o re-ranker você mesmo"],"answer":2,"explanation":"Transformar insatisfação difusa em diagnóstico com exemplos concretos ('falha para perguntas sobre X') é acionável; 'a IA é ruim' é só desabafo."},{"question":"O que são chunking e re-ranking num sistema de RAG?","options":["Chunking é treinar o modelo; re-ranking é ajustar a temperatura","Chunking é como os documentos são fatiados antes de indexar; re-ranking é reordenar os trechos recuperados por relevância antes de enviá-los ao modelo","Chunking é o cache de respostas; re-ranking é o log de erros","São dois nomes para a mesma etapa de geração da resposta"],"answer":1,"explanation":"Chunking fatia os documentos e re-ranking reordena os trechos por relevância; juntos são os fatores que mais afetam a qualidade de um RAG."},{"question":"Quando um RAG 'não acha' uma informação que está na base, qual costuma ser a causa, segundo a lente do agilista?","options":["Quase sempre o modelo é fraco demais","O usuário fez a pergunta errada","Falta de dados na base do Confluence","Decisões invisíveis de recuperação — como os documentos foram fatiados e como os trechos foram ordenados"],"answer":3,"explanation":"Quando um RAG erra, a culpa quase nunca é do modelo; a causa mora no chunking e na ordenação dos trechos."},{"question":"Para levar uma reclamação sobre o assistente ao time técnico de forma útil, o que vale mais?","options":["Três perguntas reais que falharam, com o padrão observado (mesmo tipo de pergunta? mesmo tipo de documento?)","Dez minutos descrevendo que 'o pessoal anda desconfiado do bot'","Uma estimativa sua da causa técnica do problema","Uma lista de modelos alternativos para o time avaliar"],"answer":0,"explanation":"Casos concretos que falharam, com o padrão, permitem ao time investigar; impressões soltas evaporam."},{"question":"O assistente do Confluence responde bem sobre processos gerais, mas falha em acordos de times específicos; após você levar os casos, o dev descobre a causa. O que aconteceu?","options":["O modelo não foi treinado com dados de acordos","As páginas de acordos são longas e o fatiamento cortou no meio das seções, separando pergunta e resposta","O Confluence estava fora do ar durante as buscas","As perguntas eram ambíguas demais para qualquer sistema"],"answer":1,"explanation":"O chunking cortou no meio das seções: a pergunta encontrava o título, mas a resposta ficara em outro pedaço; corrigir o corte por seção resolveu."}],
  "grounding": [{"question":"O que 'grounding' e 'faithfulness' significam na prática para quem produz resumos que outros vão ler?","options":["Grounding é ancorar a resposta nas fontes; faithfulness mede se cada afirmação é de fato suportada pela fonte citada","Que a IA sempre cita fontes, então a resposta é confiável","Que basta a resposta soar plausível para estar correta","Que citações substituem a necessidade de revisão humana"],"answer":0,"explanation":"Grounding é ancorar a resposta nos dados; faithfulness verifica se cada afirmação se sustenta na fonte — citar uma fonte e se sustentar nela são coisas diferentes."},{"question":"A IA gera um resumo executivo e escreve 'a iniciativa de checkout está no prazo [status de junho]'. A fonte diz 'no prazo, com risco na dependência do time de pagamentos'. Qual é o modo de falha?","options":["A afirmação é falsa e deve ser descartada","A citação está errada, o problema é a fonte apontada","A afirmação é incompleta: omitir o risco muda a decisão de quem lê","Não há problema, pois 'no prazo' está correto"],"answer":2,"explanation":"A afirmação não é falsa, é incompleta; a omissão do risco muda a decisão do leitor, por isso o pedido é 'reescreva mantendo os riscos das fontes'."},{"question":"Por que a 'afirmação órfã' (que soa plausível mas não veio de nenhuma fonte) é a mais perigosa na comunicação com stakeholders?","options":["Porque ela sempre contém números errados","Porque ninguém abre o link para conferir — a presença da citação já compra a confiança","Porque ela demora mais para ser gerada pela IA","Porque ela aparece só em relatórios longos"],"answer":1,"explanation":"A afirmação órfã soa plausível e vem acompanhada de citação; como ninguém abre o link, a confiança é comprada sem suporte real."},{"question":"Qual método de revisão o agilista aplica antes de repassar um texto redigido pela IA a um diretor?","options":["Confiar no texto se ele tiver pelo menos uma citação por parágrafo","Reescrever tudo do zero sem usar a IA","Enviar direto, já que a revisão é papel de quem cuida da qualidade","Decompor o resumo em afirmações verificáveis (cada número, data, 'no prazo') e conferir cada uma contra a fonte apontada"],"answer":3,"explanation":"O método é decompor em afirmações verificáveis e checar cada uma contra a fonte, pegando tanto contradições quanto afirmações órfãs."},{"question":"Por que grounding, para o agilista, é 'higiene básica' e não apenas uma técnica de IA?","options":["Porque a ferramenta obriga a checagem automaticamente","Porque uma afirmação sem suporte que você repassa sai com o seu nome, não com o da ferramenta","Porque só afeta relatórios técnicos, não executivos","Porque grounding elimina a necessidade de fontes"],"answer":1,"explanation":"Boa parte do que o agilista produz é texto para decisão; ao repassar, ele assume a autoria, então verificar cada afirmação é higiene, não opcional."}],
  "logprobs-confidence": [{"question":"O time desenha uma triagem automática de tickets baseada na confiança do modelo. Qual princípio de desenho de fluxo esse conceito oferece ao agilista?","options":["Automatizar tudo, já que a IA classifica sozinha","Automatizar o que a IA acerta com confiança alta e rotear o incerto para uma fila de revisão humana","Enviar todos os tickets para revisão humana por segurança","Descartar os tickets de baixa confiança"],"answer":1,"explanation":"Nem toda resposta merece a mesma confiança, então nem toda deve seguir o mesmo caminho: alta confiança segue automático, incerto vai para revisão — gestão de fluxo por risco."},{"question":"O que são logprobs e calibração?","options":["Logprobs são logs de erro; calibração é o ajuste do servidor","Logprobs medem a latência; calibração mede o custo","Logprobs são as probabilidades que o modelo atribui a cada token gerado (sinal de confiança); calibração mede se essa confiança bate com a taxa real de acerto","São sinônimos para a temperatura do modelo"],"answer":2,"explanation":"Logprobs indicam quão 'confiante' o modelo estava em cada token; calibração verifica se essa confiança reportada corresponde à taxa real de acerto."},{"question":"Na discussão de fluxo da triagem, qual pergunta o agilista traz que o time focado no modelo costuma esquecer?","options":["Quantos por cento dos casos cairão na fila de revisão e quem absorve esse trabalho?","Qual algoritmo de classificação é usado internamente?","Qual a temperatura ideal do modelo?","Como reduzir o número de tokens por ticket?"],"answer":0,"explanation":"A fila de revisão humana é trabalho real; capacidade, dono da fila e impacto no lead time são perguntas de fluxo que o agilista traz ao desenho."},{"question":"Por que o limiar de confiança é descrito como 'uma decisão de processo', não um número técnico?","options":["Porque só o time de dados pode defini-lo","Porque ele nunca precisa ser revisitado depois","Porque quanto maior o limiar, mais rápido o modelo responde","Porque tem um trade-off de fluxo: apertado demais, a fila humana explode e vira gargalo; frouxo demais, erro passa direto e vira retrabalho"],"answer":3,"explanation":"O limiar tem trade-off clássico de fluxo entre fila humana e erro que passa; por isso é decisão de processo, não apenas técnica."},{"question":"Por que o limiar de confiança precisa ser validado com dados reais antes de o fluxo entrar em produção?","options":["Porque a confiança reportada pode ser mal calibrada — o modelo pode dizer '90%' e acertar 70%","Porque o modelo sempre subestima a própria confiança","Porque validar reduz o custo por token","Porque a produção não aceita fluxos com revisão humana"],"answer":0,"explanation":"A confiança pode estar mal calibrada; validar com dados históricos evita dimensionar mal a fila — como na simulação que revelou um terço dos tickets indo para revisão."}],
  "determinism": [{"question":"Por que a mesma pergunta a um LLM pode gerar respostas diferentes a cada execução?","options":["É um defeito da ferramenta que deve ser reportado como bug","Só acontece quando o modelo está sobrecarregado","É a natureza probabilística e não-determinística dos LLMs; temperatura 0 e seeds reduzem, mas raramente garantem 100%","Só acontece se o prompt tiver erros de digitação"],"answer":2,"explanation":"LLMs são não-determinísticos por natureza; a variação não é defeito, e mesmo temperatura 0 e seeds raramente eliminam a variação por completo."},{"question":"Você vai levar 'as 3 principais causas do atraso' geradas por IA a uma audiência que decide. Qual prática o conceito de determinismo recomenda?","options":["Confiar na primeira resposta, pois a IA é consistente","Rodar mais de uma vez: o que aparece nas várias rodadas é sinal; o que apareceu em uma só merece verificação","Aumentar a temperatura para ter mais variedade","Evitar usar IA para qualquer análise"],"answer":1,"explanation":"Como a saída varia entre rodadas, o que se repete é sinal confiável e o que aparece uma vez só precisa de verificação antes de virar afirmação sua."},{"question":"Na planning, o time estima 8 pontos para 'testar o classificador de tickets' e um stakeholder estranha. Como você defende a estimativa?","options":["Explica que a saída varia, então o teste honesto roda cada caso várias vezes e mede a taxa de acerto, não um 'passou/falhou' único","Diz que o time sabe o que faz e encerra a discussão","Reduz a estimativa para evitar conflito","Sugere não testar a feature de IA"],"answer":0,"explanation":"Como a saída varia, testar exige rodar cada caso várias vezes e medir consistência, o que multiplica o trabalho; a estimativa se sustenta com argumento técnico, não autoridade."},{"question":"Por que o critério de aceite 'a classificação deve estar correta' não funciona para uma feature de IA?","options":["Porque é longo demais para um card","Porque critérios de aceite não se aplicam a IA","Porque só quem testa pode escrever critérios de IA","Porque num sistema que varia não é verificável; o formato correto é algo como '≥ 95% de acerto no conjunto de referência, sem regressão'"],"answer":3,"explanation":"Em um sistema não-determinístico, 'estar correta' não é verificável; 'passou' vira uma taxa com tolerância, então o critério precisa virar um número mensurável."},{"question":"Ao contextualizar a estimativa, a conversa com o stakeholder muda de 'por que tão caro?' para qual pergunta?","options":["Quem é o responsável pelo atraso da estimativa?","Qual taxa de acerto aceitamos para lançar? (a conversa vira sobre risco, não desconfiança)","Podemos remover os testes desta feature?","Qual modelo é mais barato de operar?"],"answer":1,"explanation":"Ao explicar a natureza do teste, a conversa migra de desconfiança sobre o custo para a conversa certa de risco: qual taxa de acerto é aceitável para lançar."}],
  "sdd": [{"question":"O que caracteriza o SDD (Spec-Driven Development) na ótica de fluxo do agilista?","options":["Escrever mais código antes de especificar","Substituir o refinamento por geração automática sem revisão","Colocar a especificação como fonte da verdade (contrato executável) da qual a IA deriva código, testes e documentação","Terceirizar a spec para a ferramenta de teste"],"answer":2,"explanation":"No SDD a spec estruturada vira contrato executável que guia a IA a gerar código e testes, o que eleva o valor do trabalho upstream de refinamento."},{"question":"Se a spec vira contrato executável do qual a IA gera código, o que acontece com o refinamento na sprint?","options":["Vira burocracia dispensável, pois a IA resolve tudo","Vira a atividade de maior alavancagem: ambiguidade na spec agora vira código errado em horas, não em semanas","Passa a ser responsabilidade exclusiva do PM","Deixa de existir, pois não há mais histórias"],"answer":1,"explanation":"Como a IA deriva código e testes da spec, uma ambiguidade que antes levava semanas para virar bug agora vira código errado em horas, elevando o refinamento a atividade de maior alavancagem."},{"question":"No refinamento orientado a SDD, que artefato a sessão passa a produzir?","options":["Uma descrição solta no Jira, como antes","Apenas o código já pronto gerado pela IA","Uma lista de tarefas sem critérios","Uma spec estruturada com regras no formato 'QUANDO X, o sistema DEVE Y' e exemplos, validada por PM, Dev e quem testa antes de qualquer código"],"answer":3,"explanation":"O refinamento SDD produz uma spec estruturada (requisitos no formato 'QUANDO X, DEVE Y'), validada em conjunto antes do código — a spec vira o novo Definition of Ready."},{"question":"Na squad piloto, as primeiras sessões de SDD 'sofrem' porque escrever 'QUANDO o token expirar, o sistema DEVE retornar erro' dá mais trabalho. O que aparece no board duas sprints depois?","options":["A velocidade cai permanentemente e o piloto é abortado","Os cards de retrabalho por 'entendi diferente' praticamente somem e o refluxo (cards voltando de teste para dev) despenca","O número de bugs aumenta por excesso de spec","O time abandona os critérios de aceite"],"answer":1,"explanation":"Apesar do esforço inicial, o retrabalho por 'entendi diferente' some e o refluxo despenca — e essa métrica de refluxo é o que sustenta a mudança de processo."},{"question":"Por que 'zona cinzenta na spec' passa a ser tratada como impedimento no fluxo SDD?","options":["Porque atrasa a daily","Porque impede o PM de aprovar o card","Porque a spec é o novo Definition of Ready e a IA implementa a partir dela — ambiguidade não resolvida vira código errado rapidamente","Porque a ferramenta bloqueia specs incompletas"],"answer":2,"explanation":"Sendo a spec a fonte da qual a IA deriva a implementação, zona cinzenta é impedimento e não detalhe — precisa ser removida antes de o item virar código."}],
  "agentic-coding": [{"question":"O time adota um agente de código e as tarefas de desenvolvimento encolhem de dias para horas. Qual pergunta de fluxo só o agilista tende a fazer?","options":["Qual IDE o time deve usar para operar o agente?","Se o time codifica muito mais rápido, por que o lead time não caiu? (o gargalo mudou de lugar)","Como escrever o prompt perfeito para o agente?","Quantos tokens o agente consome por tarefa?"],"answer":1,"explanation":"Quando as tarefas de código encolhem, o gargalo migra — quase sempre para revisão, validação e integração; enxergar para onde ele foi é papel do agilista."},{"question":"O que é 'agentic coding' e 'vibe coding'?","options":["Um autocomplete que sugere uma linha por vez","Uma técnica de escrever testes E2E manualmente","Um agente de IA que planeja e executa a tarefa de código de ponta a ponta (edita arquivos, roda testes, corrige); vibe coding é guiá-lo por intenção em linguagem natural e revisar o resultado","Um modo de programar sem revisão humana nenhuma"],"answer":2,"explanation":"Agentic coding é o agente implementando a tarefa inteira de ponta a ponta; vibe coding é o estilo de guiá-lo por intenção em linguagem natural, revisando a saída."},{"question":"Duas sprints após adotar o agente, o CFD/cycle time por coluna mostra: itens atravessam 'em desenvolvimento' na metade do tempo, mas o estoque 'em revisão' triplicou. O que você faz na retro?","options":["Projeta o gráfico e facilita a pergunta: 'o que fazemos com um fluxo em que gerar código ficou barato e revisar ficou caro?'","Sugere reduzir a quantidade de código gerado pela IA","Propõe remover a coluna de revisão do board","Conclui que o agente deve ser abandonado"],"answer":0,"explanation":"Com o dado do cycle time por coluna, o agilista facilita a decisão certa — acordos de revisão para código de IA e limite de WIP na revisão — em vez de discutir sensações."},{"question":"Segundo a lente do agilista, por que estimativa e quebra de trabalho 'mudam de natureza' com agentes de código?","options":["Porque agora tudo é estimado em horas, não em pontos","Porque o agente define as estimativas sozinho","Porque uma tarefa 'grande' para um humano pode ser trivial para um agente (e vice-versa); tamanho do código deixa de ser proxy de esforço","Porque estimar deixa de ser necessário"],"answer":2,"explanation":"O que era proxy de esforço (tamanho do código) deixa de valer; refinar como antes produz previsões piores, e provocar essa recalibragem é papel do agilista."},{"question":"Após criar acordos de revisão para código gerado por IA e limitar o WIP da revisão, o lead time finalmente cai. Qual é a lição sobre ganho de ferramenta versus ganho de fluxo?","options":["A ferramenta sozinha garante o ganho de fluxo","A ferramenta trouxe a velocidade, mas o ganho de fluxo veio de alguém olhando o sistema inteiro","Ganho de fluxo depende só de contratar mais revisores","Velocidade de código e lead time são sempre a mesma coisa"],"answer":1,"explanation":"A adoção acelerou o desenvolvimento, mas o lead time só caiu quando o gargalo de revisão foi tratado — o ganho de fluxo veio da leitura do sistema inteiro."}],
  "ai-code-review": [{"question":"Na leitura de fluxo do agilista, qual fila invisível o review de PR com IA ataca diretamente?","options":["O tempo de build no CI","O tempo de espera em 'aguardando revisão' — trabalho pronto, mas parado, inflando o lead time sem ninguém estar 'atrasado'","O tempo de escrita de código","O tempo de deploy em produção"],"answer":1,"explanation":"'Aguardando revisão' é uma das maiores filas invisíveis do downstream; review com IA ataca essa espera, e cabe ao agilista medir se o lead time respondeu."},{"question":"O que o review de PR com IA cobre e o que continua sendo humano?","options":["Cobre tudo, tornando o revisor humano desnecessário","Cobre apenas segurança e nada mais","Faz a primeira passada (padrões, riscos óbvios, bugs, falta de testes); decisões de design continuam humanas","Substitui o Definition of Done"],"answer":2,"explanation":"A IA faz a primeira passada em padrões e riscos óbvios, enquanto decisões de design seguem humanas; entender isso permite medir o efeito real no lead time."},{"question":"O time ativa review de IA e o tempo em 'aguardando revisão' cai de 26 para 9 horas, mas na retro um dev reclama que a IA comenta obviedades e ele passou a ignorar tudo. Qual é a natureza desse segundo problema?","options":["É um problema de acordo de trabalho — mesmo tipo de conversa de Definition of Done que você já facilita","É um problema técnico do modelo, fora do seu escopo","É um sinal de que o review de IA deve ser desligado","É um problema de infraestrutura do Bitbucket"],"answer":0,"explanation":"Ruído que vira fadiga de alerta mata a credibilidade do gate; isso é acordo de trabalho, território de facilitação do agilista, não problema técnico."},{"question":"Como você facilita o novo acordo quando o ruído dos comentários da IA vira pauta de retro?","options":["Determina por conta própria quais comentários a IA deve suprimir","Manda o dev ignorar a reclamação","Remove o review de IA para acabar com o ruído","Facilita: a IA faz a primeira passada, o humano decide, e o time define quais categorias de comentário ela deve suprimir"],"answer":3,"explanation":"Adotar em fase sombra, decidir o que bloqueia e o que só comenta, e definir em time quais categorias suprimir é desenho de processo — o agilista media, o time decide."},{"question":"Por que, ao voltar na retro seguinte, você traz os dois números — tempo em espera e ruído?","options":["Para justificar a compra da ferramenta ao fornecedor","Porque ferramenta nova exige acordo novo, e é o dado que mantém a conversa honesta (o ganho se cumpriu ou o time só ganhou um robô que comenta?)","Porque o número de ruído define o salário do time","Porque só a diretoria pode ver essas métricas"],"answer":1,"explanation":"O agilista mede se a promessa se cumpre: espera caiu de fato e o ruído foi controlado; o dado mantém a conversa baseada em evidência, não impressão."}],
  "cypress-ai": [{"question":"Você não vai escrever testes Cypress. Qual é o 'verdadeiro gargalo' de uma suíte E2E que o agilista precisa enxergar para ler o fluxo?","options":["Escrever o teste na primeira vez","Mantê-lo vivo enquanto o produto muda — manutenção que é um consumidor invisível de capacidade da sprint","Rodar o teste no CI","Escolher a ferramenta de teste certa"],"answer":1,"explanation":"O gargalo não é escrever o teste, é a manutenção; ela some do backlog como 'quem testa está ocupado' e velocity inexplicada, e self-healing ataca esse custo."},{"question":"No nível certo para o agilista, o que os recursos de IA do Cypress (cy.prompt e self-healing) fazem?","options":["Autoria assistida escreve passos em linguagem natural e o self-healing conserta seletores quando a UI muda, reduzindo o custo de manutenção da suíte","Substituem completamente quem testa","Geram relatórios de fluxo para o eazyBI","Movem cards no Jira automaticamente"],"answer":0,"explanation":"cy.prompt gera passos e descobre seletores; self-healing conserta seletores quando a UI muda — atacando o custo de manutenção, que é o que interessa ao agilista no fluxo."},{"question":"Se os testes passam a se curar sozinhos quando a UI muda, que pergunta de facilitação isso gera na retro?","options":["Qual seletor a IA usou para se curar?","Qual a cobertura de linha da suíte?","Os itens recorrentes de 'consertar a suíte' sumiram do backlog? Se não sumiram, é pauta de retro","Quantos testes foram escritos esta sprint?"],"answer":2,"explanation":"Se a promessa é reduzir manutenção, os itens recorrentes de conserto deveriam sumir; se não sumirem, o agilista leva isso para inspeção e adaptação."},{"question":"Quando o time de qualidade explica que 'cura silenciosa pode esconder regressão' e cada cura vira item a revisar, o que isso significa para o fluxo?","options":["Que a capacidade liberada volta parcialmente como trabalho de auditoria — o ganho não é de graça","Que o self-healing deve ser desligado imediatamente","Que a suíte não precisa mais de revisão humana","Que a regressão é problema exclusivo do agilista"],"answer":0,"explanation":"Parte da capacidade volta como trabalho de auditoria das curas; prever esse efeito no fluxo é leitura do agilista, não da ferramenta."},{"question":"Você nota no Jira 2-3 itens de 'corrigir testes quebrados' por sprint (quase um dia de capacidade). Como você apoia a proposta de adotar a IA do Cypress?","options":["Aprova sem medir, confiando na promessa do fornecedor","Apoia com o dado e combina a medição: se em dois meses esses itens caírem, o ganho é real; se só mudarem de nome (de 'consertar' para 'revisar curas'), a conversa é outra","Rejeita porque testes E2E não afetam o fluxo","Sugere que o time escreva menos testes"],"answer":1,"explanation":"O agilista torna o custo visível antes e depois e mede em horas de capacidade recuperada — não em promessa —, permitindo ao time decidir expandir ou recuar."}],
  "zephyr-ai": [{"question":"O Zephyr com Rovo gera casos de teste a partir das histórias dentro do Jira. Qual é o principal ganho de FLUXO que isso traz para o agilista?","options":["Elimina a necessidade de quem testa","Aumenta a cobertura de código automaticamente em produção","A criação de casos de teste deixa de ser uma etapa que espera quem testa ter tempo — o rascunho nasce no próprio refinamento, antes do código","Substitui os critérios de aceite das histórias"],"answer":2,"explanation":"O valor de fluxo é antecipar a conversa de qualidade: o caso de teste nasce no refinamento e não depois, tornando cobertura parte do Definition of Ready."},{"question":"O 'sinal de risco de release' que o Zephyr/Rovo produz deve ser tratado pelo time como o quê?","options":["Um veredito que decide sozinho o que entra na release","Um indicador — dado novo para as conversas de priorização e planejamento, com a decisão continuando humana","Um número técnico que só quem testa entende","Uma métrica de velocity do time"],"answer":1,"explanation":"O risco de release é informação nova para priorização, desde que tratado como indicador e não como veredito; a decisão de escopo continua do time e do PM."},{"question":"O artigo diz que a qualidade dos casos gerados é função direta da qualidade dos critérios de aceite. Por que isso é 'a favor' do trabalho upstream do agilista?","options":["Porque a IA corrige os critérios sozinha","Porque critérios de aceite deixam de ser necessários","Porque a geração via Rovo funciona como um termômetro do refinamento: se os casos saem rasos, o problema está nas histórias, e a devolutiva chega em minutos","Porque o risco de release substitui o refinamento"],"answer":2,"explanation":"Critério vago vira caso de teste confiante e errado; a geração dá feedback rápido sobre a qualidade do discovery do time, coisa que poucas ferramentas oferecem."},{"question":"No refinamento, quem testa gera os casos da história via Rovo em minutos e o time revisa junto, na hora. O que muda na cerimônia?","options":["A cobertura de teste vira parte da conversa de DoR, não uma etapa posterior","O refinamento é substituído pela geração automática","O PM deixa de participar da sessão","A história não precisa mais de revisão humana"],"answer":0,"explanation":"Gerar e revisar os casos na hora antecipa a qualidade para dentro do Definition of Ready, em vez de deixá-la como etapa que espera o código."},{"question":"Na conversa de release, o indicador de risco aponta duas histórias com cobertura fraca. Como você usa isso como facilitador?","options":["Bloqueia a release automaticamente com base no indicador","Facilita a decisão de escopo com o PM: entram na release ou esperam mais uma sprint de teste? — a decisão parte de um dado que antes não existia","Repassa o indicador à diretoria como veredito final","Ignora, pois cobertura não é assunto de agilista"],"answer":1,"explanation":"O indicador vive na ferramenta que você já opera e alimenta a conversa de priorização; a decisão continua humana, mas agora parte de um dado que antes não existia."}],
  "harness-eval": [{"question":"O que é um eval harness, na analogia que fala com o agilista?","options":["Um painel de fluxo no eazyBI","O arcabouço que roda a IA contra um conjunto de casos e mede a qualidade automaticamente — o equivalente do CI, só que para qualidade de IA","Um modelo de linguagem que gera testes","Um documento de acordos de trabalho do time"],"answer":1,"explanation":"Um eval harness tem dataset, executor e avaliador; é o que transforma 'a IA melhorou?' de opinião em número acompanhável, como o CI faz para a qualidade de IA."},{"question":"O time desenvolve um assistente e cada sprint alguém 'melhora o prompt', mas cada um testou 3 exemplos na mão. Qual é a sua contribuição na retro?","options":["Aponta que não sabemos se melhorou e apoia priorizar um harness com casos reais e nota automática","Sugere trocar o modelo de IA","Pede para cada pessoa testar 10 exemplos em vez de 3","Conclui que melhorar prompt não é trabalho válido"],"answer":0,"explanation":"Sem eval, 'melhorar o prompt' é card que nunca fecha; o harness com casos reais transforma isso em entrega com critério de aceite mensurável e gráfico na review."},{"question":"Segundo a lente do agilista, como um eval harness torna features de IA 'gerenciáveis' dentro da sprint?","options":["Elimina a necessidade de refinamento","Faz a IA se auto-avaliar sem dataset","Dá definição de pronto objetiva: 'subir o recall de urgentes de 0.78 para 0.90 no golden dataset' em vez de 'melhorar as respostas do bot'","Garante que a IA nunca erra"],"answer":2,"explanation":"Com eval, melhorias de IA viram entregas com escopo fechado e critério mensurável — ouro para o refinamento e para uma review baseada em gráfico, não em exemplos escolhidos a dedo."},{"question":"Você configura um agente para gerar o resumo quinzenal da sprint. Como o conceito de eval se aplica ao seu próprio uso, antes de confiar nele?","options":["Confiar direto, pois a IA lê os dados do Jira","Pedir ao time para revisar cada resumo linha por linha para sempre","Usar o agente apenas para comunicações internas","Fazer um mini-eval: pegar seus 10 últimos resumos (golden dataset), rodar o agente sobre as mesmas sprints e comparar contra uma rubrica simples"],"answer":3,"explanation":"Dez casos e uma rubrica (citou as entregas certas? não inventou item? sinalizou riscos? tom serve para diretor?) separam o 'brinquedo que confiro toda vez' do 'assistente com verificação por amostragem'."},{"question":"Quando a discussão 'a IA melhorou ou piorou?' esquenta na retro, qual é o 'move de facilitador' que o eval habilita?","options":["Pedir para cada um dar sua opinião e votar","Perguntar 'qual número decidiria essa discussão?' — times que discutem IA sem eval discutem impressões","Encerrar a discussão até a próxima sprint","Deixar quem testa decidir sozinho"],"answer":1,"explanation":"Impressões são o pior instrumento de decisão; perguntar qual número resolveria a discussão traz a mesma disciplina que o agilista já aplica às métricas de fluxo."}],
  "agent-skills": [{"question":"Qual é o paralelo direto entre um AGENTS.md (instruções versionadas) e o trabalho do agilista?","options":["É um manual técnico que só devs leem","É um acordo de trabalho — o DoR/DoD da colaboração com IA — para um integrante que chega zerado a cada tarefa","É um substituto do backlog","É uma métrica de fluxo do time"],"answer":1,"explanation":"Instruções versionadas registram a convenção uma vez e valem para todos; são acordos de trabalho para agentes, e facilitar sua criação e revisão é papel do agilista."},{"question":"O artigo diz: 'regra que ninguém acordou é legislar por decreto; o arquivo tem autoridade porque passou por review'. Por que isso é uma tese de facilitação?","options":["Porque só o agilista pode escrever o arquivo","Porque review é uma etapa técnica do CI","Porque transformar convenção implícita em acordo explícito, com discussão e consenso, é o que separa um AGENTS.md vivo de mais um wiki morto","Porque decretos funcionam melhor que consenso"],"answer":2,"explanation":"O time pode escrever o arquivo sozinho, mas o ofício de tornar convenção implícita em acordo com consenso é do facilitador — é o que dá autoridade e vida ao documento."},{"question":"O que são 'skills' e instruções de projeto (AGENTS.md, CLAUDE.md), na descrição do material?","options":["Arquivos de instrução versionados no repositório (e pacotes de instruções que o agente carrega quando a tarefa pede) — conhecimento do time virando configuração versionada","Prompts descartáveis digitados a cada tarefa","Modelos de IA treinados pelo time","Relatórios de qualidade gerados pela IA"],"answer":0,"explanation":"São instruções e exemplos versionados que o agente lê/carrega, em vez de cada pessoa repetir tudo em cada prompt — conhecimento do time como configuração versionada."},{"question":"Você percebe que cada pessoa pede coisas à IA de um jeito (histórias sem critérios, resumos em formatos diferentes). Como o padrão de acordo de trabalho se aplica fora do repositório de código?","options":["Cada um continua do seu jeito, pois inconsistência é inevitável","Define sozinho as regras e comunica por e-mail","Pede que a IA padronize os prompts automaticamente","Facilita uma sessão de uma hora para o time escrever instruções compartilhadas e versionadas (formato de história, template de resumo, o que o agente nunca deve fazer)"],"answer":3,"explanation":"A inconsistência nos artefatos do processo tem a mesma solução do código: instruções compartilhadas e versionadas, construídas em sessão de acordo de trabalho facilitada pelo agilista."},{"question":"Qual ingrediente garante que o AGENTS.md não vire 'decreto esquecido' ao longo do tempo?","options":["Trancar o arquivo para edições","Entrar como item permanente da retro (inspeção e adaptação): o agente errou o padrão? a regra está ambígua? alguma convenção mudou?","Deixar só a liderança revisar o arquivo","Reescrever o arquivo do zero a cada sprint"],"answer":1,"explanation":"Acordos para agentes envelhecem como acordos para pessoas; o ciclo de inspeção e adaptação na retro é o mecanismo — não técnico — que mantém o arquivo vivo."}],
  "meta-prompting": [{"question":"O que é meta-prompting?","options":["Escrever prompts mais longos para o modelo","Usar o próprio modelo para escrever, criticar e otimizar prompts: mostrar o prompt atual e saídas ruins, e pedir uma versão melhor","Treinar um modelo novo com seus dados","Traduzir prompts para outro idioma"],"answer":1,"explanation":"Meta-prompting usa o modelo para melhorar prompts a partir de evidência (saídas ruins), industrializando o ciclo gerar → medir → manter o melhor."},{"question":"O agilista tem 'prompts de produção' que talvez não chame assim. Quais são?","options":["Apenas prompts técnicos escritos por devs","Os testes automatizados da suíte","O resumo semanal para stakeholders, a pauta da retro, a quebra de épico em histórias, a ata do planning — instruções que ele repete toda semana","As configurações do Jira"],"answer":2,"explanation":"São instruções repetidas toda semana e geralmente ajustadas 'no olho'; meta-prompting é a versão profissional desse ajuste, com o ciclo de inspecionar e adaptar."},{"question":"Qual é 'a lição mais transferível' do meta-prompting para o agilista?","options":["A separação de papéis: o modelo gera, a evidência decide — sua régua precisa existir, senão a 'melhora' é gosto pessoal","O modelo deve reescrever tudo sem supervisão","Quanto mais versões, melhor, sem comparar","A régua precisa sempre ser um golden dataset com LLM-as-judge"],"answer":0,"explanation":"O modelo gera e a evidência decide; a régua pode ser o comportamento dos leitores, mas precisa existir, senão a melhoria vira gosto pessoal."},{"question":"Seu prompt de resumo semanal gera textos longos que ninguém lê. Qual é o passo que o material recomenda ANTES de pedir a reescrita?","options":["Aumentar a temperatura do modelo","Trocar de ferramenta de IA","Reduzir o número de stakeholders na lista","Entregar o prompt atual mais dois resumos ruins anotados e pedir crítica/diagnóstico antes da reescrita"],"answer":3,"explanation":"Colete evidência de falha anotada e peça o diagnóstico antes de reescrever — é o ciclo inspecionar-adaptar aplicado ao próprio instrumento de trabalho."},{"question":"Você roda v1 e v2 do prompt por duas semanas cada e, com a v2, stakeholders passam a responder apontando os riscos. Por que isso valida a v2?","options":["Porque a v2 é mais curta que a v1","Porque a evidência (comportamento dos leitores) mostra que leram — o resumo virou conversa, que era o objetivo; a v2 entra no repertório com a evidência que a justificou","Porque a IA disse que a v2 era melhor","Porque a diretoria exigiu a v2"],"answer":1,"explanation":"A régua é a reação dos leitores: responder apontando os riscos prova que leram; a v2 entra no repertório justificada por evidência e a v1 vira histórico."}],
  "upstream-ai": [{"question":"O que caracteriza o uso de IA no upstream (discovery), na descrição do material?","options":["A IA decide sozinha o que entra no backlog","A IA atua como um par de refinamento: rascunha épicos/histórias, sugere quebras, redige critérios e aponta ambiguidades — o time decide","A IA substitui o PO nas conversas com stakeholders","A IA mede o fluxo do board na entrega"],"answer":1,"explanation":"No upstream a IA rascunha, questiona e estrutura o item antes de ele entrar na sprint, atuando como par de refinamento — a decisão permanece do time."},{"question":"Por que o refinamento é onde o agilista mais 'gasta energia de facilitação'?","options":["Porque é a cerimônia mais longa da sprint","Porque o PO nunca comparece","Porque uma história mal escrita vira, semanas depois, retrabalho, carryover e discussão áspera na planning","Porque não há timebox definido"],"answer":2,"explanation":"Histórias mal escritas geram retrabalho e carryover; por isso o timebox do refinamento é o recurso mais escasso e onde a IA no upstream mais ajuda."},{"question":"Com IA no upstream, como o timebox do refinamento passa a ser usado?","options":["O tempo do time passa a ser gasto no que só ele pode fazer: decidir, discordar, alinhar — pois a quebra, os critérios e as dúvidas já chegam rascunhados","Redigindo texto ao vivo no telão, como antes","Aprovando automaticamente o que a IA rascunhou","Discutindo o board da sprint anterior"],"answer":0,"explanation":"Chegando com quebra, critérios e lista de perguntas já mapeada, a cerimônia rende o dobro no mesmo timebox e o time foca em decidir, não em redigir."},{"question":"Como a IA no upstream ajuda a Definition of Ready a deixar de ser 'checklist decorativo'?","options":["Removendo a DoR do processo","Delegando a DoR ao time de qualidade apenas","Automatizando a aprovação da DoR","Tornando-a auditável: 'essa história tem critérios testáveis? tem dúvidas sem dono?'"],"answer":3,"explanation":"Com critérios redigidos e dúvidas mapeadas, a DoR vira algo auditável de fato — critérios testáveis e dúvidas com dono — em vez de um checklist decorativo."},{"question":"Onde está o 'ponto de encontro' entre o agilista e o time de qualidade no upstream?","options":["Ambos querem escrever o código mais rápido","Ambos querem a história sem ambiguidade: qualidade olha 'isso é testável?' e o agilista olha 'isso vai fluir sem travar?' — mesma pergunta, lentes diferentes","Ambos querem eliminar o refinamento","Ambos querem operar as mesmas ferramentas de teste"],"answer":1,"explanation":"Upstream bem feito é o par qualidade + agilista trabalhando junto: 'é testável?' e 'vai fluir?' são a mesma pergunta com lentes diferentes, e a mesma sessão de IA responde às duas."}],
  "downstream-ai": [{"question":"O que caracteriza o uso de IA no downstream (delivery), na descrição do material?","options":["Escrever histórias e critérios de aceite antes da sprint","Resumir o estado da sprint/board, detectar itens parados, bloqueios e gargalos a partir dos dados do fluxo, e rascunhar comunicações de entrega","Gerar os testes automatizados da suíte","Estimar os pontos das histórias"],"answer":1,"explanation":"No downstream a IA lê o trabalho em andamento e vira sinal e narrativa: resume o board, aponta o que está parado e rascunha release notes e updates."},{"question":"Por que fluxo e previsibilidade são descritos como 'o território' do agilista onde a IA vira um radar?","options":["Porque a IA decide o que priorizar sozinha","Porque a IA substitui a daily","Porque WIP alto, itens envelhecendo em coluna e bloqueios silenciosos são o que o agilista caça todo dia — e a IA os aponta cinco minutos antes da daily","Porque previsibilidade só depende da ferramenta"],"answer":2,"explanation":"A IA resume o board e aponta o que está parado além do normal, liberando o agilista para o trabalho que só humano faz: destravar pessoas e conversas."},{"question":"A IA aponta que 3 cards estão há 4 dias em 'Code Review'. Como isso muda a qualidade das suas perguntas na daily?","options":["Você move os cards você mesmo","Você pergunta 'alguém tem impedimento?', que convida ao silêncio","Você adia a daily até o review terminar","Você pergunta 'o que está travando os três cards que estão há quatro dias em Code Review?', que convida à resposta"],"answer":3,"explanation":"Facilitação com dado é mais respeitosa: você pergunta sobre o trabalho, não sobre as pessoas — a pergunta específica convida à resposta, o convite genérico convida ao silêncio."},{"question":"Como a IA no downstream libera tempo do agilista, e para quê?","options":["Rascunha updates, resumos de review e release notes a partir do board; o tempo liberado vai para destravar pessoas, mediar conflito e melhorar o processo","Assume a mediação de conflitos do time","Elimina a necessidade de comunicação com stakeholders","Toma as decisões de escopo no lugar do PM"],"answer":0,"explanation":"A IA rascunha o que levaria uma tarde e o agilista edita em minutos; o tempo vai para o trabalho que só humano faz — destravar pessoas, mediar, melhorar o processo."},{"question":"Qual é o 'ponto de encontro' com o time de qualidade quando ambos olham o mesmo resumo de board?","options":["Cada um discute a própria dor isoladamente","O gargalo de teste que a qualidade enfrenta é o gargalo de fluxo que o agilista mede; a daily deixa de ser 'cada um com sua dor' e vira 'o que o fluxo está dizendo'","A qualidade passa a facilitar a daily","O agilista assume os testes"],"answer":1,"explanation":"O gargalo de teste e o gargalo de fluxo são o mesmo visto de lentes diferentes; olhar o mesmo resumo de board unifica a conversa em torno do que o fluxo mostra."}],
  "iniciativas-macro-temas": [{"question":"No planejamento de portfólio com IA, qual é o maior valor do mapa de dependências que ela gera ao cruzar as frentes de um macro tema?","options":["Substituir a sessão de planejamento trimestral, que passa a ser desnecessária","Expor cedo dependências invisíveis que, se descobertas tarde, viram impedimentos no pior momento","Definir sozinha a ordem de prioridade dos épicos sem participação do time","Garantir que cada épico terá a mesma estimativa de esforço"],"answer":1,"explanation":"O texto chama o mapa de dependências de 'ouro particular': dependência invisível no planejamento é o impedimento que você removeria tarde, com times já comprometidos e prazos prometidos."},{"question":"A IA propõe uma quebra do macro tema em 6 épicos e aponta que dois disputam o mesmo time especialista. Como o agilista deve usar isso na sessão de planejamento?","options":["Aceitar a quebra como final, já que a IA analisou todas as frentes","Descartar o alerta, porque disputa de time não é assunto de planejamento","Levar o mapa para a sessão e começar a discussão pelos pontos críticos, não pelo óbvio","Adiar a iniciativa até que o time especialista seja duplicado"],"answer":2,"explanation":"O ganho é chegar com rascunho, mapa de dependências e riscos para que a discussão comece pelos pontos críticos, transformando mediação de opiniões em decisão informada."},{"question":"Um stakeholder pergunta 'como está a iniciativa?'. O que, segundo o material, resolve a dor crônica de responder isso com opinião?","options":["Deixar o fio épico → meta explícito desde o início, para mostrar o avanço em vez de narrá-lo","Encaminhar a pergunta para o PO, que conhece melhor o escopo","Aumentar a frequência das dailies para coletar mais status","Pedir à IA que estime uma data de conclusão para dar ao stakeholder"],"answer":0,"explanation":"Com a rastreabilidade épico → meta explícita, cada entrega concluída se conecta a um avanço de meta que você mostra, não narra — mudando a conversa para uma decisão informada."},{"question":"Qual é o papel da IA na quebra de uma iniciativa em épicos e histórias, na visão do agilista?","options":["Assumir a decisão de priorização no lugar da sessão de planejamento","Eliminar a necessidade do time de qualidade na conversa de portfólio","Acelerar o rascunho da quebra e mapear dependências e riscos, para o humano conduzir a priorização com estrutura","Garantir que a iniciativa cabe no trimestre sem ajuste de escopo"],"answer":2,"explanation":"A IA acelera o rascunho da quebra, cruza frentes para mapear dependências e explicita a contribuição de cada épico para a meta — a decisão de priorização continua sendo conduzida pela facilitação."},{"question":"Por que ter o time de qualidade sentado ao lado do agilista na sessão de quebra de iniciativas é descrito como um aliado?","options":["Porque ele escreve os épicos no Jira mais rápido","Porque aponta risco de qualidade por frente, fazendo o plano nascer honesto","Porque valida a JQL usada para gerar a lista de épicos","Porque assume a facilitação da sessão quando há disputa de agendas"],"answer":1,"explanation":"O texto destaca o time de qualidade apontando risco de qualidade por frente como o aliado que faz o plano nascer honesto."}],
  "confluence-ai": [{"question":"A IA do Confluence barateia as 'duas pontas' do trabalho do agilista com documentação. Quais são elas?","options":["Aprovar páginas e arquivá-las quando ficam obsoletas","Redigir (escrever a ata, estruturar a página) e fazer os outros encontrarem (busca que responde)","Traduzir páginas para outros idiomas e revisar ortografia","Controlar permissões de acesso e versionar o histórico das páginas"],"answer":1,"explanation":"O tempo do agilista se esvai em redigir (ata que leva 40 min para virar texto) e em fazer os outros encontrarem a informação — as duas pontas que a escrita assistida e a busca com resposta barateiam."},{"question":"Um integrante novo pergunta pela quinta vez onde está a página do processo de deploy. Além de a busca do Confluence responder isso, que sinal de facilitação essa repetição carrega?","options":["Que o integrante não foi bem onboardado e precisa de treinamento formal","Que a busca do Confluence está mal configurada","Que falta uma página ou a existente está ruim — uma métrica silenciosa do trabalho de curadoria","Que o agilista deve centralizar todas as perguntas para não perder contexto"],"answer":2,"explanation":"Cada pergunta que chega repetidamente até você é um sinal: falta página ou a existente está ruim — a busca transforma o agilista de 'roteador de perguntas' em curador de fontes."},{"question":"Segundo o material, qual é o efeito composto de documentar passar a custar 10 minutos em vez de uma hora?","options":["O time documenta mais, e o agilista deixa de ser o único guardião da memória coletiva","As páginas ficam mais curtas e perdem detalhe importante","A IA assume totalmente a redação, sem revisão humana","O volume de páginas cresce tanto que a busca fica inútil"],"answer":0,"explanation":"O texto diz que o efeito composto é maior que a soma: quando documentar custa 10 minutos, o time documenta mais e o agilista para de ser o único guardião da memória coletiva."},{"question":"Você tem anotações soltas da retro e quer transformá-las numa página estruturada de acordos. Como a escrita assistida entra nesse fluxo?","options":["Ela publica os acordos automaticamente, sem revisão, para agilizar","Ela gera a primeira versão em segundos, e você revisa e ajusta em vez de redigir do zero","Ela só corrige o tom, sem reorganizar o conteúdo","Ela exige que você já tenha a página pronta para apenas resumir"],"answer":1,"explanation":"O padrão é primeira-versão-em-segundos e revisão humana depois: anotações soltas viram página estruturada em 10 minutos, com o agilista revisando e ajustando."},{"question":"Como a IA do Confluence apoia a facilitação pura das cerimônias, sem facilitar por você?","options":["Conduzindo a retro no seu lugar quando você não pode comparecer","Decidindo quais acordos da retro anterior foram cumpridos","Definindo a pauta do refinamento a partir das permissões das páginas","Eliminando o trabalho braçal — resumir a spec para o refinamento, os acordos para a retro, a página de status para o stakeholder"],"answer":3,"explanation":"A IA não facilita por você; ela elimina o trabalho braçal (resumos de spec, de acordos, de status) que competia com a facilitação pelo seu tempo."}],
  "jira-ai": [{"question":"Quais são as três funções da Atlassian Intelligence embutida no Jira que o material destaca para o dia a dia do agilista?","options":["Criar servidores MCP, configurar agentes Rovo e escrever scripts Groovy","JQL por linguagem natural, resumo de issues e threads, e sugestão de quebra em subtarefas","Montar dashboards eazyBI, publicar no Confluence e atualizar metas no Goals","Detectar bugs no código, rodar testes e gerar relatórios de cobertura"],"answer":1,"explanation":"O tópico trata da IA embutida sem configuração: JQL por linguagem natural, resumo de issues/threads e sugestão de quebra em subtarefas — diferente da integração via MCP e agentes, que é o tópico avançado."},{"question":"Preparando o refinamento, você quer a lista de 'histórias do próximo release sem estimativa e sem critérios de aceite'. Como a JQL por linguagem natural muda essa preparação?","options":["A lista resultante vira a própria pauta da sessão, sem precisar saber JQL ou clicar issue por issue","A IA conduz o refinamento e estima as histórias automaticamente","Ela só funciona se você já souber escrever a JQL manualmente","Ela substitui a necessidade de refinar, pois marca as histórias como prontas"],"answer":0,"explanation":"A pauta se monta sozinha: a pergunta vira JQL em segundos e a lista resultante é a pauta, sem depender de saber JQL nem clicar issue por issue."},{"question":"Na planning, para uma história grande, você pede a sugestão de quebra em subtarefas. Qual é o valor desse rascunho, mesmo que imperfeito?","options":["Ele dispensa a discussão do time, pois já vem pronto","Ele garante que a estimativa da história ficará correta","Ele elimina o quadro em branco — o time reage mais rápido a uma proposta do que a uma página vazia","Ele só serve se a história já estiver estimada"],"answer":2,"explanation":"A sugestão de quebra elimina o quadro em branco; o texto lembra que rascunho ruim também tem valor, pois o time reage mais rápido a uma proposta errada do que a uma página vazia."},{"question":"Um item está travado há 4 dias com uma thread de comentários quilométrica. Como o resumo de issue melhora a sua daily?","options":["Ele fecha o item automaticamente por inatividade","Ele reatribui o item ao plantonista sem você intervir","Ele avisa o canal do time sobre o bloqueio","Ele te dá cinco linhas antes da daily para você chegar sabendo onde a conversa empacou"],"answer":3,"explanation":"O resumo acelera a preparação: cinco linhas antes da daily e você chega sabendo onde a conversa empacou, fazendo a pergunta certa em vez de 'e aí, como está?'."},{"question":"Segundo o material, o que a JQL por linguagem natural muda na autonomia do agilista sobre suas visões de fluxo?","options":["Sua leitura de fluxo deixa de ser limitada pelo domínio de sintaxe — você monta, salva e reusa as consultas sozinho","Ela transfere a criação de boards para quem 'sabe Jira'","Ela impede a criação de filtros personalizados, padronizando tudo","Ela só gera consultas de leitura, nunca dashboards"],"answer":0,"explanation":"Filtros por linguagem natural fazem cada pergunta virar uma consulta que você mesmo monta, salva e reusa — sua leitura de fluxo deixa de ser limitada pelo domínio de sintaxe."}],
  "atlassian-goals": [{"question":"O que o Atlassian Goals torna explícito, navegável e auditável para o agilista?","options":["O lead time e o throughput de cada épico","A ligação entre metas/OKRs e o trabalho real (projetos, épicos, entregas no Jira)","A quantidade de story points de cada sprint","As permissões de acesso às páginas do Confluence"],"answer":1,"explanation":"O Goals conecta metas e OKRs ao trabalho real e torna essa ligação explícita, navegável e auditável — resolvendo a pergunta 'para que meta este épico contribui?'."},{"question":"Ao decompor um macro tema em épicos usando o Goals, você encontra um épico que não se conecta a nenhuma meta. O que isso representa?","options":["Um erro de configuração do Goals que precisa ser corrigido","Uma meta que deveria ser criada às pressas para justificar o épico","Uma pergunta de priorização se fazendo sozinha — um argumento estrutural para a conversa de escopo com o PO","Um sinal de que o épico deve ser marcado como concluído"],"answer":2,"explanation":"Épico que não se conecta a meta nenhuma é uma pergunta de priorização se fazendo sozinha, e dá ao agilista um argumento estrutural para a conversa de escopo com o PO."},{"question":"No fim do mês, uma meta do tribe ficou amarela (em risco). Como o agilista usa o Goals e a IA nesse ponto?","options":["Rebaixa a meta para verde para não alarmar a liderança","Persegue cada líder por status, como sempre fez","Espera a revisão trimestral para tratar o assunto","Pede à IA um rascunho do update a partir do progresso dos épicos ligados, o dono ajusta e publica"],"answer":3,"explanation":"Para a meta que amarelou, você pede à IA um rascunho de update a partir do progresso dos épicos conectados; o dono ajusta e publica — o fim da caçada trimestral por status."},{"question":"Com o Goals, como o papel do agilista no acompanhamento de portfólio se transforma?","options":["De coletor de status para curador do ritmo — garantindo a cadência de updates e a honestidade dos status","De facilitador para redator oficial de todos os updates de meta","De coach para administrador de permissões das metas","De curador para executor das entregas conectadas às metas"],"answer":0,"explanation":"O papel migra de coletor de status para curador do ritmo: garantir que a cadência de updates aconteça e que os status sejam honestos."},{"question":"Quais anti-padrões do sistema de metas o agilista, como coach, está melhor posicionado para enxergar e facilitar?","options":["Metas com muitos épicos e épicos com poucas subtarefas","Meta órfã de trabalho, trabalho órfão de meta, update copiado do anterior e 'tudo verde até virar vermelho'","Metas sem responsável e responsáveis sem acesso ao Jira","Updates escritos pela IA e updates escritos à mão"],"answer":1,"explanation":"O agilista é quem melhor enxerga os anti-padrões: meta órfã de trabalho, trabalho órfão de meta, update copiado do anterior e tudo verde até virar vermelho — facilitar a honestidade do sistema é trabalho de coach."}],
  "rovo": [{"question":"Quais são as três peças do Rovo descritas no material?","options":["Rovo Search (busca conectada), Rovo Chat (conversa com contexto da empresa) e Rovo Agents (agentes que executam ações)","Rovo JQL, Rovo Dashboards e Rovo Automation","Rovo Confluence, Rovo Jira e Rovo Goals","Rovo Prompt, Rovo Memory e Rovo Orchestration"],"answer":0,"explanation":"O Rovo tem três peças: Search (busca conectada por Jira, Confluence e apps), Chat (responde usando o contexto da empresa) e Agents (agentes configuráveis que executam ações), tudo respeitando permissões."},{"question":"No meio da quarta-feira, um PO pergunta no Rovo Chat qual foi a decisão sobre o escopo do épico X e recebe a resposta com link para a ata. Por que isso é descrito como 'escudo de interrupções'?","options":["Porque o Chat impede que o PO acesse o Jira diretamente","Porque cada pergunta respondida pela ferramenta é uma interrupção que você não sofreu e uma dependência de 'pessoa-índice' que o time perdeu","Porque o agilista passa a filtrar todas as perguntas do time","Porque o Chat encaminha a pergunta para o dono do épico"],"answer":1,"explanation":"Como escudo de interrupções, o Chat responde perguntas que hoje passam por você; cada resposta é uma interrupção evitada e uma dependência de 'pessoa-índice' que o time perdeu, dando autonomia a novos integrantes."},{"question":"Você cria um Rovo Agent que toda segunda gera o resumo da semana do time e publica no Confluence. Qual detalhe do desenho preserva a supervisão humana?","options":["O agente envia o resumo direto à liderança para ganhar tempo","O agente decide sozinho o que é risco sem registrar a fonte","O agente publica como rascunho, para você revisar antes da reunião de líderes","O agente só roda se o agilista aprovar cada card individualmente"],"answer":2,"explanation":"O agente publica como rascunho no Confluence para revisão, transformando uma manhã de compilação em dez minutos de revisão — o humano continua sendo o curador."},{"question":"Por que o material diz que projetar um Rovo Agent é um 'novo objeto de facilitação' para o agilista?","options":["Porque exige que o agilista aprenda a programar em Groovy","Porque projetar um agente é escrever um processo executável (papel, fontes, formato, revisão) — desenho de processo, sua especialidade","Porque o agente assume a facilitação das cerimônias no lugar do agilista","Porque substitui a necessidade de acordos de time explícitos"],"answer":1,"explanation":"Projetar um agente é escrever um processo executável — papel, fontes, formato, pontos de revisão — que é desenho de processo, a especialidade de sempre do agilista, num material novo."},{"question":"Segundo o texto, montar um bom Rovo Agent melhora o processo do time antes mesmo de ele rodar. Por quê?","options":["Porque o agente já executa as rotinas durante a configuração","Porque a ferramenta valida automaticamente os acordos do time","Porque a IA reescreve os acordos implícitos por conta própria","Porque as perguntas que um bom agente exige ('o que é risco declarado? onde fica registrado?') forçam o time a explicitar acordos implícitos"],"answer":3,"explanation":"As perguntas que um bom agente exige forçam o time a explicitar acordos que estavam implícitos, então montar o agente já melhora o processo antes de ele rodar."}],
  "eazybi-ai": [{"question":"O 'combo eazyBI + IA' descrito no material é, na verdade, o quê?","options":["Uma feature nativa de IA dentro do próprio eazyBI","Um agente autônomo que monta os dashboards sozinho","O fluxo de exportar os dados/relatórios do eazyBI e pedir a um LLM que os interprete","Uma integração MCP que fecha cards automaticamente"],"answer":2,"explanation":"O combo não é feature nativa: é o fluxo de exportar os dados (ou relatórios) do eazyBI e pedir a um LLM que interprete tendências, anomalias, correlações e uma narrativa clara."},{"question":"Segundo o texto, qual sempre foi o gargalo real do agilista com os dashboards do eazyBI?","options":["O acesso aos dashboards e a licença da ferramenta","A interpretação e o custo de comunicação — o que a curva significa e como explicá-la a quem não lê burndown","A velocidade de carregamento dos relatórios","A quantidade de métricas disponíveis no Jira"],"answer":1,"explanation":"O gargalo nunca foi acesso a dashboard; foi o tempo de interpretação e o custo de comunicação — o que o CFD diz e como explicar isso a um diretor que não lê burndown."},{"question":"Antes da retro, você exporta o lead time por tipo de item de 6 sprints e pede à IA tendências, anomalias e 3 perguntas. Ela nota que o lead time de histórias subiu 40% após mudança de composição do time. Como isso muda a sua postura na retro?","options":["Você chega com o diagnóstico fechado 'o time está lento' e cobra melhoria","Você adia a retro até confirmar os números com cada pessoa","Você delega a condução da retro à IA, que já tem os dados","Você chega com perguntas em vez de diagnósticos — 'o que aconteceu no handoff?' abre conversa"],"answer":3,"explanation":"O efeito de postura é chegar na retro com perguntas em vez de diagnósticos: 'o lead time subiu 40% depois da mudança de composição — o que aconteceu no handoff?' abre conversa; 'o time está lento' fecha."},{"question":"O material descreve o LLM como 'tradutor por audiência'. O que isso significa na prática para a comunicação do agilista?","options":["A mesma tabela vira três perguntas afiadas para a retro e um parágrafo sem jargão para o report de liderança","O LLM traduz os dashboards para outros idiomas","O LLM substitui o julgamento do agilista sobre o contexto do time","O LLM gera um único relatório padrão que serve para todas as audiências"],"answer":0,"explanation":"Na comunicação, o LLM é tradutor por audiência: a mesma tabela vira três perguntas afiadas para a retro e um parágrafo sem jargão para o report de liderança."},{"question":"O CFD mostra a banda 'Em Andamento' engordando. Qual é a atitude correta do agilista quanto ao papel da IA nessa leitura?","options":["Confiar que a IA decide sozinha se é WIP demais ou vazão de menos e comunicar isso como fato","Usar a IA para acelerar a leitura e apontar anomalias, mas manter o julgamento sobre o contexto como seu","Ignorar a IA, pois interpretação de CFD é só intuição","Pedir à IA que altere o limite de WIP automaticamente"],"answer":1,"explanation":"A IA não substitui o julgamento sobre o contexto — ela escala a capacidade de leitura, varrendo dados e apontando o que passaria despercebido; a facilitação com dado continua sendo do agilista."}],
  "scriptrunner-ai": [{"question":"De onde vem o poder de IA no combo com o ScriptRunner, segundo o material?","options":["De uma feature nativa de IA do próprio ScriptRunner","Do combo: usar um assistente de IA para gerar, explicar e revisar o script Groovy","De um agente Rovo que aplica os scripts em produção sozinho","Da JQL por linguagem natural nativa do Jira"],"answer":1,"explanation":"O poder vem do combo, não de feature nativa: usar a IA para gerar o script a partir da descrição, explicar um script herdado e revisar antes de rodar."},{"question":"O agilista herdou um Jira cheio de scripts que ninguém entende e não pode melhorar o workflow. Como o combo IA + ScriptRunner destrava o lado do legado?","options":["Apaga os scripts antigos automaticamente para limpar o Jira","Aplica melhorias direto em produção sem revisão para ganhar tempo","Você cola o script e pede a explicação em português antes de qualquer mudança, gerando de quebra a documentação que nunca existiu","Transfere a responsabilidade dos scripts para o assistente de IA"],"answer":2,"explanation":"Para o legado, você cola o script e pede a explicação em português antes de mexer no workflow — e de quebra gera a documentação que nunca existiu."},{"question":"Na retro, o time combina que subtarefas fechem junto com a história e que itens 5 dias em 'Bloqueado' notifiquem o canal. Qual é o papel do agilista nesse fluxo com a IA?","options":["Escrever o Groovy do zero, já que agora domina a linguagem","Especificar a regra, testar no sandbox e levar o script revisado para o admin aplicar","Aplicar o script em produção assim que a IA o gerar","Delegar tudo ao admin sem participar da especificação"],"answer":1,"explanation":"O papel do agilista é o de quem especifica a regra (facilitação: tornar o combinado executável e sem ambiguidade), testa no sandbox e leva o script revisado para o admin aplicar — não vira programador."},{"question":"Por que o material insiste que o agilista confira os casos de borda (ex.: 'e se a história reabrir?') antes de levar o script?","options":["Porque a IA não consegue gerar scripts Groovy válidos","Porque o admin não tem permissão para testar","Porque casos de borda mudam a estimativa da sprint","Porque script em produção sem revisão pode derrubar o board de um time inteiro"],"answer":3,"explanation":"O texto alerta que script em produção sem revisão derruba o board de um time inteiro — por isso a responsabilidade de testar os casos de borda antes de aplicar continua sendo do agilista."},{"question":"Qual é a diferença central que o combo traz para a fila de melhorias de processo que dependiam de quem 'sabe Groovy'?","options":["É de dependência: antes você esperava semanas por alguém; agora chega com 90% pronto e pede os 10% finais","As melhorias deixam de ser necessárias, pois a IA otimiza o workflow sozinha","O admin passa a ser dispensável no processo","A retro deixa de gerar acordos, pois tudo já está automatizado"],"answer":0,"explanation":"A diferença é de dependência: o acordo da retro vira rascunho de script no mesmo dia; antes se esperava semanas por alguém, agora se chega com 90% pronto e pede os 10% finais."}],
  "jira-automation-ai": [{"question":"Qual é a estrutura de uma regra do Jira Automation, o motor no-code do Jira?","options":["Script Groovy + listener + job agendado","Gatilho (algo acontece) + condição + ação (o Jira faz algo)","Prompt + contexto + resposta","Meta + épico + história"],"answer":1,"explanation":"O Jira Automation é gatilho + condição + ação, sem script; com a IA, você descreve a regra em linguagem natural e ela monta o rascunho com os componentes certos."},{"question":"O material diz que o agilista, na 'manutenção de processo', É a regra de automação 'na versão cara, lenta e que desgasta relacionamento'. O que isso quer dizer?","options":["Que o agilista deve parar de facilitar e virar administrador do Jira","Que cada cobrança manual (item parado, card sem estimativa, órfão) é um gatilho + condição + ação que ele executa à mão","Que a automação é sempre mais barata que qualquer facilitação","Que o Jira já automatiza tudo sem intervenção humana"],"answer":1,"explanation":"Cada cobrança manual é um gatilho + condição + ação executado à mão — o agilista É a regra de automação na versão cara, lenta e que desgasta relacionamento."},{"question":"Na retro, o time combina que nenhum item entra na sprint sem estimativa. Como o agilista transforma esse acordo em sistema antes de a reunião acabar?","options":["Anota que 'o agilista vai conferir' os cards toda sprint","Descreve a regra em linguagem natural, a IA monta, ele revisa e ativa na hora","Abre um chamado para o time técnico implementar via ScriptRunner","Cria uma página no Confluence com o acordo e cobra manualmente"],"answer":1,"explanation":"Em vez de virar 'o agilista vai conferir', ele descreve a regra ('quando um item entrar na sprint ativa sem story points, comente marcando o PO e adicione a etiqueta sem-estimativa'), a IA monta, ele revisa e ativa — o acordo virou automação antes de a reunião acabar."},{"question":"Qual é o ganho 'mais sutil' de uma regra de automação explícita, segundo o texto?","options":["Ela despersonaliza a cobrança: o comentário automático não está de mau humor nem escolhe alvo, e some o atrito de 'o agilista pegou no meu pé'","Ela elimina a necessidade de retros","Ela garante que a sprint sempre feche no prazo","Ela substitui o PO na priorização do backlog"],"answer":0,"explanation":"Regra explícita despersonaliza a cobrança: o comentário automático não está de mau humor, não escolhe alvo, não esquece — some o atrito e sobra a conversa que interessa."},{"question":"Com o board se policiando sozinho via automação, para qual conversa o agilista fica livre?","options":["Para escrever os scripts Groovy que faltam","Para conferir manualmente cada card antes da daily","Para o porquê: por que itens continuam chegando sem estimativa? — lendo o padrão e facilitando a melhoria","Para aprovar cada regra de automação antes de ela disparar"],"answer":2,"explanation":"Quando o board se policia sozinho, o agilista sai do papel de fiscal e volta ao de quem lê o padrão e facilita a melhoria — a conversa sobre por que os itens continuam chegando sem estimativa."}],
  "ai-agent": [{"question":"Segundo a definição do material, o que caracteriza um agente de IA e o diferencia de 'só responder uma pergunta'?","options":["Ele apenas resume textos longos com um clique","Ele executa etapas fixas definidas previamente pelo usuário","Dado um objetivo, ele planeja, usa ferramentas, observa resultados e itera em loop até concluir","Ele só funciona conectado a um servidor MCP"],"answer":2,"explanation":"Um agente é um LLM que, dado um objetivo, planeja, usa ferramentas, observa resultados e itera em loop com autonomia para decidir os próximos passos — vai além de responder uma pergunta."},{"question":"Quando parte do backlog passa a ser 'executada por agente com supervisão humana', quais convenções de fluxo o agilista precisa rever?","options":["A cor dos cards e o nome das colunas do board","Estimativa, Definition of Done e o que significa 'em progresso' quando quem progride é um software em loop","A frequência das dailies e a duração da sprint","As permissões de acesso ao Jira"],"answer":1,"explanation":"Autonomia não-determinística quebra premissas do fluxo: como estimar uma tarefa cujo esforço humano é revisar, onde entra a revisão no DoD, e o que é 'em progresso' quando quem progride é um software rodando em loop."},{"question":"Antes da planning, você dá a um agente o objetivo de levantar o status de 8 histórias, identificar as bloqueadas e resumir o risco de não fechar na sprint. Que cuidado o material recomenda ao usar o resultado?","options":["Confiar integralmente, pois o agente cruzou os comentários","Conferir por amostragem antes de usar, porque agente erra com confiança","Repassar o objetivo para o time refazer manualmente","Publicar o panorama direto para os stakeholders sem revisão"],"answer":1,"explanation":"O agente volta com um panorama que você confere por amostragem antes de usar, porque agente erra com confiança — a hora economizada em coleta vira hora de facilitação."},{"question":"O material afirma que o agilista NÃO precisa saber implementar um ciclo ReAct. O que ele precisa, então, reconhecer e fazer?","options":["Que autonomia não-determinística quebra premissas do fluxo, e facilitar os novos acordos antes que o board vire ficção","Programar o loop de decisão do agente em Groovy","Impedir que o time use agentes até dominarem a técnica","Substituir as cerimônias por execução automatizada"],"answer":0,"explanation":"Ele não precisa saber implementar um ciclo ReAct; precisa reconhecer que autonomia não-determinística quebra premissas do fluxo e facilitar os novos acordos antes que o board vire ficção."},{"question":"Por que boa parte do dia do agilista é 'o caso de uso ideal' para delegar a um agente?","options":["Porque facilitação de cerimônias é totalmente automatizável","Porque o agente decide sozinho a prioridade do backlog","Porque é trabalho de coleta e síntese de várias etapas com objetivo claro — compilar dados de fluxo, cruzar cards com comentários, preparar cerimônias","Porque elimina a necessidade de conferir os dados"],"answer":2,"explanation":"Compilar dados de fluxo, cruzar cards com comentários, preparar cerimônias e montar relatórios são tarefas de coleta e síntese de várias etapas com objetivo claro — o caso ideal para delegar e revisar."}],
  "agentic-workflow": [{"question":"Qual é a diferença entre um workflow agêntico e um agente autônomo, traduzida para o vocabulário do agilista?","options":["Workflow usa IA e agente não usa","Workflow tem etapas fixas (previsibilidade); agente decide as etapas sozinho (adaptação)","Workflow é sempre mais caro que o agente autônomo","Workflow serve só para código e agente só para relatórios"],"answer":1,"explanation":"Workflow agêntico tem etapas definidas por você (previsibilidade, testável); agente autônomo decide as etapas sozinho (flexibilidade, imprevisibilidade) — no fundo, uma conversa sobre previsibilidade versus adaptação."},{"question":"O time diz 'vamos fazer um agente que cuida do report de sprint'. Como o agilista reformula, e por quê?","options":["Aprova o agente autônomo, pois soa mais moderno","Recusa qualquer automação do report","Aponta que o report tem etapas fixas (coletar métricas, listar entregas, destacar bloqueios), então um workflow determinístico resolve com resultado igual toda semana","Sugere que cada pessoa escreva o report à mão"],"answer":2,"explanation":"O report tem etapas fixas, então um fluxo determinístico com IA nos pontos de redação resolve com resultado igual toda semana — autonomia se reserva para o exploratório."},{"question":"Segundo o material, qual é a pergunta de facilitação que o agilista leva ao refinamento quando o time propõe 'fazer um agente' para um processo?","options":["Quanto custa a licença da ferramenta de IA?","Quem vai revisar o código do agente?","As etapas desse processo são conhecidas? Se sim, por que precisamos que uma IA decida o fluxo em vez de só preencher as lacunas?","O agente vai substituir alguém do time?"],"answer":2,"explanation":"A pergunta de facilitação é: as etapas desse processo são conhecidas? Se sim, por que precisamos que uma IA decida o fluxo em vez de só preencher as lacunas? — autonomia é custo, não troféu."},{"question":"O time testa as duas versões do report. Na retro seguinte, qual é a constatação registrada no material?","options":["A versão autônoma foi mais rápida e sem retrabalho","A versão com etapas fixas gerou menos retrabalho de revisão do que a autônoma, que mudava de formato e uma vez inventou uma métrica","As duas versões foram idênticas em qualidade","Nenhuma das versões conseguiu gerar o report"],"answer":1,"explanation":"A versão com etapas fixas gerou menos retrabalho de revisão do que a autônoma, que cada semana escrevia num formato diferente e uma vez inventou uma métrica — a escolha da arquitetura virou decisão de processo."},{"question":"Por que o material afirma que 'autonomia é custo, não troféu' na leitura de esforço do agilista?","options":["Porque autonomia custa em variabilidade, exatamente o que você não quer num processo que roda toda semana","Porque agentes autônomos são sempre proibidos por governança","Porque workflows nunca erram","Porque autonomia exige contratar mais desenvolvedores"],"answer":0,"explanation":"Autonomia custa em variabilidade — exatamente o que não se quer num processo recorrente; para processos com etapas conhecidas, workflow determinístico dá saída consistente e custo previsível."}],
  "multi-agent": [{"question":"Como o material descreve a organização de um sistema multi-agente, usando a metáfora que fala a língua do agilista?","options":["Como um único generalista faz-tudo, mais rápido que humanos","Como um organograma: papéis especializados, um coordenador e handoffs entre eles","Como uma esteira de produção sem pessoas envolvidas","Como um banco de dados de decisões passadas"],"answer":1,"explanation":"Em vez de um agente faz-tudo, há vários especializados coordenados por um orquestrador — um organograma com papéis, um coordenador e handoffs entre eles."},{"question":"Onde os sistemas multi-agente falham, e por que isso é familiar ao agilista?","options":["Na velocidade de cada agente isolado","Nos mesmos lugares que times humanos falham: comunicação, passagem de contexto e retrabalho na integração","Na quantidade de tokens que cada agente consome","Na escolha do modelo de linguagem"],"answer":1,"explanation":"O comportamento crítico não mora em nenhum agente isolado, mora na coordenação — eles falham onde times humanos falham: comunicação, passagem de contexto e retrabalho na integração."},{"question":"No refinamento de um épico de 'time de agentes', o dev estima alto e o PO estranha. Como o agilista facilita traduzindo para linguagem de fluxo?","options":["'O custo está em cada agente individual, então reduzam o número de agentes'","'A estimativa está errada, refaçam sem contar a integração'","'O custo não está em cada agente, está nos handoffs — como quando duas squads dividem uma feature e a integração é onde tudo quebra'","'Adiem o épico até a IA ficar mais barata'"],"answer":2,"explanation":"O agilista traduz: o custo não está em cada agente, está nos handoffs, como quando duas squads dividem uma feature e a integração é onde tudo quebra — coordenar agentes é trabalho de integração."},{"question":"Depois de destravar a conversa da estimativa, como o épico multi-agente é quebrado para virar progresso medível no board?","options":["Por handoff testável — cada passagem de contexto entre agentes vira uma entrega verificável","Por agente — cada agente vira uma história independente","Em uma única entrega de 'está 80% pronto'","Por modelo de IA usado em cada etapa"],"answer":0,"explanation":"Quebrar o épico por handoff testável faz cada passagem de contexto virar entrega verificável, e o progresso passa a ser medível no board em vez de um '80% pronto' que nunca fecha."},{"question":"Que sintomas de fluxo o agilista reconhece nos anti-padrões de um sistema multi-agente?","options":["O coordenador que delega sem contexto é o épico mal quebrado; o subagente que chuta é a squad que assume premissa em silêncio; o deadlock é o card travado esperando quem não sabe que é esperado","O modelo lento é a daily longa; o token caro é a sprint estourada","O agente correto é o card bem estimado; o incorreto é o mal estimado","Não há paralelo entre agentes e problemas de time humano"],"answer":0,"explanation":"O material mapeia: coordenador que delega sem contexto = épico mal quebrado; subagente que chuta = squad que assume premissa em silêncio; deadlock de orquestração = card travado esperando alguém que não sabe que é esperado."}],
  "subagents": [{"question":"Qual é o motivo central do padrão orquestrador + subagentes, segundo o material?","options":["Reduzir o custo de tokens de cada chamada","Isolamento de contexto: o subagente faz a exploração 'suja' e devolve só a conclusão, mantendo o contexto do principal limpo","Permitir que cada subagente decida a arquitetura do sistema","Eliminar a necessidade de um agente orquestrador"],"answer":1,"explanation":"O motivo central é isolamento de contexto: o subagente lê dezenas de arquivos e varre logs (a exploração 'suja') e devolve só a conclusão, mantendo o contexto do principal limpo."},{"question":"O material compara escrever o handoff de ida para um subagente a uma prática que o agilista já conhece. Qual?","options":["A Definition of Ready: escrever objetivo, escopo, restrições e formato de retorno, como quem escreve um bom ticket","O burndown chart da sprint","A retrospectiva dos acordos do time","O limite de WIP do board"],"answer":0,"explanation":"'Escreva o handoff de ida como quem escreve um bom ticket' — objetivo, escopo, restrições, formato de retorno — é Definition of Ready aplicada à delegação para subagentes."},{"question":"Para preparar a revisão trimestral, você dispara análises paralelas (fluxo, escopo, riscos) e pede uma síntese. Por que não jogar tudo num prompt único?","options":["Porque o prompt único é mais caro em licença","Porque despejar tudo produz síntese contaminada — o modelo se perde no próprio contexto e a conclusão sai diluída","Porque a IA não aceita prompts longos","Porque cada análise precisa de um modelo de IA diferente"],"answer":1,"explanation":"Despejar tudo num prompt único produz a síntese contaminada: o modelo se perde no meio do próprio contexto e a conclusão sai diluída; o desenho orquestrador-trabalhadores resolve com escopos separados."},{"question":"No cenário da revisão trimestral, qual é a 'quarta rodada' que faz o papel do cético, equivalente ao advogado do diabo numa retro?","options":["Uma rodada que soma todos os dados brutos das três análises","Uma rodada que refaz as três análises do zero","Uma rodada que pergunta 'para cada conclusão, que dado a contradiz?'","Uma rodada que publica a síntese sem revisão"],"answer":2,"explanation":"A quarta rodada faz o papel do cético — 'para cada conclusão, que dado a contradiz?' — a versão IA do advogado do diabo que o agilista faria numa retro, deixando a síntese enxuta e auditável."},{"question":"Quando o time do produto adotar o padrão de subagentes, por que o agilista entende que a estimativa cresce, mesmo sem revisar system prompts?","options":["Porque 'adicionar um subagente' nunca é só adicionar — é adicionar duas interfaces (handoffs) que precisam de log, teste e verificação","Porque cada subagente exige um novo desenvolvedor no time","Porque subagentes rodam mais devagar que um agente único","Porque o orquestrador precisa ser reescrito a cada subagente"],"answer":0,"explanation":"O sistema falha nas interfaces, não nos nós: cada handoff é um ponto de falha que precisa de log, teste e verificação, então 'adicionar um subagente' é adicionar duas interfaces — e a estimativa cresce."}],
  "mcp": [{"question":"O que é o MCP (Model Context Protocol), segundo o material?","options":["Uma ferramenta de BI que monta dashboards a partir do Jira","Um protocolo aberto que padroniza como modelos de IA se conectam a ferramentas, dados e sistemas externos","Um agente autônomo que fecha cards no Jira","Uma feature nativa de resumo do Confluence"],"answer":1,"explanation":"MCP é um protocolo aberto (criado pela Anthropic) que padroniza como modelos de IA se conectam a ferramentas, dados e sistemas — em vez de integração customizada, você expõe um servidor MCP e qualquer IA compatível usa."},{"question":"Para o agilista que vive de ler fluxo, qual é a diferença prática que o MCP representa?","options":["Trocar de LLM sempre que precisar de mais contexto","A diferença entre colar prints de board num chat e simplesmente perguntar 'como está a sprint?'","Poder escrever JQL sem conhecer a sintaxe","Rodar o eazyBI mais rápido"],"answer":1,"explanation":"Com MCP, a IA enxerga os dados reais (Jira, Confluence, dashboards) de forma padronizada; para quem lê fluxo, é a diferença entre alimentar a IA com relatórios e simplesmente perguntar 'como está a sprint?'."},{"question":"O material diz que o agilista não vai implementar um servidor MCP, mas ganha duas capacidades práticas. Quais?","options":["Pedir as integrações certas e participar da conversa de segurança com conhecimento de causa","Escrever o código do servidor e aprovar o deploy","Configurar o vector DB e ajustar a temperatura do modelo","Substituir o Tech Lead nas decisões de arquitetura"],"answer":0,"explanation":"Entender o conceito permite pedir as integrações certas ('quero que o assistente leia os cards do projeto X e os acordos no Confluence') e participar da conversa de segurança com conhecimento de causa."},{"question":"Na conversa de segurança sobre uma IA conectada via MCP, qual raciocínio de permissão o agilista já aplica ao administrar o Jira?","options":["Toda IA deve ter acesso total para ser útil","Uma IA que lê o board do seu time não deveria enxergar o de outro, e ferramentas que escrevem merecem mais cuidado do que as que só leem","Permissões atrapalham a produtividade e devem ser removidas","Só o Tech Lead pode opinar sobre permissões"],"answer":1,"explanation":"É o mesmo raciocínio de permissão do Jira: uma IA que lê o board de um time não deveria enxergar o de outro, e ferramentas que escrevem (fechar card, editar estimativa) merecem mais cuidado do que as que só leem."},{"question":"Hoje você gasta meia sexta-feira exportando dados do Jira e montando o report de fluxo à mão. Com um MCP conectando a IA ao Jira, o que muda?","options":["O report deixa de ser necessário para o time","A IA passa a decidir sozinha quais bloqueios priorizar","Você pergunta 'quais cards estão parados há mais de 5 dias e por quê?' e o tempo de coleta vira tempo de conversa com o time sobre os bloqueios","Você precisa colar prints atualizados a cada consulta"],"answer":2,"explanation":"Com MCP você pergunta direto à fonte 'quais cards estão parados há mais de 5 dias e por quê?' e recebe a lista com comentários resumidos — o tempo de coleta vira tempo de conversa sobre os bloqueios, que era o objetivo do report."}],
  "orchestration": [{"question":"O que fazem as ferramentas e frameworks de orquestração de IA (LangChain, LangGraph, CrewAI, n8n) descritos no material?","options":["Treinam modelos de linguagem do zero","Conectam LLMs, ferramentas, memória e fluxos, cuidando de loops, estado, chamadas de ferramenta e tratamento de erro","Substituem o Jira e o Confluence","Geram apenas resumos de páginas"],"answer":1,"explanation":"São ferramentas que conectam LLMs, ferramentas, memória e fluxos para construir aplicações de IA sem reinventar a roda, cuidando de loops, estado, chamadas de ferramenta e tratamento de erro."},{"question":"Por que as ferramentas low-code como o n8n são chamadas de 'porta de entrada' para o agilista?","options":["Porque exigem que ele aprenda a programar antes","Porque permitem automatizar o operacional do próprio processo ágil sem depender de dev nem de sprint alheia","Porque só o time técnico pode usá-las","Porque substituem as cerimônias do time"],"answer":1,"explanation":"Ferramentas low-code como o n8n são a porta de entrada para o agilista automatizar o operacional do processo (aviso de card parado, resumo postado, alerta de WIP) ligando nós num canvas, sem depender de dev."},{"question":"Você monta um fluxo low-code que toda sexta coleta cards parados, pede à IA o resumo do motivo e posta no canal antes da retro. Qual é o efeito na retro?","options":["A retro deixa de acontecer, pois tudo já foi resolvido","A IA conduz a retro no lugar do agilista","O time chega com os pontos de atrito já mapeados, e a discussão parte dos dados, não da memória de cada um","O time precisa recolher os dados manualmente durante a retro"],"answer":2,"explanation":"O fluxo entrega os pontos de atrito mapeados antes da retro, e a discussão parte dos dados, não da memória de cada um."},{"question":"Entender que 'o LLM é um nó num grafo maior' dá ao agilista qual leitura sobre confiabilidade?","options":["Que a confiabilidade vive nas conexões (retries, tratamento de erro, gatilho que dispara duas vezes), então há um limite: fluxo artesanal versus processo oficial","Que qualquer fluxo pode virar processo oficial sem engenharia","Que o LLM sozinho já é confiável para qualquer processo","Que a confiabilidade depende só do modelo escolhido"],"answer":0,"explanation":"A confiabilidade vive nas conexões — retries, tratamento de erro, o que acontece se o gatilho disparar duas vezes; saber isso mostra o limite entre o fluxo artesanal e o que vira processo oficial e merece engenharia de verdade."},{"question":"Três sprints depois, outra squad pede o mesmo fluxo de sexta-feira. O que essa transição do artesanal para o oficial ilustra sobre o papel do agilista?","options":["Que ele deve manter tudo artesanal para não depender de ninguém","Que saber onde passa a linha do que vale industrializar é decisão de processo, e o vocabulário para discuti-la agora é dele","Que a squad deve construir seu próprio fluxo do zero","Que protótipos nunca devem virar processo oficial"],"answer":1,"explanation":"Quando o protótipo vira processo de várias squads, o agilista envolve o time técnico para industrializá-lo com robustez; saber onde passa essa linha é decisão de processo, e o vocabulário para discuti-la é dele."}],
  "memory": [{"question":"Qual é a diferença entre memória de curto e de longo prazo de um agente, segundo o material?","options":["Curto prazo é o vector DB; longo prazo é a janela de contexto","Curto prazo é o histórico da conversa atual (janela de contexto); longo prazo persiste informação entre sessões","Curto prazo guarda decisões; longo prazo guarda perguntas","Não há diferença prática entre as duas"],"answer":1,"explanation":"Memória de curto prazo é o histórico da conversa atual na janela de contexto; a de longo prazo persiste informação entre sessões (geralmente em vector DB), permitindo lembrar de fatos e acordos anteriores."},{"question":"O material compara um assistente sem memória a qual personagem familiar ao agilista?","options":["Ao estagiário eternamente novo, para quem você re-explica o contexto do time a cada conversa","Ao stakeholder que só quer prazos","Ao dev que estima alto","Ao PO que muda o escopo"],"answer":0,"explanation":"O assistente sem memória é o estagiário eternamente novo, para quem você re-explica o contexto do time a cada conversa; a memória aposenta essa re-explicação e traz continuidade."},{"question":"Por que o material diz que a memória de um agente 'merece desconfiança'?","options":["Porque ela nunca guarda nada entre sessões","Porque ela é um cérebro que raciocina sozinho","Porque é um mecanismo de busca e injeção de contexto que falha de formas silenciosas: dado desatualizado, não encontrado na hora, ou vazado entre contextos","Porque ela só funciona com permissões desativadas"],"answer":2,"explanation":"A memória não é um cérebro, é um mecanismo de busca e injeção de contexto que falha em silêncio: o que ela 'lembra' pode estar desatualizado, pode não ser encontrado na hora, ou pode vazar entre contextos de times diferentes."},{"question":"Você facilita várias squads. Qual risco da memória o material pede atenção redobrada nesse caso?","options":["A memória apagar os acordos ao fim de cada sprint","O vazamento de contexto — o combinado do time A aparecer na conversa sobre o time B","A memória guardar dados demais e ficar lenta","A memória exigir revalidação de tudo, mesmo o estável"],"answer":1,"explanation":"A memória pode vazar entre contextos — o combinado do time A aparecendo na conversa sobre o time B — atenção redobrada para quem facilita várias squads."},{"question":"O time reviu o limite de WIP de 4 para 5. Qual é o critério prático que o material dá para lidar com a memória do assistente de facilitação?","options":["Confie à memória o que é estável e revalide o que é decisão viva; confirme que o novo acordo foi atualizado, senão a IA cobra um combinado que já não existe","Apague toda a memória a cada mudança de acordo","Trate tudo o que a IA lembra como verdade final","Nunca use memória para acordos de time"],"answer":0,"explanation":"O critério é: confie à memória o que é estável, revalide o que é decisão viva; ao mudar o WIP para 5, confirme que a memória foi atualizada, senão a IA cobraria com confiança um combinado que já não existe."}],
  "human-in-the-loop": [{"question":"Na lente do agilista, decidir onde a IA age sozinha e onde para para aprovação humana (HITL) é, antes de tudo, uma questão de quê?","options":["Capacidade técnica do modelo: quanto mais avançado, menos gates precisa.","Desenho de processo e análise de risco — o mesmo ofício de definir o que o time decide sozinho e o que precisa de alinhamento.","Custo de infraestrutura: gates encarecem a operação e devem ser minimizados.","Preferência do stakeholder, que define caso a caso o que precisa de aprovação."],"answer":1,"explanation":"O material trata HITL como desenho de processo — o ofício do agilista — cuja lógica é análise de risco: ações reversíveis e baratas correm sozinhas; as que afetam pessoas, compromissos ou dados pedem checkpoint."},{"question":"O time quer um agente que atualiza cards no Jira. Facilitando o desenho do fluxo pela régua de reversibilidade, qual arranjo faz mais sentido?","options":["Toda ação do agente exige aprovação humana, para garantir segurança máxima.","O agente tem autonomia total, pois automação parcial não gera ganho de produtividade.","Comentar e etiquetar podem ser autônomos; mover card para 'concluído' ou alterar estimativa só com aprovação, porque mexem nas métricas e no que o stakeholder enxerga.","Alterar estimativa é livre (reversível) e comentar exige aprovação (fica registrado publicamente)."],"answer":2,"explanation":"A régua do material é reversibilidade e impacto: ações reversíveis e de baixo impacto correm sozinhas; mover para concluído ou mexer em estimativa afeta métricas e compromissos, então pede checkpoint."},{"question":"Um time definiu que o agente de IA precisa de aprovação humana para quase toda ação, e agora são 200 aprovações por dia. O material alerta para qual risco?","options":["Fadiga de aprovação: o gate vira carimbo automático, como a cerimônia que virou ritual vazio — a estrutura existe, mas a atenção morreu.","Sobrecarga de servidor, porque cada aprovação dispara uma nova chamada ao modelo.","Perda de rastreabilidade, já que aprovações em massa não ficam registradas.","Nenhum: quanto mais aprovações, mais seguro o sistema fica."],"answer":0,"explanation":"O material diz que gate demais é tão perigoso quanto gate de menos: 200 aprovações por dia viram carimbo automático — a fadiga de aprovação é prima da cerimônia que virou ritual vazio."},{"question":"Depois de desenhar a matriz 'ação × autonomia' com o time, qual é o encaminhamento coerente com a prática ágil?","options":["Congelar a matriz como política fixa da empresa, imune a mudanças.","Deixar a matriz com o time de qualidade, pois é decisão puramente técnica.","Arquivar a matriz e reabrir a discussão só se ocorrer um incidente grave.","Tornar o combinado parte do acordo de trabalho do time e revisá-lo na retro — removendo gates que ninguém lê e criando gate novo para o incidente que escapou."],"answer":3,"explanation":"No material, a matriz vira acordo de trabalho do time e, como todo acordo, é revisada na retro: gates inúteis saem e o incidente que escapou ganha gate novo."},{"question":"Segundo a lente do agilista, qual princípio resume o bom desenho de pontos de controle (HITL)?","options":["Automatizar 100% sempre que o modelo tiver acurácia acima de 90%.","Poucos pontos de controle, carregados de contexto, colocados onde o erro custa caro.","Um ponto de controle por etapa do processo, para não deixar nada passar.","Concentrar todas as aprovações em uma única pessoa, para padronizar o critério."],"answer":1,"explanation":"O material compara facilitar HITL a facilitar processo: poucos pontos de controle, carregados de contexto, no lugar onde o erro custa caro — nem gate demais, nem de menos."}],
  "guardrails": [{"question":"Na tradução do material para o mundo do agilista, guardrails são o equivalente a quê?","options":["Os acordos de trabalho da IA: limites explícitos sobre o que ela pode dizer e fazer, escritos antes do incidente.","O burndown da IA: um gráfico do que ela já aprendeu ao longo das sprints.","A definição de pronto do modelo: o critério que diz quando ele foi treinado o suficiente.","A velocidade da IA: quantas respostas ela consegue gerar por sprint."],"answer":0,"explanation":"O material define guardrails como os acordos de trabalho da IA — limites explícitos sobre o que ela pode dizer e fazer, definidos antes do incidente e não depois."},{"question":"No refinamento de um chatbot de atendimento, a estimativa do time saiu o dobro do que o PO esperava. Por que, segundo o material, isso costuma acontecer com histórias de IA?","options":["Porque o time superestima por medo de errar com uma tecnologia nova.","Porque metade do esforço é guardrail — impedir que o bot prometa prazo, dê desconto ou fale do concorrente — trabalho invisível que não aparece na demo.","Porque chatbots exigem hardware caro, e isso entra na estimativa da história.","Porque o PO não descreveu bem os critérios de aceite do caminho feliz."],"answer":1,"explanation":"O material aponta que impedir o que o bot não deve fazer consome metade da sprint e não aparece na demo; quem estima olhando só o caminho feliz subestima sistematicamente."},{"question":"Toda feature de IA carrega dois trabalhos, segundo o material. Quais são?","options":["Treinar o modelo e depois monitorá-lo em produção.","Escrever o prompt e escolher o provedor de LLM.","Fazer a coisa funcionar e impedir que ela faça o que não deve (definir política, implementar barreiras e testá-las de forma adversarial).","Reduzir custo de tokens e reduzir latência das respostas."],"answer":2,"explanation":"O material é explícito: fazer funcionar e impedir o que não deve são os dois trabalhos; quando a quebra da história ignora o segundo, a estimativa vem errada e a sprint estoura 'sem explicação'."},{"question":"Aplicando a lente de guardrails ao refinamento, como o agilista ajuda a quebrar uma história de chatbot para refletir o esforço real?","options":["Adiando a parte de segurança para uma sprint futura, para entregar valor antes.","Pedindo ao time uma estimativa única, para não burocratizar o refinamento.","Removendo os limites da história e tratando-os como bug quando aparecerem.","Separando em 'responder corretamente' e 'recusar o que não deve', cada uma com critérios próprios, e refletindo isso no roadmap da iniciativa."],"answer":3,"explanation":"No exemplo do material, o time quebra a história em 'responder corretamente' e 'recusar o que não deve', cada uma com critérios próprios, e o roadmap passa a refletir o esforço real."},{"question":"Qual pergunta de facilitação o material sugere que o agilista faça no refinamento de qualquer feature de IA?","options":["Qual modelo vamos usar e quanto custa cada mil tokens?","O que essa IA não pode fazer de jeito nenhum, e onde está esse trabalho no backlog?","Quantas respostas por segundo a IA precisa entregar?","Quem vai escrever o prompt e revisar a gramática das respostas?"],"answer":1,"explanation":"O material dá essa pergunta ao agilista como ferramenta de facilitação, para trazer à tona o esforço de guardrail que costuma ficar invisível na estimativa."}],
  "evals": [{"question":"Segundo o material, qual analogia do mundo ágil descreve melhor o que é uma feature de IA sem eval?","options":["Uma história sem estimativa de esforço.","Uma sprint sem retrospectiva.","Uma história sem critério de aceite mensurável — não dá para saber se está pronta nem se a última mudança melhorou ou piorou.","Um backlog sem priorização."],"answer":2,"explanation":"O material equipara aceitar uma feature de IA sem eval a aceitar uma história sem critério de aceite: 'parece boa' não diz se está pronta nem se a mudança da semana ajudou."},{"question":"Na planning de uma feature de IA, o agilista pergunta 'qual é o critério de aceite mensurável?' e vem o silêncio. Qual é o encaminhamento sugerido pelo material?","options":["Nasce uma história de eval: montar o dataset de referência e definir a meta (ex.: 90% de acerto), como item visível e estimável.","Adiar a feature até o modelo melhorar sozinho.","Aceitar a feature como pronta, pois IA não tem critério objetivo.","Repassar a decisão de aceite inteiramente para o stakeholder."],"answer":0,"explanation":"No material, do silêncio nasce uma história de eval — montar o dataset e definir a meta — trabalho real que precisa estar visível no backlog, não como tarefa fantasma."},{"question":"Por que, para o agilista, o número do eval é tão valioso nas cerimônias?","options":["Porque substitui a necessidade de demo na review.","Porque impressão vira número, e número é o que as cerimônias consomem: entra na definição de pronto, aparece na review e alimenta a conversa com stakeholder.","Porque garante que o modelo nunca mais vai errar.","Porque permite dispensar o time de qualidade da avaliação."],"answer":1,"explanation":"O material destaca que o eval transforma 'parece boa' em número, e número é o que a definição de pronto, a review e a conversa de priorização consomem."},{"question":"Nas sprints seguintes, o número do eval sobe de 82% para 91% e entra na review junto com a demo. Como o material descreve o valor disso para stakeholders?","options":["Como uma métrica de vaidade que não deve ser exposta à diretoria.","Como um relatório técnico que só o time de qualidade entende.","Como prova de que a feature nunca mais precisará de manutenção.","Como um 'burndown de qualidade' — os stakeholders veem a qualidade evoluir sprint a sprint, e 'quando fica pronto?' vira uma linha num gráfico."],"answer":3,"explanation":"O material chama isso de burndown de qualidade: a resposta a 'quando fica pronto?' deixa de ser 'estamos ajustando' e vira uma linha num gráfico, construindo confiança."},{"question":"Além de definir 'pronto', que segundo ganho o eval traz para o replanejamento, segundo o material?","options":["Elimina a necessidade de refinamento das histórias seguintes.","Dá uma régua objetiva: se o número estagnou três sprints seguidas, a conversa sobre mudar a abordagem parte de dado, não de frustração.","Garante que a velocidade do time aumente a cada sprint.","Permite prometer datas exatas de entrega ao stakeholder."],"answer":1,"explanation":"O material aponta que o eval dá régua objetiva para replanejar: número estagnado por três sprints embasa em dado a decisão de mudar de abordagem."}],
  "llm-as-judge": [{"question":"Que problema o padrão 'LLM as a judge' resolve, e por que ele interessa ao agilista mesmo sem IA no processo?","options":["Elimina a necessidade de refinamento, gerando histórias automaticamente.","Avaliar em escala saídas que não têm resposta única — o mesmo problema de saber se as 40 histórias do backlog estão bem escritas ou se as atas seguem o padrão.","Garante que o modelo nunca produza vieses.","Reduz o custo de tokens ao usar um modelo menor como avaliador."],"answer":1,"explanation":"O material mostra que o padrão resolve avaliar em escala o que não tem resposta única — um problema que o agilista já tem com histórias, atas e critérios de aceite."},{"question":"No padrão LLM-as-judge, qual é 'o trabalho nobre' que, segundo o material, é justamente o do agilista?","options":["Escrever o código do avaliador e integrá-lo ao pipeline.","Escolher o modelo que fará o julgamento.","Escrever a rubrica — definir o que é uma história boa ou uma ata completa —, a mesma habilidade de transformar 'qualidade' em critérios observáveis do Definition of Ready.","Rotular manualmente todas as 40 histórias antes de rodar o juiz."],"answer":2,"explanation":"O material aponta que escrever a rubrica (transformar qualidade em critérios observáveis) é o trabalho nobre e é do agilista — a mesma habilidade do Definition of Ready."},{"question":"Você usou uma IA para avaliar as 40 histórias do backlog contra critérios que definiu. Antes de confiar no resultado para priorizar, o que o material recomenda?","options":["Confiar direto, pois a IA é objetiva por natureza.","Substituir a revisão humana por completo a partir de agora.","Pedir ao juiz que também reescreva as histórias, além de avaliá-las.","Conferir uma amostra das notas contra o seu próprio julgamento — se o juiz estiver desregulado, ajustar os critérios primeiro."],"answer":3,"explanation":"O material mostra o agilista conferindo uma amostra (concordou com 8 de 10) antes de confiar; se o juiz estivesse desregulado, ajustaria os critérios primeiro."},{"question":"Um colega propõe: 'a IA vai dar nota nos PRs do time'. Qual pergunta de facilitação o material já deixa pronta para o agilista?","options":["Comparamos o julgamento da IA com o de humanos numa amostra? Qual foi a concordância?","Qual modelo é mais barato para rodar essa avaliação?","Quantos PRs por dia a IA consegue avaliar?","A IA consegue também aprovar e mergear o PR sozinha?"],"answer":0,"explanation":"O material dá essa pergunta ao agilista: como o juiz é um modelo probabilístico com vieses, ele precisa ser calibrado contra julgamento humano antes de merecer confiança."},{"question":"Depois de avaliar as 40 histórias, o time foca nas 12 piores no refinamento. Como o material descreve o papel do 'juiz' nesse resultado?","options":["O juiz decide quais histórias entram na sprint.","O juiz não decide nada; ele aponta onde o tempo de facilitação do agilista rende mais.","O juiz substitui o refinamento, que deixa de ser necessário.","O juiz reescreve as 12 histórias automaticamente."],"answer":1,"explanation":"O material é claro: o juiz não decide nada — ele prioriza onde o tempo de facilitação rende mais, e a decisão continua com o time."}],
  "observability": [{"question":"Que paralelo o material faz entre o tracing de uma IA e a prática de fluxo do agilista?","options":["Tracing é como um relatório de velocidade: mede quantas respostas a IA entrega por sprint.","Tracing torna visível o caminho que a execução percorreu, passo a passo — como olhar o board e ver em qual coluna o card travou.","Tracing é como o burndown: mostra quanto falta para a IA terminar a tarefa.","Tracing serve para estimar quanto uma feature de IA vai custar."],"answer":1,"explanation":"O material compara o trace a olhar o board para ver onde o card travou: torna visível o caminho da execução, e trabalho visível é a base de qualquer melhoria de fluxo."},{"question":"Na retro, o time reclama que 'o assistente de triagem erra demais'. Qual movimento o material sugere ao agilista para tirar a conversa do achismo?","options":["Decidir na hora desligar a automação, já que ela não funciona.","Anotar 'melhorar a IA' como ação e cobrar na próxima retro.","Perguntar 'onde exatamente ele erra? O trace mostra?' e pedir que o dado seja trazido na sprint seguinte.","Trocar o modelo por um maior, que erra menos."],"answer":2,"explanation":"No material, em vez de achismo ou decisão precipitada, o agilista pede o dado do trace: 'onde exatamente ele erra?' — a pergunta que tem resposta objetiva."},{"question":"Como o material descreve o salto que o trace provoca numa discussão sobre uma falha de IA?","options":["De opinião ('o modelo é ruim') para dado ('o erro está na etapa de busca, não na resposta') — o mesmo salto de uma retro que sai do 'sinto que estamos lentos' para o gráfico de cycle time.","De problema técnico para problema de negócio, tirando o time da conversa.","De decisão do time para decisão do stakeholder.","De qualitativo para quantitativo apenas em custo de tokens."],"answer":0,"explanation":"O material mostra que, com o trace, a discussão deixa de ser opinião e vira dado — o mesmo salto de uma retro que troca a sensação pelo gráfico de cycle time."},{"question":"O dev traz os dados e descobre-se que 80% dos erros vêm de uma etapa específica (a busca de histórico). Segundo o material, qual é o desfecho desejável dessa retro?","options":["Concluir que a automação é irreparável e removê-la.","Registrar que 'a IA é imprevisível' e seguir em frente.","Escalar imediatamente para o stakeholder sem plano.","A conversa vira uma ação concreta de melhoria, com dono e prazo — mesmo padrão de uma retro bem facilitada."],"answer":3,"explanation":"No material, o dado do trace transforma a reclamação em ação concreta com dono e prazo; sem o trace, o time teria abandonado uma automação que precisava de conserto pontual."},{"question":"Sobre o papel do agilista diante das ferramentas de observabilidade (LangSmith, Langfuse, Arize), o que o material afirma?","options":["Ele precisa aprender a escrever queries e abrir árvores de spans para liderar a análise.","Ele não opera a ferramenta, mas saber que essa visibilidade existe muda as perguntas que faz — 'onde o fluxo da IA quebra?' passa a ter resposta objetiva.","Ele deve assumir a operação da ferramenta para não depender do time de qualidade.","Ele deve evitar o tema, pois observabilidade é assunto exclusivo de infraestrutura."],"answer":1,"explanation":"O material é explícito: o agilista não vai abrir spans nem escrever queries, mas saber que a visibilidade existe muda suas perguntas de facilitação."}],
  "model-drift": [{"question":"Qual premissa silenciosa do planejamento o conceito de drift quebra, segundo o material?","options":["A de que estimativas em pontos são sempre confiáveis.","A de que o que foi entregue continua funcionando até alguém mexer no código — para features de IA, 'pronto' tem prazo de validade.","A de que o time consegue manter a mesma velocidade a cada sprint.","A de que o backlog sempre reflete a prioridade do negócio."],"answer":1,"explanation":"O material abre com 'seis meses sem um commit e o sistema piorando sozinho': drift quebra a premissa de que o entregue continua funcionando — 'pronto' tem prazo de validade."},{"question":"Se o portfólio não reserva capacidade para monitorar e recalibrar features de IA, o que acontece com esse trabalho, segundo o material?","options":["Ele deixa de ser necessário, pois o provedor mantém o modelo atualizado.","Ele é absorvido automaticamente pela velocidade do time.","Ele vira trabalho invisível — não está em card nenhum, mas come a sprint do mesmo jeito.","Ele é transferido integralmente para o time de qualidade sem impacto no fluxo."],"answer":2,"explanation":"O material alerta que sem capacidade prevista a manutenção vira trabalho invisível: aquele que não está em card nenhum mas consome a sprint."},{"question":"Seis meses após o lançamento, o classificador de chamados começa a errar e a reclamação chega via stakeholder, não via monitoramento. Que ajuste de processo o material propõe na retro?","options":["Refazer a feature do zero na próxima sprint.","Tratar o caso como bug pontual e fechar o card.","Terceirizar a manutenção para o provedor do modelo.","Toda feature de IA no portfólio ganha um item recorrente de acompanhamento de qualidade, e o macro tema passa a prever essa capacidade, sprint sim, sprint não."],"answer":3,"explanation":"O material propõe transformar sustentação de IA em item recorrente do portfólio, com capacidade prevista — não algo que depende de alguém 'achar um tempinho'."},{"question":"Um stakeholder pergunta por que uma feature de IA entregue há meses ainda consome capacidade. Como o material sugere que o agilista sustente essa conversa?","options":["Explicando que não é retrabalho, mas a natureza do produto: 'o mundo mudou ao redor dela' — uma resposta defensável quando se entende o mecanismo do drift.","Admitindo que a entrega anterior foi malfeita e prometendo não repetir.","Dizendo que o time errou a estimativa e vai compensar com horas extras.","Evitando o tema para não expor fragilidade da feature."],"answer":0,"explanation":"O material dá ao agilista o argumento: entender o drift permite explicar que a manutenção contínua não é retrabalho, e sim a natureza de um produto de IA."},{"question":"Sobre a divisão de papéis no tratamento do drift, o que o material afirma?","options":["O agilista deve aprender a calcular PSI e montar o golden set para liderar tecnicamente.","O agilista assume o monitoramento porque o time de qualidade não tem tempo.","O agilista não calcula PSI nem monta golden set — seu papel é garantir que esse trabalho exista como trabalho: visível, estimável e com capacidade prevista.","O drift é responsabilidade exclusiva do provedor do modelo, então ninguém do time precisa agir."],"answer":2,"explanation":"O material separa os papéis: a técnica (PSI, golden set) é do time; o agilista garante que a manutenção seja trabalho visível no backlog com capacidade prevista."}],
  "prompt-injection": [{"question":"Segundo o material, por que features de IA que leem conteúdo de fora (tickets, e-mails, documentos) carregam um risco que não aparece na demo?","options":["Porque conteúdo externo consome mais tokens e encarece a operação.","Porque dado não confiável pode se comportar como código executável — instruções escondidas podem sequestrar o comportamento da IA (injeção indireta).","Porque a IA fica mais lenta ao processar textos longos de clientes.","Porque textos externos costumam ter erros de português que confundem o modelo."],"answer":1,"explanation":"O material parte de que dado não confiável se comporta como código executável: toda feature que lê conteúdo externo carrega um risco de injeção que não aparece na demo onde o cronograma nasce."},{"question":"No refinamento de um assistente que lê e resume tickets de clientes, qual pergunta o material sugere que o agilista coloque na mesa?","options":["Quantos tickets por hora o assistente consegue resumir?","Qual modelo é mais barato para essa tarefa?","E se um cliente escrever instruções maliciosas dentro do ticket?","O resumo pode ser gerado em outro idioma?"],"answer":2,"explanation":"O material mostra o agilista fazendo exatamente essa pergunta no refinamento — o silêncio da sala revela que ninguém havia pensado no risco de injeção."},{"question":"Por que o material insiste que a conversa de risco de prompt injection aconteça no refinamento, e não depois?","options":["Porque no refinamento há mais desenvolvedores disponíveis para discutir.","Porque só no refinamento o modelo ainda pode ser trocado.","Porque depois do lançamento a segurança não pode mais ser adicionada.","Porque segurança discutida no refinamento custa um critério de aceite; discutida depois do incidente, custa um post-mortem, um stakeholder em pânico e semanas de replanejamento."],"answer":3,"explanation":"O material contrasta o custo: no refinamento é um critério de aceite; depois do incidente é post-mortem, pânico do stakeholder e replanejamento — um ângulo de governança que é do agilista."},{"question":"Sobre o que o agilista precisa dominar em prompt injection, o que o material afirma?","options":["Ele não precisa saber escrever payloads nem como o ataque funciona por dentro — precisa saber qual pergunta colocar na mesa e quando.","Ele precisa aprender a construir a suíte adversarial e o gate no CI.","Ele deve assumir os testes de segurança para não sobrecarregar o time.","Ele deve evitar o tema, que é exclusivo da equipe de segurança."],"answer":0,"explanation":"O material é claro: o facilitador não precisa saber como o ataque funciona por dentro — precisa saber qual pergunta de risco colocar na mesa e em que momento."},{"question":"Da pergunta feita no refinamento nasceram um critério de aceite de segurança e uma tarefa de teste. Que efeito o material destaca sobre a estimativa da história?","options":["A estimativa some, pois segurança não é estimável.","A estimativa cresce de forma honesta, antes do compromisso com o stakeholder, e não depois.","A estimativa diminui, pois o risco foi eliminado.","A estimativa é transferida para outra iniciativa."],"answer":1,"explanation":"O material diz que a estimativa cresce de forma honesta antes do compromisso com o stakeholder — o custo real de colocar IA em contato com conteúdo que a empresa não controla."}],
  "responsible-ai": [{"question":"O caso de abertura do material — tickets em linguagem informal caindo sistematicamente para baixa prioridade — é apresentado como o quê para o agilista?","options":["Um bug de performance que atrasa a fila de atendimento.","Um risco de produto e de reputação que ninguém decidiu criar — e risco dessa natureza é pauta do agilista no planejamento.","Um problema de usabilidade da interface de tickets.","Uma falha de treinamento que só o time de dados pode discutir."],"answer":1,"explanation":"O material trata o caso como risco de produto e reputação que ninguém decidiu criar; risco assim é pauta do agilista, ao lado de dependências e outros riscos de iniciativa."},{"question":"Segundo o material, o que o agilista precisa (e o que NÃO precisa) fazer em relação a justiça/fairness numa iniciativa de IA?","options":["Definir pessoalmente a métrica de fairness e implementá-la.","Auditar o dataset de treino em busca de viés.","Não definir a métrica de fairness — mas garantir que a pergunta 'quem decidiu o que é justo aqui, e onde está documentado?' seja feita no refinamento da iniciativa.","Evitar o tema, pois é decisão exclusiva do jurídico."],"answer":2,"explanation":"O material separa: definir a métrica não é do agilista; garantir que a pergunta multiárea sobre justiça seja feita no refinamento (quando ainda custa barato) é."},{"question":"Numa iniciativa de IA que prioriza atendimento de clientes, qual pergunta o material sugere levar ao refinamento?","options":["Quantos clientes por minuto a IA consegue priorizar?","Qual modelo tem o menor custo por priorização?","A IA consegue priorizar sem intervenção humana nenhuma?","A priorização trata clientes de perfis diferentes de forma consistente? Quem valida isso, e contra qual critério?"],"answer":3,"explanation":"O material apresenta exatamente essa pergunta; se a resposta for silêncio, nasceu um item de trabalho e a definição de pronto ganha um critério de equidade com dono."},{"question":"No registro de riscos da iniciativa, como o material sugere que 'viés não auditado' seja tratado?","options":["Entra ao lado de 'dependência externa atrasada', com a mesma seriedade.","Fica fora do registro, por ser um tema técnico do modelo.","Entra apenas se um cliente reclamar formalmente.","É registrado só depois do lançamento, como lição aprendida."],"answer":0,"explanation":"O material coloca 'viés não auditado' no registro de riscos com a mesma seriedade de uma dependência externa atrasada."},{"question":"O material lembra que IA responsável também toca o próprio uso do agilista. Que cuidado ele cita ao pedir à IA um resumo das contribuições da retro?","options":["Verificar apenas se o resumo está gramaticalmente correto.","Revisar se o resumo não apaga as falas de quem participa menos ou não penaliza um padrão de trabalho legítimo — porque o resumo influencia percepção, e percepção influencia o time.","Confiar no resumo, pois a IA é neutra por natureza.","Pedir que a IA classifique as contribuições por qualidade individual."],"answer":1,"explanation":"O material alerta que o resumo influencia percepção (e percepção influencia carreira); por isso o agilista revisa se ele não apaga falas de quem participa menos antes de repassar."}],
  "rlhf-alignment": [{"question":"Segundo o material, por que um modelo alinhado (via RLHF) tende à bajulação (sycophancy)?","options":["Porque foi programado para nunca discordar de nenhum usuário.","Porque aprendeu a maximizar a nota de anotadores humanos, e concordância historicamente pontua bem — apresente uma ideia com entusiasmo e ele tende a validá-la.","Porque modelos maiores são naturalmente mais educados.","Porque a temperatura alta faz o modelo concordar mais."],"answer":1,"explanation":"O material explica que o modelo aprendeu a maximizar a nota de anotadores e concordância pontua bem; o resultado é o viés de agradar quem apresenta a ideia."},{"question":"Por que a bajulação da IA é uma armadilha específica para quem facilita decisões de processo, segundo o material?","options":["Porque a IA se recusa a opinar sobre cerimônias.","Porque a IA sempre discorda para provocar o debate.","Porque a ferramenta usada para pensar tem um viés treinado para agradar: concordância da IA não é validação, é o comportamento mais provável dado o seu tom.","Porque a IA só entende de código, não de processo."],"answer":2,"explanation":"O material alerta que concordância da IA não é validação — é o comportamento mais provável dado o tom entusiasmado de quem apresenta a proposta."},{"question":"Você pede à IA uma opinião sobre reorganizar as cerimônias do time e ela elogia o plano em três parágrafos. Sabendo do alinhamento, o que o material sugere fazer?","options":["Aceitar o elogio como validação e apresentar a proposta na retro.","Descartar a IA como ferramenta inútil para decisões.","Refazer a pergunta com um tom ainda mais entusiasmado.","Inverter o jogo: 'aja como um crítico cético — liste os cinco maiores riscos dessa proposta e em que contexto ela falharia'."],"answer":3,"explanation":"No material, o agilista pede crítica explícita ('aja como crítico cético'), e as respostas mudam completamente — duas apontam problemas reais que viram ajustes antes da retro."},{"question":"Além da bajulação, que outro comportamento o material atribui ao modo como o alinhamento funciona?","options":["O over-refusal (recusar pedidos legítimos) e mudanças de comportamento entre versões — não são defeitos aleatórios, mas consequência de como o alinhamento é construído.","A incapacidade de gerar textos longos.","A perda total de memória entre mensagens.","A recusa em usar ferramentas externas."],"answer":0,"explanation":"O material cita o over-refusal e a mudança de comportamento entre versões como consequências diretas do alinhamento, não erros aleatórios."},{"question":"Qual hábito o material aponta como o que 'separa quem usa IA como espelho de quem usa como contraparte de raciocínio'?","options":["Sempre usar o modelo mais avançado disponível.","Nunca aceitar o primeiro elogio e sempre extrair a crítica.","Fazer a mesma pergunta várias vezes e escolher a melhor resposta.","Pedir sempre respostas mais curtas para economizar tokens."],"answer":1,"explanation":"O material fecha com esse hábito: nunca aceitar o primeiro elogio e sempre extrair a crítica é o que separa usar a IA como espelho de usá-la como contraparte de raciocínio."}],
  "computer-use": [{"question":"Que tipo de trabalho do agilista o material aponta como o principal candidato a ser delegado a agentes de Computer Use?","options":["A facilitação de cerimônias como retro e planning.","A definição de prioridades do backlog junto ao PO.","O trabalho operacional em ferramentas sem integração: sistemas legados, planilhas de status sem API, apresentações mensais montadas copiando número por número.","A negociação de prazos com stakeholders."],"answer":2,"explanation":"O material aponta que Computer Use atinge exatamente as ferramentas sem integração — o sistema legado, a planilha sem API, a apresentação montada copiando número por número."},{"question":"Um agente de navegador preenche a planilha de portfólio da diretoria a partir do eazyBI e informa 'preenchida com sucesso'. Qual lição do material o agilista aplica?","options":["Confiar na conclusão declarada pelo agente, pois ele executou a tarefa.","Nunca confiar na conclusão declarada pelo agente — a planilha 'preenchida com sucesso' merece a mesma revisão que se exige das asserções: o agente executa, você julga.","Repassar a planilha direto à diretoria para economizar tempo.","Pedir ao agente que ele mesmo valide o próprio preenchimento."],"answer":1,"explanation":"O material enfatiza: nunca confie na conclusão declarada pelo agente; o agente executa e o humano confere os totais antes de enviar."},{"question":"O time propõe trocar os testes E2E por agentes de Computer Use. Qual pergunta de planning o material coloca na boca do agilista?","options":["Qual agente tem a interface mais bonita?","Quantos cliques por minuto o agente consegue dar?","O agente sabe programar os próprios testes?","Isso deixa nosso pipeline mais lento ou menos determinístico? Quanto desse custo entra recorrente na sprint?"],"answer":3,"explanation":"O material dá ao agilista a pergunta que conecta a decisão técnica ao fluxo: impacto na velocidade e no determinismo do pipeline e no custo recorrente da sprint."},{"question":"Segundo o material, qual é o trade-off central de agentes de Computer Use que o agilista precisa ler?","options":["Flexibilidade alta, mas custo por execução e variabilidade que afetam a previsibilidade do pipeline.","Baixo custo, mas exigem hardware dedicado.","Total determinismo, mas pouca flexibilidade.","Nenhum trade-off relevante: substituem qualquer automação com vantagem."],"answer":0,"explanation":"O material descreve o trade-off como flexibilidade alta versus custo por execução e variabilidade — exatamente o que afeta a previsibilidade do pipeline."},{"question":"Na planning, qual resposta do time indica, segundo o material, que ele entendeu o trade-off de usar agentes em testes?","options":["Vamos trocar tudo por agentes, é mais moderno.","O agente explora, e a regressão continua com scripts determinísticos (modelo híbrido).","Agentes são sempre mais baratos, então usamos em tudo.","Deixamos o agente decidir sozinho quais testes rodar."],"answer":1,"explanation":"O material aponta o modelo híbrido — o agente explora e a regressão fica com scripts determinísticos — como sinal de que o time entendeu o trade-off; 'trocar tudo por agentes' pede uma conversa mais longa antes do compromisso."}],
  "hallucination-detection": [{"question":"Qual é a pergunta central de faithfulness que o material sugere que vire reflexo do agilista antes de repassar qualquer texto gerado por IA?","options":["Isso está bem escrito e é convincente?","Isso é suportado pela fonte, ou foi inventado?","Isso está no tom certo para a diretoria?","Isso cabe em uma página?"],"answer":1,"explanation":"O material coloca essa pergunta como reflexo: 'isso é suportado pela fonte ou foi inventado?' — porque quem repassa a informação assina por ela."},{"question":"Você pediu à IA um resumo do andamento da iniciativa para a diretoria e o texto cita uma entrega 'concluída' que ainda está em revisão. Por que, segundo o material, ninguém percebeu?","options":["Porque a frase era fluente e confiante, exatamente como uma alucinação bem escrita se apresenta.","Porque o resumo era longo demais para ser lido.","Porque o Jira estava indisponível no momento.","Porque a diretoria não acompanha o andamento."],"answer":0,"explanation":"O material descreve a alucinação como uma resposta plausível, bem escrita e factualmente falsa; a fluência e a confiança da frase mascararam o erro."},{"question":"Depois do susto, qual versão manual da técnica de decomposição o material mostra o agilista adotando?","options":["Pedir à IA que reescreva o resumo várias vezes até parecer certo.","Trocar de modelo de IA a cada resumo.","Pedir 'para cada afirmação, cite o card ou documento de origem' e conferir as afirmações principais contra o Jira antes de enviar.","Deixar de usar IA para resumos executivos."],"answer":2,"explanation":"O material mostra o agilista adotando a decomposição manual: exigir fonte por afirmação e conferir as principais no Jira — o resumo continua economizando tempo, mas nunca mais viaja sem verificação."},{"question":"No planejamento, como o conceito de detecção de alucinação muda a leitura de risco do agilista, segundo o material?","options":["Uma feature de IA sem taxa de alucinação medida é uma feature com risco desconhecido — e a medição é trabalho que precisa estar visível no backlog.","Alucinação é problema só de chatbots de produto, não de features internas.","Como a IA sempre inventa, não vale a pena medir a taxa.","Basta trocar por um modelo maior para eliminar o risco sem medição."],"answer":0,"explanation":"O material afirma que sem taxa de alucinação medida o risco é desconhecido; a medição (dataset de avaliação, gate de faithfulness) é trabalho visível, não implícito no 'testar'."},{"question":"Quando o time pede tempo para construir o dataset de avaliação e o gate de faithfulness, qual frase o material diz ser a única que o agilista deveria aceitar levar a um stakeholder?","options":["O bot parece bom nos testes que fizemos.","A IA raramente erra, então está pronto.","Trocamos por um modelo melhor, agora confia mais.","Sabemos quanto o bot inventa, e decidimos que é aceitável."],"answer":3,"explanation":"O material contrapõe 'o bot parece bom' a 'sabemos quanto o bot inventa e decidimos que é aceitável', afirmando que só a segunda deveria ser levada a um stakeholder."}],
  "agent-eval": [{"question":"Avaliar a trajetória de um agente — o caminho, não só o resultado — é comparado no material a qual prática que o agilista já faz com times?","options":["Medir a velocidade da sprint pelo total de pontos entregues.","Olhar o fluxo, não só o burndown: um resultado bom obtido com heroísmo, WIP estourado e revisão pulada é sorte, não capacidade.","Contar quantos bugs foram abertos na sprint.","Comparar a estimativa planejada com a realizada."],"answer":1,"explanation":"O material equipara avaliação de trajetória a olhar o fluxo e não só o burndown: resultado bom por processo ruim é sorte — e sorte não escala, não se estima e não sustenta compromisso."},{"question":"Na review, o time demonstra um agente que triou corretamente todos os bugs da semana e a sala se empolga. Qual é a pergunta de trajetória que o material sugere?","options":["Ele acertou pelo caminho certo? Se o volume dobrar ou o formato do log mudar, continua acertando?","Quantos bugs por minuto ele consegue triar?","Qual modelo de IA está por trás do agente?","Podemos colocá-lo para triar também os bugs antigos?"],"answer":0,"explanation":"O material coloca essa pergunta na boca do agilista: não 'funcionou dessa vez?', mas se o caminho é estável o suficiente para o fluxo depender dele."},{"question":"Ao abrir os traces, descobre-se que o agente pulou a verificação de duplicidade em 3 dos 10 casos, acertando por sorte porque não havia duplicatas naquela semana. Que desfecho o material propõe?","options":["Aprovar o agente, pois o resultado final foi correto.","Descartar o agente e voltar à triagem manual.","A definição de pronto do agente ganha um critério de processo: as verificações obrigatórias precisam aparecer no trace, toda vez.","Aumentar o volume de bugs para testar o agente ao limite."],"answer":2,"explanation":"O material adiciona um critério de processo à definição de pronto do agente — as verificações obrigatórias devem aparecer no trace sempre —, a mesma maturidade de 'entregamos, mas como entregamos?'."},{"question":"Por que, segundo o material, um agente instável importa para o mundo do agilista?","options":["Porque consome mais tokens e encarece a operação.","Porque vira uma fonte nova de variabilidade no sistema — retrabalho imprevisível, exatamente o que corrói lead time e previsibilidade.","Porque exige um servidor mais potente.","Porque atrasa a demo na review."],"answer":1,"explanation":"O material aponta que um agente instável é uma nova fonte de variabilidade e retrabalho imprevisível — o que corrói lead time e previsibilidade."},{"question":"Sobre a divisão de papéis na avaliação de agentes, o que o material afirma?","options":["O agilista deve escrever as asserções sobre os traces e calibrar o juiz.","O agilista assume a avaliação técnica porque conhece o fluxo.","A avaliação de trajetória é dispensável quando o resultado é bom.","O agilista não escreve asserções nem calibra juiz — mas usa a lente de trajetória para fazer a pergunta certa quando o time passa a depender de agentes."],"answer":3,"explanation":"O material separa: a técnica (asserções, calibração) é do time de qualidade; a lente de trajetória dá ao agilista a pergunta certa na hora certa."}],
  "flaky-detection": [{"question":"Por que o material chama testes flaky de 'ladrão de previsibilidade' que interessa diretamente ao agilista?","options":["Porque deixam o código mais lento em produção.","Porque pipeline vermelho sem causa real gera card parado esperando rerun, troca de contexto e merge adiado — engordando o cycle time semana após semana, sem nunca virar incidente.","Porque consomem muitos tokens de IA ao serem re-executados.","Porque exigem contratar mais desenvolvedores."],"answer":1,"explanation":"O material descreve flakiness como um ladrão que rouba em pequenas quantias: nunca vira incidente nem ganha card, mas engorda o cycle time via reruns, troca de contexto e merges adiados."},{"question":"Segundo o material, qual é 'o custo mais grave' da flakiness, além do tempo perdido?","options":["A corrosão da confiança no sinal: quando o time passa a ignorar o vermelho, o pipeline vira teatro e a definição de pronto vira ficção.","O aumento da conta de infraestrutura do CI.","A perda de cobertura de testes.","A lentidão do editor de código dos desenvolvedores."],"answer":0,"explanation":"O material aponta que o custo mais grave é a corrosão da confiança no sinal: o pipeline vira teatro e a definição de pronto que depende dele vira ficção."},{"question":"Qual é, segundo o material, a transformação que torna a IA sobre histórico do CI 'ouro' para quem facilita?","options":["Ela corrige os testes flaky automaticamente.","Ela elimina a necessidade de retrospectiva.","Ela transforma 'o CI é instável' (desabafo) em 'estes testes causam esta fração das falhas falsas, custando tantas horas por semana' (dado negociável) — porque reclamação genérica não entra em backlog, número entra.","Ela substitui o time de qualidade na operação do pipeline."],"answer":2,"explanation":"O material destaca que a IA transforma desabafo em dado negociável, e é isso que permite ao agilista transformar reclamação genérica em item de backlog priorizável."},{"question":"Na retro, 'o pipeline vive quebrando' aparece pela terceira vez seguida como desabafo. O que o material sugere ao agilista fazer?","options":["Anotar mais um post-it e revisitar na próxima retro.","Perguntar a quem testa se dá para usar o histórico do CI para quantificar: quantos testes são flaky e quanto tempo o time perde re-rodando builds.","Decidir remover os testes que mais falham.","Escalar a instabilidade diretamente para a diretoria."],"answer":1,"explanation":"O material mostra o agilista, em vez de anotar mais um post-it, pedindo a quantificação do histórico do CI — o que transforma o desabafo em investimento com retorno medível."},{"question":"O material lembra que a política de quarentena de testes flaky (o que bloqueia merge, quem é dono, qual o prazo de correção) é o quê?","options":["Uma decisão técnica isolada do time de qualidade.","Uma configuração automática que a IA define sozinha.","Uma regra imposta pela diretoria.","Um acordo de time — não decisão técnica isolada — que o agilista ajuda a construir e a manter vivo na sprint."],"answer":3,"explanation":"O material trata a política de quarentena como acordo de time (não decisão técnica isolada), do tipo que o agilista ajuda a construir e a manter vivo."}],
  "rca-ai": [{"question":"Por que a compressão da investigação de causa-raiz (de horas para minutos) via IA aparece direto nas métricas do agilista, segundo o material?","options":["Porque reduz o número de testes automatizados necessários.","Porque enquanto se garimpa a causa, o card do incidente fica parado no board — menos tempo de card bloqueado significa menos interrupção não planejada e mais previsibilidade.","Porque diminui o custo de tokens do time.","Porque aumenta a velocidade da sprint automaticamente."],"answer":1,"explanation":"O material mostra que cada hora de garimpo é hora de lead time e time em modo reativo; comprimir essa fase aparece como menos card bloqueado e mais previsibilidade nas métricas."},{"question":"O material aponta um 'segundo presente' da RCA com IA que é inteiramente do agilista. Qual é?","options":["O padrão de raciocínio serve para o fluxo, não só para incidente técnico — dá para aplicar a mesma lógica sobre os dados dos cards para investigar por que a previsibilidade caiu.","A IA passa a escrever os post-mortems sozinha.","A IA prioriza o backlog no lugar do PO.","A IA elimina a necessidade de retrospectivas."],"answer":0,"explanation":"O material destaca que a mecânica de RCA (dar sinais heterogêneos, pedir hipóteses ranqueadas com evidência, validar antes de agir) se aplica idêntica aos dados do fluxo."},{"question":"Qual é a 'regra de ouro' que o material transpõe da RCA para o uso do agilista?","options":["Confiar na primeira hipótese, pois a IA é objetiva.","Aplicar a correção antes de validar, para ganhar tempo.","Tratar cada hipótese como réu, não testemunha: a IA propõe; quem valida com o time é você.","Usar sempre o maior número possível de hipóteses."],"answer":2,"explanation":"O material cita a regra de ouro: cada hipótese é réu, não testemunha; a IA propõe e o agilista valida com o time antes de agir."},{"question":"O throughput caiu 30% no último mês e o comitê quer explicação na quinta. Como o material sugere que o agilista use a IA?","options":["Pedir à IA que reescreva o relatório do mês anterior.","Deixar a IA decidir sozinha a causa e levar ao comitê.","Pedir à IA uma previsão do throughput do próximo mês.","Exportar os dados dos cards do período (transições, tempos por coluna, bloqueios, comentários) e pedir hipóteses de causa com evidência apontando cards específicos."],"answer":3,"explanation":"No material, o agilista exporta os dados dos cards e pede hipóteses ranqueadas com evidência; a IA aponta cards de um componente parados em 'revisão' esperando a mesma pessoa dividida com outro projeto."},{"question":"Segundo o material, qual é a diferença que a RCA com IA ajuda o agilista a criar diante de um stakeholder?","options":["A diferença entre 'o mês foi difícil' (desculpa) e 'identificamos o gargalo, eis a evidência, eis a correção' (causa com dado e plano) — a diferença entre perder e ganhar a confiança.","A diferença entre entregar cedo ou tarde.","A diferença entre usar um modelo grande ou pequeno.","A diferença entre ter ou não ter testes automatizados."],"answer":0,"explanation":"O material contrapõe 'o mês foi difícil' a 'identificamos o gargalo, eis a evidência, eis a correção', chamando isso de diferença entre perder e ganhar a confiança do stakeholder."}],
  "test-prioritization": [{"question":"A pergunta central da priorização de testes por risco — 'se só posso rodar 500 dos 8.000 testes em 10 minutos, quais 500 escolho?' — é comparada no material a qual decisão do agilista?","options":["A definição da meta da sprint com o PO.","A priorização do backlog: dado que não cabe tudo, o que gera mais valor primeiro? É ordenação sob restrição.","A escolha do modelo de IA que o time vai usar.","A alocação de pessoas entre projetos."],"answer":1,"explanation":"O material equipara a pergunta a priorizar o backlog — ordenação sob restrição — decisão em que o agilista tem mais quilometragem na sala."},{"question":"Por que, segundo o material, a priorização de testes por risco costuma ficar invisível na conversa de melhoria do time?","options":["Porque o time de qualidade a esconde de propósito.","Porque não tem impacto real no fluxo.","Porque mora dentro do CI e ninguém a traz para a conversa de melhoria — é uma alavanca de fluxo que fica fora do radar.","Porque só funciona em times grandes."],"answer":2,"explanation":"O material diz que a alavanca fica invisível porque mora dentro do CI; entender o conceito permite ao agilista reconhecê-la quando as métricas de fluxo degradam."},{"question":"O cumulative flow mostra cards acumulando na coluna de validação há três sprints, e a suíte leva 2 horas por PR. Que conceito o material sugere que o agilista traga para a discussão de melhoria?","options":["Aumentar o WIP para compensar a espera.","Remover a etapa de validação do fluxo.","Contratar mais QAs para rodar a suíte em paralelo.","E se rodássemos primeiro só os testes relevantes para cada mudança, e a suíte completa ficasse como rede de segurança no merge?"],"answer":3,"explanation":"O material mostra o agilista trazendo a seleção por risco (test impact analysis) para a discussão: rodar primeiro os testes relevantes e deixar a suíte completa como rede de segurança no merge."},{"question":"Depois de prototipada a seleção por risco, o feedback de PR cai de 2 horas para 25 minutos. Como o material descreve o efeito no mundo do agilista?","options":["No mês seguinte o cycle time da coluna cai junto — uma melhoria de fluxo que dá para mostrar no dashboard e contar na review, com antes e depois.","O número de testes cai pela metade, reduzindo a cobertura.","A velocidade da sprint dobra imediatamente.","O time deixa de precisar de refinamento."],"answer":0,"explanation":"O material mostra o cycle time da coluna caindo junto — uma melhoria de fluxo visível no dashboard e contável na review com antes e depois."},{"question":"O PO pergunta: 'mas não estamos testando menos?'. Qual é a resposta honesta que o material dá ao agilista?","options":["Sim, mas o risco é baixo o suficiente para aceitar.","Reordenar não é descartar — a suíte completa continua rodando, só não mais na frente do fluxo.","Sim, cortamos os testes menos importantes para ganhar velocidade.","Não sei, isso é decisão do time de qualidade."],"answer":1,"explanation":"O material dá a resposta do artigo: reordenar não é descartar — a suíte completa continua rodando como rede de segurança no merge, só não mais na frente do fluxo."}],
  "jailbreak": [{"question":"Perto do lançamento do chatbot, o QA pede uma sprint de red teaming e um stakeholder pressiona para ir direto para produção porque 'está funcionando nas demos'. Segundo a lente do agilista, qual é a melhor forma de mediar essa conversa?","options":["Ceder à pressão do stakeholder, já que demos que funcionam são evidência suficiente de prontidão.","Fazer uma pergunta de risco de negócio ('qual o custo de um print do nosso bot falando algo indevido circulando publicamente?'), tornando a comparação entre uma sprint de teste e um incidente de marca explícita.","Assumir você mesmo a execução do red teaming para não atrasar o cronograma.","Explicar ao stakeholder os detalhes técnicos das técnicas de role-play e codificação usadas nos jailbreaks."],"answer":1,"explanation":"O papel do agilista é traduzir a decisão em risco de negócio, não em técnica: comparar o custo de uma sprint de teste ao de um incidente de reputação torna a decisão óbvia e traz o patrocínio do próprio stakeholder."},{"question":"O artigo compara jailbreak a 'engenharia social aplicada a uma máquina'. Por que isso faz do tema um assunto do agilista, e não só de quem testa?","options":["Porque o agilista precisa aprender a escrever os prompts de ataque para validar o produto.","Porque jailbreak é um problema puramente técnico que não afeta o planejamento.","Porque produto com IA exposta ao público carrega um risco de reputação que não aparece em nenhum critério de aceite funcional, e gerir esse risco disputa espaço no cronograma — disputa que o agilista media.","Porque cabe ao agilista aprovar ou vetar cada resposta que o modelo recusa dar."],"answer":2,"explanation":"O risco de reputação de uma IA contornável é gestão de risco organizacional; esse trabalho compete por espaço no cronograma com feature, e mediar essa disputa é papel do agilista."},{"question":"Uma equipe trata 'testar a segurança do chatbot' como um card único a ser feito no fim da iniciativa. Por que essa leitura de planejamento está errada, segundo o artigo?","options":["Porque a suíte adversarial roda de novo a cada mudança de prompt, modelo ou fonte de dados; segurança de IA não passa uma vez e fica resolvida, é atividade recorrente que precisa de espaço contínuo.","Porque o teste de segurança deveria ser o primeiro card da iniciativa, nunca o último.","Porque segurança de IA é responsabilidade de um fornecedor externo, não do time.","Porque um único card é suficiente desde que seja bem detalhado e estimado com folga."],"answer":0,"explanation":"Qualquer mudança de prompt, modelo ou dados altera o comportamento de forma imprevisível, então o red teaming reaparece sprint após sprint — não é um card único de fim de iniciativa."},{"question":"Na review após o red teaming, o time apresenta o relatório dos vetores de ataque testados. Na visão do agilista, qual é o valor desse artefato?","options":["Serve para responsabilizar o desenvolvedor que introduziu cada vulnerabilidade encontrada.","É apenas documentação técnica de arquivo, sem uso na comunicação com stakeholders.","Substitui a necessidade de qualquer teste de segurança nas próximas iterações.","Vira parte da evidência de que o produto está pronto — um artefato de confiança usado na comunicação com a diretoria."],"answer":3,"explanation":"O relatório de vetores testados é um artefato de confiança que o agilista usa para sustentar, com evidência, a decisão de prontidão diante da diretoria."},{"question":"O que caracteriza corretamente o papel do agilista diante do red teaming de uma IA, segundo a lente do artigo?","options":["Montar o corpus de ataques e medir a taxa de sucesso de cada vetor.","Garantir espaço no planejamento para esse trabalho e traduzi-lo como gestão de risco, sem operar as técnicas de ataque.","Decidir tecnicamente quais guardrails do modelo devem ser reforçados.","Substituir o time de qualidade na execução dos testes de segurança quando o prazo aperta."],"answer":1,"explanation":"O agilista não monta corpus nem mede taxa de sucesso; entende o suficiente para reconhecer o red teaming como gestão de risco e garantir seu espaço no cronograma."}],
  "pii-detection": [{"question":"Você quer usar IA para achar padrões nos feedbacks de retro do trimestre. Segundo a lente do agilista, qual é o cuidado que deve virar reflexo antes de colar esse material num prompt?","options":["Perguntar 'tem dado pessoal aqui?' e mascarar identificadores, porque PDPs, feedbacks e atas são o material mais sensível da empresa e o prompt pode vazar justamente o que deveria proteger.","Garantir que o modelo escolhido seja o mais barato disponível para a análise.","Enviar tudo cru primeiro e pedir à IA que ela mesma remova os dados pessoais depois.","Confirmar que o texto tem pelo menos dez feedbacks para a análise ser estatisticamente válida."],"answer":0,"explanation":"O artigo trata 'tem dado pessoal aqui?' como reflexo: material de time é sensível e colar cru num prompt pode vazar exatamente o que deveria ser protegido."},{"question":"Ao anonimizar um feedback, o texto ficou: 'a pessoa que voltou de licença em março e cuida do módulo de pagamentos'. Por que isso ainda é um problema de privacidade, segundo o artigo?","options":["Porque o texto está muito longo para caber no contexto do modelo.","Porque privacidade não é só apagar o nome: o contexto singulariza a pessoa (re-identificação), e alguém do time leria isso e saberia de quem se trata.","Porque feedbacks de retro nunca devem ser analisados por IA em nenhuma hipótese.","Porque falta a data exata do retorno da licença para completar o registro."],"answer":1,"explanation":"A lição da re-identificação: o nome é dispensável quando o contexto singulariza; anonimizar exige remover os detalhes que permitiriam alguém reconhecer a pessoa."},{"question":"Depois de mascarar os dados com cuidado, o artigo recomenda que o agilista não guarde esse cuidado só para si. Qual é o próximo passo?","options":["Construir um gate de mascaramento automático no pipeline de CI do time.","Proibir definitivamente qualquer uso de IA sobre textos do time.","Transformar o cuidado em acordo de trabalho: o time define junto o que pode e o que não pode ir para ferramentas de IA, e a regra fica escrita no Confluence.","Delegar todas as decisões de privacidade individualmente para cada membro conforme o bom senso de cada um."],"answer":2,"explanation":"É governança no tamanho do time: o combinado explícito (o que vai ou não para a IA) vira acordo escrito no Confluence, não regra que mora na cabeça de cada um."},{"question":"Sobre o papel do agilista em relação à detecção de PII e mascaramento, qual afirmação está correta segundo o artigo?","options":["O agilista deve construir o gate técnico de mascaramento no CI para garantir conformidade.","O agilista não constrói o mecanismo técnico, mas garante que exista um combinado explícito antes que o primeiro incidente o torne urgente.","A responsabilidade sobre dados pessoais é exclusiva do DPO e não toca o dia a dia do agilista.","Basta confiar que as ferramentas de IA já removem dados sensíveis automaticamente."],"answer":1,"explanation":"O agilista não constrói o gate no CI, mas é quem garante que o acordo de trabalho sobre uso de IA exista antes de um incidente forçar a conversa."},{"question":"No acordo de trabalho sobre uso de IA, qual conjunto de regras está alinhado ao exemplo do artigo?","options":["Qualquer dado pode ir para a IA desde que o membro avise depois no chat do time.","Só o agilista pode usar ferramentas de IA, e sempre com dados reais para maior fidelidade.","Dados de cliente podem circular crus desde que a análise seja urgente.","Dados de cliente nunca vão crus, feedbacks sempre anonimizados, e dúvida se resolve perguntando ao DPO — tudo registrado no Confluence."],"answer":3,"explanation":"O exemplo define combinados concretos: cliente nunca cru, feedback sempre anonimizado, dúvida ao DPO, com a regra escrita no Confluence."}],
  "playwright-mcp": [{"question":"Quando o time de qualidade passa a explorar uma feature conversando com um agente que navega no produto, qual é o efeito no fluxo que mais interessa ao agilista?","options":["O agilista passa a operar o agente para registrar os próprios bugs.","A necessidade de refinamento das histórias desaparece, pois o agente descobre tudo sozinho.","O ciclo entre 'bug relatado' e 'bug documentado com passos' encurta e os bugs entram melhor descritos no board, reduzindo o pingue-pongue dev–quem testa.","O board deixa de precisar de uma coluna de teste."],"answer":2,"explanation":"O ganho de fluxo é o ciclo mais curto entre relato e documentação e bugs melhor descritos, o que reduz cards voltando de coluna — retrabalho evitado é fluxo."},{"question":"Na planning, o time estima 'automatizar o fluxo de cupom'. Que pergunta o agilista deve fazer, segundo o artigo, ao lembrar que 'o agente é o andaime, não a construção'?","options":["Se a estimativa considera a exploração supervisionada com o agente ou já assume o script de teste pronto — são dois momentos com custos diferentes.","Qual biblioteca de seletores o agente vai usar para clicar nos elementos.","Se o agente consegue eliminar completamente a etapa de escrever testes versionados.","Quantos screenshots o agente vai capturar durante a exploração."],"answer":0,"explanation":"A sessão exploratória (rápida, resultado variável) e o teste versionado durável são momentos diferentes; o agilista verifica se a estimativa contempla ambos."},{"question":"Um bug intermitente vai e volta há três sprints porque ninguém consegue reproduzi-lo, e o card virou 'morador do board'. O time usa o agente e captura a sequência exata; o card destrava. Como o agilista aproveita isso na retro?","options":["Cobrando de quem testava por que não havia reproduzido o bug antes.","Puxando uma conversa de processo: quanto tempo o time gastava em cards de 'não reproduzível' e o que muda nas estimativas e no SLA de triagem agora que o recurso existe.","Pedindo que o time passe a usar o agente em todos os cards, reproduzíveis ou não.","Encerrando o assunto, já que o bug foi resolvido e não há aprendizado a extrair."],"answer":1,"explanation":"A retro é conversa de processo, não de ferramenta: o dado de tempo de investigação antes e depois embasa estimativas, SLA e a review da iniciativa."},{"question":"No exemplo do artigo, o agente encontrou um defeito de mensagem de erro 'antes de qualquer código de teste existir'. Por que isso importa para o agilista na leitura de fluxo?","options":["Porque prova que o agente substitui integralmente o trabalho de quem testa.","Porque descoberta antecipada é retrabalho evitado, e retrabalho evitado é fluxo.","Porque a mensagem de erro deveria ter sido detectada apenas em produção.","Porque significa que o time pode dispensar a coluna de teste no board."],"answer":1,"explanation":"Defeito descoberto cedo é retrabalho que não acontece depois; para o agilista, isso é ganho de fluxo, não uma questão de operar a ferramenta."},{"question":"Qual é o posicionamento correto do agilista diante do Playwright MCP, segundo a lente do artigo?","options":["Aprender a registrar o server MCP e revisar os seletores gerados pelo agente.","Definir os seletores de acessibilidade que o agente deve priorizar.","Assumir a execução das sessões exploratórias quando o time estiver sobrecarregado.","Não operar a ferramenta, mas ler o que ela muda no board: ciclo de bug mais curto, tarefa nova (exploração supervisionada) para aprender a estimar e dado para a review da iniciativa."],"answer":3,"explanation":"O agilista não registra server nem revisa seletor; sua atuação é ler a mudança de fluxo, estimar o trabalho novo e extrair dado para a review."}],
  "wdio-mcp": [{"question":"O detalhe decisivo do WebdriverIO MCP para o agilista é que a sessão exploratória termina virando um teste versionado no repositório. Por que isso muda uma 'equação antiga do board'?","options":["Porque elimina a necessidade de refinamento das histórias de mobile.","Porque o trabalho manual deixa de evaporar e vira ativo permanente, então o card de 'automatizar depois' que envelhecia no backlog como dívida encolhe.","Porque o agilista passa a gravar as sessões de teste no lugar de quem testa.","Porque acaba com toda a instabilidade das farms de dispositivos."],"answer":1,"explanation":"Quando explorar já produz o rascunho do teste, o 'depois' encolhe e devem aparecer menos cards de dívida de automação acumulando no board."},{"question":"Historicamente, o mesmo time estima o dobro para histórias com teste mobile. Segundo o artigo, por que o WebdriverIO MCP pode reduzir essa diferença de custo entre web e mobile?","options":["Porque o agente elimina a latência do Appium e a instabilidade da farm de dispositivos.","Porque mobile deixa de exigir qualquer teste a partir de agora.","Porque o mesmo roteiro roda no Chrome e num device real trocando uma configuração, diminuindo a diferença estrutural de custo — e isso é verificável, não opinião.","Porque o agilista assume a manutenção da suíte mobile separada."],"answer":2,"explanation":"Cobrir web e mobile pela mesma porta reduz a diferença estrutural de custo; o artigo ressalva que é redução, não milagre, pois farm e Appium seguem existindo."},{"question":"No planning, o time demonstra a sessão que cobre web e app e exporta o esqueleto do teste. Em vez de 'declarar vitória', o que o artigo diz que o agilista deve fazer?","options":["Acompanhar nas sprints seguintes se a diferença de estimativa entre histórias web e mobile de fato cai e se os cards de dívida de automação param de nascer.","Aumentar imediatamente a meta de throughput do time com base na demo.","Substituir todas as estimativas mobile pelas de web já na próxima sprint.","Encerrar a prática de automação mobile por ter virado trivial."],"answer":0,"explanation":"O agilista verifica o efeito real ao longo das sprints (estimativas e dívida de automação) em vez de aceitar a promessa da demo."},{"question":"Se, algumas sprints depois, os números NÃO confirmarem a redução esperada de custo mobile, qual é a atitude do agilista segundo o artigo?","options":["Concluir que a ferramenta é inútil e abandonar a iniciativa.","Levar mesmo assim o ganho à review da iniciativa como capacidade nova.","Culpar o time de qualidade por não ter usado a ferramenta corretamente.","Levar a pergunta certa para a retro: o que está impedindo o ativo (o teste) de ficar pronto ao fim da exploração?"],"answer":3,"explanation":"Sem confirmação nos números, o agilista transforma isso em pauta de retro para investigar o impedimento, em vez de comemorar ou abandonar precipitadamente."},{"question":"Qual é o sinal, nas métricas do agilista, de que a economia de trabalho prometida pelo WebdriverIO MCP está de fato acontecendo?","options":["Menos cards de 'criar automação' acumulando como dívida no backlog.","Aumento do número de sessões exploratórias registradas por sprint.","Redução do número de dispositivos usados na farm.","Crescimento da quantidade de seletores revisados manualmente."],"answer":0,"explanation":"Como explorar passa a deixar o rascunho do teste pronto, o indicador de fluxo é a queda dos cards de dívida de automação envelhecendo no backlog."}],
  "browserstack-ai": [{"question":"O Self-Healing Agent da suíte BrowserStack conserta locators quebrados sozinho. Qual é o 'risco novo' que o artigo diz que o agilista precisa enxergar por trás desse ganho?","options":["O agente pode ficar mais lento a cada cura aplicada.","Um teste que se conserta sozinho pode consertar para o lado errado e ficar verde quando deveria gritar — o 'falso verde' que mascara um defeito real.","A ferramenta só funciona em ambiente de produção, nunca em homologação.","O agente passa a exigir que o agilista revise cada seletor manualmente."],"answer":1,"explanation":"O falso verde é o risco central: uma cura para o lado errado deixa a suíte verde escondendo um defeito, e ninguém percebe sem revisão."},{"question":"Na retro, o time relata que a manutenção de testes caiu de ~30% para 10% do tempo graças ao self-healing. Qual é a 'pergunta de controle' que o agilista faz, segundo o artigo?","options":["'Quanto custou a licença da ferramenta?'","'Quem configurou o self-healing e com quais parâmetros?'","'Quem revisa o que a ferramenta consertou sozinha?'","'Podemos aumentar a meta de throughput agora?'"],"answer":2,"explanation":"A pergunta de governança do agilista é sobre controle: celebra-se o ganho de capacidade, mas é preciso saber quem revisa as curas para o risco não ficar sem dono."},{"question":"O Test Case Generator Agent lê PRDs e user stories e gera casos de teste. Qual efeito no fluxo isso tem, na visão do agilista?","options":["Dispensa o refinamento das histórias, pois a IA cobre todos os cenários.","Transfere a escrita de critérios de aceite para a ferramenta.","Aumenta o tempo de planning por exigir revisão de cada caso gerado.","Encurta o intervalo entre 'história refinada' e 'pronta para desenvolver', porque casos de teste nascem como rascunho a partir da story."],"answer":3,"explanation":"Casos nascendo como rascunho no pós-refinamento encurtam o intervalo entre refinada e pronta para desenvolver — um ganho de fluxo que o agilista lê no board."},{"question":"Diante de uma ferramenta que decide sozinha dentro do pipeline (como o self-healing), qual pergunta de governança o artigo recomenda ao agilista incorporar ao seu repertório?","options":["'Se a IA errar, quem percebe, em quanto tempo, e com qual evidência?'","'Qual algoritmo de matching de seletores a ferramenta usa?'","'Quantos testes a suíte executa por minuto?'","'A ferramenta é compatível com o nosso framework de automação?'"],"answer":0,"explanation":"A pergunta 'se a IA errar, quem percebe, em quanto tempo e com qual evidência?' é a contribuição do agilista: ferramenta que decide sozinha precisa de trilha e de dono."},{"question":"Depois que o time institui a revisão semanal do relatório de curas, meses depois um healing errado quase deixa passar uma regressão no checkout — e a revisão pega. Qual é a lição que o artigo tira desse caso?","options":["Que o self-healing deveria ser desligado por ser perigoso demais.","Que a revisão semanal era desnecessária, pois o problema foi corrigido pelo próprio agente.","Que capacidade nova sem controle novo é dívida disfarçada de ganho.","Que o agilista deveria ter revisado pessoalmente cada cura desde o início."],"answer":2,"explanation":"A lição é que ganho de capacidade sem um controle correspondente vira dívida disfarçada; o acordo de revisão é o que converte o ganho em ganho sustentável."}],
  "k6-ai": [{"question":"O artigo descreve teste de carga como o trabalho 'importante-mas-nunca-urgente'. Por que, na visão do agilista, a IA no k6 justifica reabrir a conversa de priorização?","options":["Porque a IA elimina a necessidade de decidir o modelo de carga (quantos usuários, qual SLA).","Porque agora o teste de carga pode ser feito só em produção, sem custo.","Porque se escrever um cenário deixa de custar uma tarde de especialista e passa a custar minutos supervisionados, a razão histórica para performance ficar fora da sprint desaparece.","Porque a IA garante que o checkout nunca mais cairá no pico."],"answer":2,"explanation":"Quando o custo de uma prática muda, a conversa de priorização precisa ser reaberta — e reabri-la, quando o authoring barateia, é papel do agilista."},{"question":"Ao levar performance para o refinamento, o agilista precisa manter a conversa 'honesta'. Segundo o artigo, o que a IA barateia e o que continua sendo decisão de gente?","options":["A IA barateia o authoring e a análise; o modelo de carga (quantos usuários, qual SLA, qual mistura de tráfego) continua sendo decisão de negócio.","A IA barateia tudo, inclusive a definição do SLA e do volume de usuários.","A IA barateia apenas a execução; escrever o script continua manual.","A IA barateia o modelo de carga; o authoring continua com o especialista."],"answer":0,"explanation":"A IA reduz o custo de escrever e analisar; o modelo de carga segue sendo decisão de negócio. Ou seja, performance por sprint ficou viável, não gratuita."},{"question":"Há um 'detalhe operacional' que toca diretamente o agilista quando o time adota testes de carga assistidos por IA. Qual é?","options":["Escolher entre os executores de carga do k6.","Rodar carga contra produção sem combinar é incidente, não teste; garantir o acordo com a governança sobre ambiente e janela é impedimento que o agilista remove antes que aconteça.","Revisar cada script k6 gerado pela IA antes de rodar.","Definir o número exato de usuários virtuais para cada cenário."],"answer":1,"explanation":"Carga contra produção sem combinar vira incidente; remover esse impedimento (acordo com governança sobre ambiente e janela) é atuação típica do agilista."},{"question":"Há meses 'testar a carga do checkout' mora no backlog como um épico que nunca cabe na sprint. Quando a IA reduz o custo, qual proposta concreta o agilista leva ao refinamento?","options":["Criar um time especializado só em performance.","Adiar o assunto até que ocorra o próximo incidente no pico.","Rodar a carga direto em produção para economizar ambiente.","Performance entra como critério de aceite nas histórias que tocam fluxo crítico — não como épico separado, mas como parte do 'pronto'."],"answer":3,"explanation":"A proposta é decompor o épico eterno em prática contínua: performance vira critério de aceite das histórias de fluxo crítico, incorporada ao Definition of Done."},{"question":"Depois que performance vira prática contínua, como o resultado de cada rodada de carga passa a servir ao agilista na decisão de release?","options":["Vira evidência na avaliação de risco do release, dando ao go/no-go que o agilista facilita dado de carga na mesa, não sensação.","Substitui a necessidade de reunião de go/no-go.","Serve apenas para o time técnico, sem chegar à decisão de release.","Garante automaticamente a aprovação do release por ter passado no teste."],"answer":0,"explanation":"É o shift-left na língua do agilista: o resultado de carga entra na avaliação de risco e embasa o go/no-go com dado, em vez de sensação."}],
  "jira-rovo-mcp": [{"question":"Entre todos os MCPs, o artigo diz que o Rovo MCP é 'a porta de casa' do agilista. Por quê?","options":["Porque só o agilista tem permissão de administrador no Rovo.","Porque o Jira é o território do agilista e boa parte do dia é operar essa ferramenta (varrer boards, compilar status, padronizar descrições) — trabalho administrativo que um agente conectado ao Rovo MCP absorve.","Porque o Rovo MCP substitui a necessidade de cerimônias ágeis.","Porque o agilista precisa escrever a JQL manualmente para cada consulta."],"answer":1,"explanation":"O Jira é o território do agilista; o Rovo MCP absorve o trabalho administrativo de operar a ferramenta, liberando tempo para facilitação de gente."},{"question":"Com o agente conectado ao Rovo MCP, o report de segunda-feira chega como rascunho em minutos. Segundo o artigo, qual é o 'ponto de auditoria barato' do agilista antes de enviar?","options":["Recontar manualmente todos os cards do board.","Pedir ao agente que gere o report duas vezes e comparar.","Revisar a JQL que o agente montou por baixo, além de ajustar o tom para o stakeholder.","Confirmar que o agente tem permissão de escrita no board."],"answer":2,"explanation":"Revisar a JQL usada é a auditoria barata: valida a procedência do dado antes de o rascunho virar comunicação a stakeholder."},{"question":"O artigo alerta que o eixo leitura/escrita 'vale dobrado' para o agilista. Por que uma escrita mal-interpretada no Jira é especialmente perigosa no seu mundo?","options":["Porque o board é a fonte de verdade do fluxo: um 'crie subtarefas para todas as histórias' mal interpretado polui o board, distorce o CFD e contamina as métricas do eazyBI — e não há ctrl+z para 40 issues.","Porque o agente pode perder a conexão OAuth com o Jira.","Porque a escrita em massa deixa o Jira mais lento.","Porque só o stakeholder pode autorizar escritas no board."],"answer":0,"explanation":"O board é a fonte de verdade do fluxo; uma escrita em massa errada distorce CFD e métricas do eazyBI sem desfazer fácil — por isso o cuidado redobrado."},{"question":"Como o artigo caracteriza a política de uso do agente de IA no Jira, e por que ela é papel do agilista?","options":["Como uma configuração técnica que o time de plataforma define sozinho.","Como uma restrição imposta pela diretoria, sem participação do time.","Como um detalhe irrelevante, já que o OAuth já garante a segurança.","Como um acordo de trabalho: começar em modo leitura, definir quais escritas exigem confirmação item a item e tratar cada erro como insumo para refinar a regra — como se revisa DoR ou política de WIP."],"answer":3,"explanation":"A política de uso é um acordo de trabalho, e facilitar acordos é papel do agilista: começar em leitura, definir confirmações e refinar a regra com base nos erros."},{"question":"Qual é o ganho de fundo que o artigo aponta quando o agilista delega o trabalho administrativo do Jira ao agente?","options":["Menos administração de ferramenta e mais facilitação de gente — que é o trabalho que só o agilista faz.","Eliminação total da necessidade de o agilista abrir o Jira.","Substituição das cerimônias por relatórios automáticos.","Aumento do número de cards criados por sprint."],"answer":0,"explanation":"A conta é simples: o agente absorve a administração da ferramenta, liberando o agilista para a facilitação de pessoas, que é o trabalho insubstituível."}],
  "grafana-mcp": [{"question":"Segundo o artigo, o que realmente muda para o agilista quando a equipe conecta um agente ao Grafana?","options":["O agilista passa a escrever PromQL e subir o servidor MCP.","Quem consegue 'perguntar' à observabilidade muda: a pergunta em português passa a ter resposta na hora, e o custo cognitivo de saber qual painel e qual janela deixa de ser um gargalo concentrado em duas ou três pessoas.","Os dashboards de produção deixam de existir.","O agilista assume a responsabilidade de operar a observabilidade."],"answer":1,"explanation":"O ganho é de acesso: perguntar em linguagem natural remove o gargalo de conhecimento concentrado em poucas pessoas — o agilista não escreve PromQL."},{"question":"Na review, o PO pergunta se a feature entregue 'está sendo usada e aguentando bem'. Como o agente conectado ao Grafana muda essa cena, segundo o artigo?","options":["A pergunta é adiada para a próxima sprint por falta de dado.","O agilista precisa consultar o dev depois e retornar por e-mail.","Alguém consulta o agente ali mesmo (uso crescente, latência estável, zero alertas), e a resposta com dado acontece dentro da cerimônia, em vez de virar 'vamos verificar e retornamos'.","A review é encerrada até que o dado seja coletado manualmente."],"answer":2,"explanation":"A resposta com dado passa a acontecer dentro da review, transformando a cerimônia de demonstração de entrega em conversa sobre comportamento em produção."},{"question":"O artigo cobra do agilista o hábito do 'mostre o trabalho'. O que isso significa quando um número de produção vai parar no relatório de stakeholders?","options":["Pedir a query e a janela que o agente usou, porque dado sem procedência em relatório seu é risco seu.","Confiar no número, já que veio de um agente conectado à observabilidade.","Publicar o número apenas se for favorável à entrega.","Solicitar que o dev refaça o dashboard manualmente."],"answer":0,"explanation":"Dado sem procedência no relatório do agilista é risco dele; por isso ele pede a query e a janela usadas antes de o número virar narrativa oficial."},{"question":"O agente reporta que 'o alerta disparou junto com a entrega'. Qual é o segundo cuidado que o artigo cobra do agilista antes de anunciar isso?","options":["Anunciar imediatamente que a entrega causou o alerta.","Ignorar o alerta, pois correlação temporal não tem valor algum.","Correlação não é causa: 'disparou junto com a entrega' é pista para investigação, não veredito para anunciar.","Pedir ao agente que reescreva o alerta com outra janela."],"answer":2,"explanation":"Correlação não é causa; coincidência temporal é pista para investigar, não conclusão para comunicar — o mesmo ceticismo cobrado de quem testa."},{"question":"Qual é o efeito estrutural que o acesso à observabilidade por linguagem natural traz para o papel do agilista nas conversas com stakeholders?","options":["Elimina a necessidade da review como cerimônia.","Permite chegar às conversas de review e ao relatório com dado de comportamento em produção, não só de entrega.","Transfere ao agilista a responsabilidade técnica pelos incidentes.","Faz com que o agilista dependa ainda mais do dev para traduzir gráficos."],"answer":1,"explanation":"O agilista passa a acompanhar o impacto real das entregas em produção e chega às conversas com dado de comportamento, sem esperar o report técnico."}],
  "dynatrace-ai": [{"question":"Por que o artigo diz que a IA causal do Dynatrace (Davis AI) é métrica do agilista, e não só do SRE?","options":["Porque o agilista precisa escrever DQL para consultar a causa dos incidentes.","Porque incidente é o maior destruidor de previsibilidade de sprint: se o diagnóstico que levava horas passa a levar minutos, o custo de cada incidente sobre a capacidade da sprint despenca.","Porque o agilista é o responsável técnico por resolver os incidentes.","Porque a IA causal substitui a necessidade de burndown."],"answer":1,"explanation":"Incidente arrasa a previsibilidade da sprint; reduzir o tempo de diagnóstico reduz o custo do incidente sobre a capacidade — isso é métrica de fluxo do agilista."},{"question":"Um incidente consumiu dois dias da sprint e a retro ameaça virar 'caça às bruxas'. Como o agilista usa a cadeia de causa montada pela IA da observabilidade?","options":["Para identificar e responsabilizar quem fez o deploy que causou o problema.","Para justificar por que a sprint não será replanejada.","Para abrir a sessão com a causa objetiva na mesa (ex.: timeout numa dependência após deploy de outro time), tirando a discussão de 'quem errou' para 'que acordo fazemos com o outro time'.","Para provar que o incidente foi culpa exclusiva do time de infraestrutura."],"answer":2,"explanation":"Com a causa objetiva e reprodutível na mesa, a retro sai da culpa e produz uma ação de processo entre squads — post-mortem baseado em evidência."},{"question":"O artigo lembra que o Davis causal 'é determinístico, não é um texto gerado que pode variar'. Por que isso importa para a facilitação da retro?","options":["Porque permite que o agilista escreva a query DQL sozinho.","Porque a causa é objetiva e reprodutível, sustentando uma discussão baseada em evidência em vez de memórias divergentes de cada um.","Porque significa que o incidente nunca mais vai se repetir.","Porque dispensa a necessidade de post-mortem."],"answer":1,"explanation":"Sendo determinística e reprodutível, a cadeia causal ancora a conversa em evidência comum, evitando que cada participante traga uma memória diferente."},{"question":"Um resumo fluente do Davis CoPilot vai parar no comunicado de incidente para stakeholders. Qual é a versão do agilista do cuidado 'hipótese versus evidência'?","options":["Publicar o resumo direto, pois o CoPilot é confiável.","Reescrever o resumo com as próprias palavras para soar mais formal.","Perguntar quantos usuários foram afetados antes de enviar.","Perguntar antes se aquilo veio do motor causal ou é interpretação generativa — cobrando que alguém tenha validado antes de o número virar narrativa oficial."],"answer":3,"explanation":"O agilista não valida a query, mas sabe distinguir motor causal de texto generativo e cobra a validação antes de o dado virar narrativa oficial de incidente."},{"question":"No cenário 'Na prática' do artigo, é o agilista quem pergunta se o deploy pode ir para 100% do tráfego. O que isso ilustra sobre o seu papel na observabilidade com IA?","options":["Que o agilista deve aprender a escrever e revisar as queries DQL.","Que o agilista assume a operação da ferramenta de observabilidade.","Que o agilista não escreve DQL, mas é quem faz a pergunta de fluxo que a observabilidade com IA responde.","Que o deploy nunca deve ir a 100% sem aprovação do SRE."],"answer":2,"explanation":"O lugar do agilista na história é a pergunta de fluxo (o go/no-go do rollout), respondida pelos dados que a IA causal disponibiliza — sem operar a ferramenta."}],
  "a2a-protocol": [{"question":"O A2A cria uma 'terceira categoria' no mapa de dependências do agilista. O que a torna mais escorregadia que o time interno e o parceiro externo tradicionais?","options":["É uma dependência que só existe em ambiente de homologação.","É uma dependência cujo comportamento é não-determinístico e cujo dono está fora da empresa — o fornecedor troca o modelo do agente dele e o comportamento muda sem nenhuma alteração de contrato.","É uma dependência que dispensa qualquer acordo, pois o protocolo é aberto.","É uma dependência que o próprio agilista controla tecnicamente."],"answer":1,"explanation":"O A2A cria dependência entre 'squads' sem retro conjunta: comportamento não-determinístico e dono externo que pode mudar o agente sem avisar."},{"question":"O time diz que a integração via A2A custa três vezes mais que uma integração de API comum. Como o agilista deve reagir diante do stakeholder que esperava uma semana?","options":["Pressionar o time a reduzir a estimativa para caber no prazo do stakeholder.","Assumir a integração pessoalmente para acelerar.","Defender a estimativa: homologar um agente externo é construir o agente dublê, escrever invariantes de negócio, testar ciclo de vida das tasks e rodar evals — não é 'só fazer a integração'.","Sugerir remover os testes para reduzir o custo à metade."],"answer":2,"explanation":"O artigo explica por que o custo é maior; o agilista usa esse entendimento para defender a estimativa em vez de espremê-la sob pressão de prazo."},{"question":"Numa iniciativa em que o agente de compras consultará o agente do fornecedor, o agilista facilita o mapeamento de dependências. Qual pergunta captura a lente correta?","options":["'Qual formato de agent card o fornecedor usa?'","'Quantas requisições por segundo o agente deles suporta?'","'Qual modelo de linguagem o agente do fornecedor utiliza?'","'O que acontece com nosso fluxo se o agente deles ficar fora do ar por dois dias, ou responder algo válido no formato e absurdo no conteúdo?'"],"answer":3,"explanation":"Tratar o agente externo como um time terceirizado crítico gera histórias de contingência (fallback manual, alerta de invariante) e coloca o risco no radar do portfólio."},{"question":"Segundo o artigo, quais pontos o agilista deve garantir que entrem na negociação da parceria A2A, já que costuma estar na sala dessa conversa?","options":["Identificadores de task compartilhados, trilha de auditoria e ambiente de homologação do parceiro.","O preço por token e a latência média do agente do fornecedor.","A escolha do protocolo de rede e do formato de serialização.","A quantidade de agent cards que o fornecedor mantém publicados."],"answer":0,"explanation":"Esses são os pontos contratuais que o artigo manda exigir; garantir que entrem na negociação da parceria é atuação do agilista, que costuma estar na sala."},{"question":"Qual é o resultado prático de o agilista tratar a dependência de agente externo no planejamento, e não depois?","options":["O protocolo A2A passa a ser testado pelo próprio agilista.","Quando o agente do parceiro surtar numa sexta-feira, a diferença entre incidente e inconveniente será a conversa de planejamento que gerou fallback e alerta com dono e plano.","A integração deixa de precisar de ambiente de homologação.","O fornecedor assume total responsabilidade pelo comportamento do agente."],"answer":1,"explanation":"Da conversa de planejamento nascem histórias de contingência (fallback manual e alerta de invariante); é isso que transforma um futuro incidente em mero inconveniente."}],
  "agent-sandboxing": [{"question":"O artigo compara o sandboxing de agentes ao 'crachá do estagiário'. Na linguagem do agilista, o que isso representa?","options":["Um controle de acesso puramente técnico, sem paralelo com o mundo ágil.","Um acordo de trabalho: a lista explícita do que pode ser feito com autonomia, do que exige aprovação e do que é proibido — aplicada a um integrante de software.","Uma política de segurança que só o time de infraestrutura define.","Um limite que trava a adoção de agentes pelo time."],"answer":1,"explanation":"Sandbox e permissões são acordos de trabalho aplicados a software: a lista explícita de autonomia, aprovação e proibição — território de facilitação do agilista."},{"question":"Quando o time propõe colocar um agente para agir no CI ou nos chamados, qual é o risco de planejamento que o artigo alerta ao agilista?","options":["Desenhar o mapa de alcance, escrever os testes de abuso e configurar tetos é trabalho real que consome sprint — e é sistematicamente esquecido na estimativa de quem está empolgado com a demo.","O agente vai consumir toda a capacidade de processamento do CI.","A ferramenta de sandbox custa caro demais para o orçamento do time.","O time vai precisar contratar um especialista em segurança."],"answer":0,"explanation":"A contenção (mapa de alcance, testes de abuso, tetos) é trabalho de sprint frequentemente omitido na estimativa; garantir que ele apareça é papel do agilista."},{"question":"O artigo oferece o critério 'irreversibilidade × impacto' para decidir o que um agente faz sozinho. Aplicando ao agente que atua no board, qual ação é candidata a exigir decisão humana?","options":["Comentar num card, porque é caro e irreversível.","Etiquetar um card, porque afeta as métricas do eazyBI.","Fechar a sprint ou alterar estimativa, porque mexe com o combinado do time e com as métricas que o agilista reporta.","Sugerir um card, porque não tem dono definido."],"answer":2,"explanation":"Comentar é reversível e barato; fechar sprint ou alterar estimativa é de alto impacto sobre o combinado e as métricas — por isso é decisão de gente."},{"question":"Antes de ativar o agente que atualiza o board, o agilista facilita a definição dos limites com o time e registra o combinado. Onde ele deve ficar, segundo o exemplo?","options":["Numa configuração interna da ferramenta, invisível ao time.","Na cabeça do agilista, que cobra o cumprimento manualmente.","Num documento pessoal do agilista, revisado só por ele.","No acordo de trabalho no Confluence, ao lado dos acordos humanos, ganhando revisão na retro como qualquer outro."],"answer":3,"explanation":"O combinado sobre o raio de ação do agente vira acordo de trabalho no Confluence, revisado na retro — como qualquer outro acordo do time."},{"question":"Um mês depois, o agente erra um comentário e o dano é uma correção de trinta segundos, não uma sprint fechada com dados errados. Qual é a lição do artigo?","options":["Limite claro não trava a adoção: é o que permite ao time ousar mais, porque o raio de dano foi desenhado antes do estrago.","O agente provou ser confiável e os limites podem ser removidos.","Agentes nunca deveriam ter acesso ao board.","O erro mostra que o agilista deveria revisar cada ação do agente."],"answer":0,"explanation":"O dano foi pequeno não porque o agente é confiável, mas porque o raio de ação foi contido antes; limite claro habilita o time a ousar mais, não trava a adoção."}],
  "ai-test-generation": [{"question":"O artigo diz que a geração de testes com IA 'desloca o gargalo'. Por que isso é assunto do agilista?","options":["Porque o agilista passa a operar a ferramenta de geração de casos.","Porque quando escrever casos de teste deixa de ser a etapa cara, o sistema de trabalho do time muda de forma — e redesenhar sistema de trabalho é o ofício do agilista.","Porque a IA elimina a necessidade da coluna de teste no board.","Porque a geração de testes substitui o refinamento das histórias."],"answer":1,"explanation":"Deslocar o gargalo muda a forma do sistema de trabalho (coluna de teste, buffers, distribuição discovery/delivery); redesenhá-lo conscientemente é papel do agilista."},{"question":"No refinamento, os casos gerados pela IA a partir de uma story vêm 'estranhos'. Segundo o artigo, o que isso sinaliza para o agilista?","options":["Que a ferramenta de IA está com defeito e deve ser trocada.","Que quem testa precisa consertar os casos no downstream.","Que o modelo, diante de story vaga, preencheu lacunas com suposições — é um detector de critério de aceite mal escrito, sinal para o agilista e o PM melhorarem o upstream.","Que o refinamento deve ser cancelado até a IA melhorar."],"answer":2,"explanation":"Casos estranhos revelam critérios de aceite vagos: o modelo supõe em vez de perguntar; isso é um sinal de upstream a corrigir, não de downstream a remendar."},{"question":"A 'regra de honestidade' do artigo pede que o agilista garanta que o tempo de validação dos casos gerados apareça nas estimativas. Por quê?","options":["Porque revisar 30 casos gerados não é grátis, e ignorar isso vira promessa a stakeholder sem número por trás.","Porque a IA cobra por caso gerado.","Porque a validação é responsabilidade do agilista, não de quem testa.","Porque casos gerados por IA nunca precisam de revisão."],"answer":0,"explanation":"A IA acelera a geração, mas validar cobertura, oráculo e seletor tem custo; o agilista garante que esse tempo entre nas estimativas em vez de sumir."},{"question":"Duas sprints após adotar a geração de testes com IA, como o agilista verifica se houve ganho real de fluxo na etapa de teste?","options":["Perguntando ao time se todos gostaram da ferramenta.","Contando quantos casos a IA gerou no total.","Assumindo o ganho pela demo apresentada no refinamento.","Usando o eazyBI para checar se o cycle time na etapa de teste caiu de verdade e levando o gráfico à retro com a pergunta: o que fazemos com a capacidade liberada?"],"answer":3,"explanation":"A adoção precisa ser medida (baseline antes, comparação depois): o cycle time da etapa de teste no eazyBI mostra o ganho, e a retro decide o uso da capacidade liberada."},{"question":"Qual é a fronteira de papéis que o artigo estabelece entre o agilista e o time de qualidade na geração de testes com IA?","options":["O agilista valida cobertura, oráculo e seletor; o time de qualidade cuida das estimativas.","Quem valida cobertura, oráculo e seletor é o time de qualidade; o agilista lidera a mudança no sistema de trabalho e garante que a adoção seja medida.","Ambos operam a ferramenta em conjunto no refinamento.","O agilista escreve os casos e o time de qualidade os revisa."],"answer":1,"explanation":"O agilista não opera a ferramenta: quem valida a técnica é a qualidade; o agilista lidera a mudança de fluxo e garante baseline, medição e conversa honesta com stakeholder."}],
  "self-healing": [{"question":"O artigo descreve a manutenção de seletores quebrados como o tipo de trabalho que 'o board não enxerga'. Por que isso é um problema de fluxo para o agilista?","options":["Porque não vira card nem entra em estimativa, mas consome horas do time toda semana — e é por isso que sprints 'evaporam' sem que o CFD explique.","Porque a manutenção de testes deveria virar um épico próprio no backlog.","Porque o agilista precisa aprovar cada seletor consertado.","Porque a IA torna essa manutenção mais lenta."],"answer":0,"explanation":"Esse toil invisível não aparece no board mas consome capacidade, explicando sprints que evaporam sem justificativa no CFD — daí a importância de nomeá-lo e quantificá-lo."},{"question":"Na retro, o time reclama que 'a sprint sumiu' mas nada no board justifica. O que o self-healing dá ao agilista, segundo o artigo?","options":["Uma ferramenta que ele mesmo deve configurar e calibrar.","Vocabulário e lente para nomear esse toil, quantificá-lo e transformá-lo em decisão de investimento — não fé em ferramenta.","A garantia de que a suíte ficará sempre verde.","Um motivo para aumentar a meta de throughput imediatamente."],"answer":1,"explanation":"O agilista não calibra limiar de confiança; o conceito lhe dá vocabulário para nomear o toil, medi-lo e transformá-lo em decisão de investimento com argumento de fluxo."},{"question":"Depois de propor medir o tempo gasto consertando testes por duas sprints, como o agilista transforma a conversa de adoção do self-healing?","options":["Em uma decisão do fornecedor, que apresenta o pitch da ferramenta.","Em uma votação sobre quem gosta mais da ferramenta.","Em um argumento de fluxo com número: 'gastamos X horas por sprint nisso; a ferramenta custa Y; vamos pilotar e comparar'.","Em uma exigência de que o time pare de escrever testes E2E."],"answer":2,"explanation":"Com o número na mão, a adoção deixa de ser fé em ferramenta e vira argumento de fluxo, com piloto e comparação — não o pitch do fornecedor."},{"question":"O 'contraponto honesto' do self-healing também é de facilitação do agilista. Qual é o pior cenário que o artigo aponta?","options":["A ferramenta deixar a suíte mais lenta a cada cura.","O falso verde: uma cura que mascara uma regressão real, fazendo com que 'suíte 100% verde' deixe de ser sinônimo automático de segurança.","O time ficar dependente do fornecedor da ferramenta.","O agilista ter que revisar todos os seletores manualmente."],"answer":1,"explanation":"O falso verde — cura que mascara regressão — quebra a equivalência entre suíte verde e segurança; por isso auto-aprovar curas exige ponderar o risco."},{"question":"Quando o time discute auto-aprovar curas para 'ganhar velocidade', qual é o papel do agilista, segundo o artigo?","options":["Aprovar, pois velocidade é sempre prioridade.","Delegar a decisão inteiramente ao time de qualidade.","Vetar qualquer uso de self-healing por causa do risco.","Garantir que a decisão pondere o risco: uma regressão mascarada hoje é incidente não planejado daqui a três sprints, e trabalho não planejado é o que estão tentando reduzir."],"answer":3,"explanation":"O agilista facilita a decisão ponderando o risco de fluxo: cura auto-aprovada que mascara regressão vira trabalho não planejado futuro — o oposto do objetivo."}],
  "synthetic-data": [{"question":"O artigo pede ao agilista que olhe o quadro de bloqueios e conte os cards parados com a etiqueta 'aguardando massa de teste'. Por que esse é um dos impedimentos mais longos do delivery?","options":["Porque quase sempre depende de gente de fora do time: o DBA que extrai o dump, o squad dono da base, o comitê de privacidade que aprova acesso a dado real.","Porque a massa de teste é sempre gerada por engano.","Porque exige que o agilista escreva o dado manualmente.","Porque a massa de teste corrompe o board."],"answer":0,"explanation":"O impedimento é longo porque depende de terceiros externos ao time; dados sintéticos dissolvem essa categoria de dependência ao permitir fabricar a massa internamente."},{"question":"Um card está bloqueado há cinco dias esperando massa anonimizada de outro time. Em vez de só escalar o impedimento, qual pergunta o artigo habilita o agilista a fazer?","options":["'Podemos esperar mais três dias pela extração?'","'Quem é o responsável por aprovar o acesso ao dado real?'","'Dados sintéticos resolveriam aqui?' — o time mapeia o esquema, gera a massa e o card destrava no mesmo dia.","'Podemos usar o dado de produção sem anonimizar só desta vez?'"],"answer":2,"explanation":"Em vez de apenas subir o impedimento na hierarquia, o agilista propõe a alternativa técnica: dados sintéticos transformam o bloqueio externo em tarefa interna de uma tarde."},{"question":"Na análise mensal de bloqueios no eazyBI, a categoria 'dependência de dados' encolhe depois da adoção de dados sintéticos. Por que o artigo diz que isso 'vale um slide' no relatório de stakeholders?","options":["Porque prova que o time trabalhou mais horas.","Porque a mudança não é 'resolvemos um bloqueio', mas 'eliminamos uma classe de bloqueio' — uma mudança estrutural de fluxo.","Porque o eazyBI passa a gerar os dados sintéticos automaticamente.","Porque reduz o número de cards no board."],"answer":1,"explanation":"O ganho é estrutural: uma classe inteira de impedimento desaparece do fluxo, o que é bem mais significativo do que destravar um card isolado."},{"question":"Qual é 'o argumento que compliance escuta' quando o agilista leva dados sintéticos para a mesa, segundo o artigo?","options":["Que dados sintéticos são mais baratos que dados reais.","Que a IA garante 100% de fidelidade ao dado de produção.","Que dado sintético inverte a conversa: em vez de negociar exceções para usar dado real, o time apresenta um processo que não precisa dele — cada dump de produção em homologação é risco de LGPD ambulante.","Que o DPO deixa de precisar aprovar qualquer acesso."],"answer":2,"explanation":"Dado sintético elimina a necessidade de dado real em homologação; em vez de negociar exceções com o DPO, o time apresenta um processo que dispensa o dado sensível."},{"question":"Onde termina o papel do agilista e começa o do time de qualidade em relação aos dados sintéticos, segundo o artigo?","options":["O agilista escolhe entre GAN e faker e valida a correlação das colunas; a qualidade só executa.","Ambos validam juntos a correlação estatística das colunas geradas.","O agilista gera a massa e a qualidade apenas a utiliza.","O agilista não escolhe a técnica nem valida correlação (isso é engenharia da qualidade); ele leva a alternativa à mesa quando uma iniciativa emperra em privacidade e planeja o gerador como história estimada."],"answer":3,"explanation":"Escolher GAN vs faker e validar correlação é engenharia da qualidade; o agilista traz a alternativa quando a privacidade emperra e planeja a criação do gerador como trabalho real estimado."}],
  "ai-validators": [{"question":"O artigo abre com defeitos que nenhum 'assertEquals' pega ('o texto soa rude?'). Trocando o objeto para o sistema de trabalho do agilista, que exemplo de validação semântica ele cita?","options":["'O build passou em todos os testes?'","'Esta story tem critério de aceite de verdade ou só uma frase decorativa?' — e 'esta ata registra a decisão e o dono, ou só que a reunião aconteceu?'","'Quantos cards estão em andamento?'","'O deploy foi para produção?'"],"answer":1,"explanation":"Definition of Ready, qualidade de descrição de bug e completude de ata são critérios subjetivos — validações semânticas que um juiz de IA instruído e calibrado pode automatizar."},{"question":"O agilista define uma rubrica de prontidão e um validador passa por cada story candidata à planning na véspera. Qual é o efeito descrito no artigo?","options":["A planning para de gastar os primeiros quarenta minutos descobrindo que metade do backlog não estava pronto, e o Definition of Ready deixa de ser pôster no Confluence para virar acordo que se cumpre.","A ferramenta passa a escrever as histórias no lugar do PM.","As stories reprovadas são excluídas do backlog automaticamente.","O agilista deixa de precisar facilitar o refinamento."],"answer":0,"explanation":"O validador devolve as reprovadas com o motivo antes da cerimônia, então a planning não gasta tempo descobrindo backlog não pronto e o DoR vira acordo que se cumpre sozinho."},{"question":"O artigo insiste: 'rubrica vaga produz juiz ruidoso'. Qual formulação de critério valida de fato, segundo o exemplo?","options":["'Marque reprovada se a story não estiver bem escrita.'","'Marque reprovada se a story for grande demais.'","'Marque reprovada se nenhum critério de aceite for verificável objetivamente.'","'Marque reprovada se o PM não tiver revisado a story.'"],"answer":2,"explanation":"'Story bem escrita' não valida nada; um critério operacional e objetivo ('nenhum critério de aceite verificável') valida — escrever critérios operacionais é habilidade que o agilista já exercita."},{"question":"Antes de deixar o validador reprovar as stories dos outros, o artigo recomenda uma etapa de calibração. Qual é?","options":["Rodar o validador sobre todo o backlog de uma vez.","Rodá-lo sobre dez stories que o próprio agilista já classificou e ver se ele concorda com o julgamento; se reprovar ou aprovar tudo, o problema é a rubrica.","Pedir ao fornecedor um certificado de acurácia do modelo.","Deixar a IA decidir o critério de prontidão sozinha."],"answer":1,"explanation":"Calibrar contra stories já classificadas revela se o juiz julga como o time; reprovar ou aprovar tudo indica rubrica ruim, e refiná-la vira pauta de refinamento do processo."},{"question":"Qual é a disciplina que o artigo diz que o agilista precisa ter (sem precisar saber o que é Cohen's kappa) ao usar validadores com IA?","options":["Calcular a concordância estatística entre o juiz e o time.","Terceirizar integralmente o critério de prontidão para a IA para ganhar tempo.","Nunca terceirizar um critério para a IA sem antes conferir se ela julga como o time julgaria.","Aplicar o validador apenas às stories que ele mesmo escreveu."],"answer":2,"explanation":"A disciplina é não terceirizar um critério à IA sem conferir se ela julga como o time — a métrica formal (kappa) é dispensável, o hábito de calibrar não."}],
  "prompt-versioning": [{"question":"Na ótica do agilista, por que tratar os prompts que o time usa nos rituais (quebra de épico, resumo de sprint) como artefatos versionados é responsabilidade sua?","options":["Porque versionar prompts exige configurar um repositório Git e pipeline de evals, tarefa que cabe ao Scrum Master","Porque prompts que funcionam viram ativos do time e, sem versão, dono e histórico, esse conhecimento fica na cabeça de uma pessoa — governar o sistema de trabalho é seu papel","Porque o agilista precisa escrever os melhores prompts do time e servir de referência técnica","Porque prompts versionados aumentam a velocity da sprint de forma mensurável"],"answer":1,"explanation":"Prompts eficazes são patrimônio do time; sem gestão o conhecimento some com a pessoa (nas férias), e cuidar do sistema de trabalho é ofício do agilista."},{"question":"Alguém 'melhorou' o prompt de quebra de épico e as quebras começaram a vir rasas, sem critérios de aceite. Qual é a atitude coerente com o que você leu?","options":["Confiar no bom senso e pedir para a pessoa lembrar como era o prompt antigo","Bloquear qualquer alteração de prompt sem aprovação do agilista","Como as versões estão registradas, pegar um épico real, rodar as duas versões lado a lado e decidir com evidência se volta atrás","Trocar de ferramenta de prompt management, já que a atual permitiu a sobrescrita"],"answer":2,"explanation":"O histórico de versões permite comparar as duas num caso real conhecido — transforma 'eu acho que antes era melhor' em medida, o mesmo raciocínio do golden set."},{"question":"Onde o material sugere colocar, de forma recorrente, a revisão da biblioteca de prompts do time?","options":["Como item fixo na retro de fechamento de trimestre, junto com os demais acordos de trabalho","Na daily, todos os dias, para garantir atualização constante","Somente quando um prompt quebrar em produção","No planning de cada sprint, antes da estimativa"],"answer":0,"explanation":"A revisão vira acordo de trabalho: na retro trimestral prompts sem uso saem e os mais copiados ganham manutenção — o artefato tem ciclo de vida que alguém facilita."},{"question":"Um Scrum Master novo entra no time. Segundo a lente do agilista, qual valor a biblioteca de prompts versionada entrega nesse momento?","options":["Reduz o custo por token das chamadas de IA do time","Substitui a necessidade de qualquer treinamento formal em agilidade","Garante que o novo SM não precise participar das cerimônias","É onboarding instantâneo do 'jeito que este time trabalha com IA', dando continuidade ao conhecimento"],"answer":3,"explanation":"A biblioteca versionada dá continuidade: o novo integrante aprende de imediato como o time opera com IA, sem depender da memória de uma pessoa."},{"question":"O que significa, na prática, 'não precisar de Git nem de pipeline de evals para começar' a gerir prompts?","options":["Que gestão de prompts é opcional e só vale a pena em times grandes","Que o agilista deve esperar a área técnica montar a infraestrutura antes de agir","Que basta o princípio: uma biblioteca no Confluence com versão datada, autor e um exemplo de saída boa já resolve na escala do time","Que prompts devem ficar apenas no histórico de chat de cada pessoa"],"answer":2,"explanation":"O que importa é o princípio de tratar prompt como artefato com versão, dono e exemplo — algo viável no Confluence, sem ferramental de engenharia."}],
  "cost-latency": [{"question":"Por que, na lente do agilista, custo e latência de IA são conversa de portfólio e não apenas detalhe de engenharia?","options":["Porque o agilista precisa medir TTFT e decompor tokens para reportar aos stakeholders","Porque custo e latência decidem se a iniciativa de IA é viável — e viabilidade de iniciativa é decisão de portfólio","Porque o modelo mais caro é sempre o que deve ser escolhido pelo time","Porque latência alta é um impedimento que o agilista remove diretamente no código"],"answer":1,"explanation":"O modelo mais preciso pode ser inviável e o 'pior' pode viabilizar a feature; custo e latência definem a sobrevivência da iniciativa — pauta de portfólio."},{"question":"Na quebra de uma iniciativa de IA, você percebe que todas as histórias são funcionais ('o bot responde', 'o resumo é gerado'). Qual provocação é a mais alinhada ao seu papel?","options":["'Vamos escolher já o modelo mais barato para não estourar orçamento'","'Onde está a validação de custo e latência?' — sugerindo um spike de medição no início e limites como critérios de aceite","'Isso é problema da engenharia, seguimos com as histórias funcionais'","'Vamos adiar a iniciativa até o fornecedor baixar os preços'"],"answer":1,"explanation":"A pergunta certa cedo faz o time adicionar um spike de medição e transformar limites de custo/latência em critérios de aceite explícitos, evitando a surpresa no fim do quarter."},{"question":"Descobrir custo e latência inviáveis 'no fim do quarter, quando o recurso escala e a fatura chega' é ruim principalmente porque:","options":["É o tipo de surpresa que estoura prazo, orçamento e a sua credibilidade com stakeholders de uma vez","Obriga o time a trocar de ferramenta de observabilidade","Reduz a velocity da última sprint do trimestre","Impede o time de rodar a retro daquele quarter"],"answer":0,"explanation":"A descoberta tardia junta três estragos: prazo, orçamento e credibilidade — por isso a validação de viabilidade precisa vir na segunda sprint, registrada no plano."},{"question":"O time reclama que 'a IA interna é lenta' e a adoção despenca no dashboard. Como o agilista deve enxergar isso?","options":["Como fatalidade técnica: ferramenta de IA lenta é normal e não há o que fazer","Como problema exclusivo do fornecedor, fora do alcance do time","Como um trade-off de três eixos (custo, latência, qualidade) que alguém escolheu, talvez no escuro — e que cabe a você levar para a luz em retro, refinamento ou plano","Como sinal de que o time precisa aumentar o WIP para compensar"],"answer":2,"explanation":"Adoção é métrica do agilista; a lentidão não é destino, e sim um trade-off escolhido que deve virar pauta explícita de retro, critério de refinamento ou marco de iniciativa."},{"question":"Qual afirmação sobre 'trocar um modelo grande por um pequeno' está de acordo com o material?","options":["O modelo grande é sempre superior e nunca deve ser trocado","Modelos pequenos só servem para protótipos e nunca para produção","A troca de modelo é responsabilidade única do agilista definir","Às vezes trocar por um modelo pequeno é o que viabiliza a feature — é um trade-off entre custo, latência e qualidade, não uma perda automática"],"answer":3,"explanation":"Otimizar envolve escolher o modelo certo para a tarefa; o 'pior' modelo pode ser o que torna a feature viável — decisão de trade-off que o agilista ajuda a explicitar."}],
  "ci-cd-ai": [{"question":"Um PR está parado há dois dias porque um eval reprovou no pipeline. Como o agilista deve ler esse sinal no board?","options":["Como um impedimento a ser removido à força para o card andar","Como falha da ferramenta de CI que precisa ser trocada","Como sinal de que o time deve aumentar o limite de WIP","Como o sistema de qualidade funcionando exatamente como desenhado — não um bloqueio a destravar"],"answer":3,"explanation":"Um eval que barra merge porque a nota caiu abaixo da baseline é o gate funcionando; tratá-lo como impedimento a remover é sabotar o próprio freio de qualidade."},{"question":"Na daily, alguém sugere 'desligar aquele check que vive falhando' porque o lead time dos PRs de prompt subiu. Qual é a atuação alinhada ao seu papel?","options":["Facilitar a remoção do check imediatamente, pois lead time é a métrica prioritária","Investigar antes e facilitar a conversa certa: por que a nota está caindo? — pode ser a baseline desatualizada","Delegar a decisão ao dev que abriu o PR","Aumentar a tolerância do eval sem discussão para o fluxo voltar a correr"],"answer":1,"explanation":"Investigando, o time descobre que a baseline estava desatualizada; ajusta o dataset de regressão e o fluxo volta a correr sem sacrificar a proteção — remover impedimento não é remover o freio."},{"question":"O que caracteriza um gate de eval 'mal calibrado' e por que é território do agilista?","options":["É um bug de código do pipeline que só a engenharia resolve","É quando o threshold nunca muda, algo puramente técnico e sem impacto no time","É um problema de acordo: apertado demais vira ruído e o time dá override em tudo; frouxo demais não protege — onde fica a régua é negociação entre qualidade e velocidade","É quando o gate roda rápido demais e libera o merge sem testar"],"answer":2,"explanation":"Threshold mal calibrado é problema de acordo, não de código: gate apertado mata o sinal por descrédito, frouxo não protege — a régua é facilitação entre qualidade e velocidade."},{"question":"Quando um override do gate de eval acontecer, o material recomenda que ele seja:","options":["Auditável e discutido na retro, como qualquer exceção a um working agreement","Proibido em qualquer circunstância","Decidido em silêncio pelo autor do PR para não travar o fluxo","Registrado apenas se o incidente virar crise pública"],"answer":0,"explanation":"Override é exceção a um acordo de trabalho: deve ser auditável e levado à retro, com dado de quantas reprovações foram legítimas versus falso alarme."},{"question":"Que dado o agilista deve levar para a conversa sobre onde calibrar a régua do gate?","options":["A quantidade de linhas de código alteradas em cada PR","O número de reprovações legítimas versus falsos alarmes nas últimas sprints","O custo por token de cada execução do eval","A velocity média do time no último trimestre"],"answer":1,"explanation":"A negociação da régua se sustenta em dado: quantas reprovações foram reais e quantas foram falso alarme, para equilibrar qualidade e velocidade com evidência."}],
  "eval-driven-dev": [{"question":"Na lente do agilista, o que o eval representa para o trabalho de IA?","options":["Um relatório de testes que o QA entrega no fim do épico","A Definition of Done executável do trabalho de IA — o critério objetivo de pronto","Uma métrica de velocity específica para features de IA","Uma cerimônia nova que substitui o refinamento"],"answer":1,"explanation":"Se o EDD é o TDD da era da IA, para o agilista ele é a DoD executável: transforma 'está bom o suficiente?' de opinião em número com alvo."},{"question":"Por que 'um épico de IA sem eval definido' é um cheiro que o agilista deveria reconhecer?","options":["Porque sem eval o épico custa mais tokens do que o previsto","Porque significa que o QA não foi alocado à iniciativa","Porque impede o time de fazer a sprint review","Porque é um épico sem critério de pronto: vai iterar no prompt para sempre, cada demo parece 'quase lá' e vira um poço sem fundo que devora sprints"],"answer":3,"explanation":"Sem critério objetivo o time itera indefinidamente; o épico vira poço sem fundo — o mesmo cheiro de trabalho exploratório sem marco de conclusão que o agilista já conhece."},{"question":"Na planning de uma feature de IA você pergunta 'como saberemos que está pronto para lançar?' e recebe silêncio. Qual encaminhamento é o do material?","options":["Aceitar 'quando as respostas estiverem boas' e seguir com a planning","Adiar a feature até o modelo melhorar sozinho","Facilitar a definição com QA e PM, transformando a PRIMEIRA história do épico em 'construir o dataset de avaliação e definir o critério de aprovação'","Delegar a decisão de pronto ao stakeholder no go/no-go"],"answer":2,"explanation":"A primeira história vira a construção do eval e do critério de aprovação; isso dá baseline inicial, experimentos por iteração e um alvo real para o burn-up do épico."},{"question":"Com o eval como âncora, como muda a conversa de go/no-go com stakeholders?","options":["Continua sendo 'o time acha que está bom', só que documentado","Passa a depender exclusivamente da opinião do QA sênior","Sai de 'o time acha que está bom' para um número com alvo que qualquer diretor entende","Vira uma votação entre os membros do time"],"answer":2,"explanation":"O eval troca opinião por medida: a conversa de lançar ou não vira 'fidelidade de X%, estamos em Y', legível para stakeholders."},{"question":"A Lei de Goodhart ('quando a métrica vira alvo, o time otimiza a métrica, não a qualidade') aparece em evals como um gate só de 'fidelidade' que gera respostas vagas. Qual é o antídoto que o agilista já conhece?","options":["Nunca usar métricas em trabalho de IA","Nunca uma métrica sozinha, sempre pares que se equilibram, com revisão periódica de se o número ainda mede o que importa","Aumentar o threshold do gate a cada sprint","Deixar o QA decidir a métrica sem participação do time"],"answer":1,"explanation":"O mesmo remédio de métricas de fluxo (velocity inflada, cobertura decorativa): pares de métricas que se equilibram e vigilância periódica — facilitar isso é papel do agilista."}],
  "red-teaming": [{"question":"Por que red teaming 'cai direto no colo' do agilista, mesmo ele não escrevendo prompt malicioso?","options":["Porque é uma cerimônia ágil que o Scrum Master facilita semanalmente","Porque é trabalho de verdade, com esforço real, que precisa acontecer exatamente quando a pressão de prazo é maior — e proteger esse espaço no plano é o seu ofício","Porque o agilista é quem decide se o sistema é seguro","Porque red teaming substitui os testes funcionais do time"],"answer":1,"explanation":"Atividade de qualidade perto do go-live vira 'aquele teste extra' cortado no primeiro aperto; proteger o espaço dela no plano é trabalho clássico do agilista."},{"question":"No plano de lançamento de um assistente, como o material sugere posicionar o red teaming?","options":["Como tarefa enterrada num card, para não assustar os stakeholders","Na véspera do go-live, para pegar o produto mais próximo do final","Como uma janela com marco nomeado da iniciativa, duas sprints antes do go-live, visível para stakeholders","Somente se sobrar capacidade após as histórias funcionais"],"answer":2,"explanation":"Red teaming vira marco explícito e visível, duas sprints antes do go-live — não tarefa enterrada nem espremida na véspera, quando as piores decisões são tomadas."},{"question":"O relatório de red teaming chega com doze achados. Qual é o segundo papel do agilista nesse momento?","options":["Corrigir pessoalmente os achados de maior risco","Adiar o lançamento por tempo indefinido até zerar os achados","Facilitar a triagem sem pânico nem negação, separando o que bloqueia o lançamento do que vira backlog priorizado com dono e prazo","Encaminhar todos os achados para a próxima retro sem priorizar"],"answer":2,"explanation":"A facilitação separa bloqueantes (ex.: vazamento de dado) do que vira backlog com dono; o lançamento pode deslizar uma semana com decisão registrada e critério."},{"question":"O que significa 'o alvo se move' para o planejamento do agilista?","options":["Que trocar modelo, ajustar prompt ou adicionar ferramenta reabre buracos fechados — logo red teaming é atividade recorrente que precisa de espaço contínuo no fluxo","Que os requisitos mudam a cada sprint e o backlog precisa ser refeito","Que o red teaming deve ser feito apenas uma vez, antes do primeiro go-live","Que o time deve mover a data de lançamento sempre que houver um achado"],"answer":0,"explanation":"Como mudanças reabrem vulnerabilidades, red teaming não é portão único: é atividade recorrente com espaço contínuo no fluxo, como refino ou manutenção de testes."},{"question":"O relatório de red teaming veio limpo e alguém propõe comemorar. Qual é a pergunta saudável do facilitador, segundo o princípio 'ausência de falha não é prova de segurança'?","options":["Perguntar se já dá para reduzir a equipe de qualidade","Confirmar que o sistema está 100% seguro e liberar o go-live","Perguntar quanto custou o red teaming em capacidade","Perguntar sobre a cobertura do teste, não sobre a certeza de que não há nada"],"answer":3,"explanation":"'Não achamos nada' não é 'não há nada'; a pergunta certa é sobre cobertura — impedir que o time confunda os dois é papel de facilitação do agilista."}],
  "golden-dataset": [{"question":"Por que curar um golden dataset costuma fazer épicos de IA estourarem, na leitura do agilista?","options":["Porque é trabalho de verdade (horas de gente sênior rotulando) que parece 'preparação', não 'entrega', e trabalho que parece preparação nunca vira card","Porque exige comprar uma ferramenta cara de rotulagem","Porque o QA se recusa a participar da curadoria","Porque o dataset consome muitos tokens de inferência"],"answer":0,"explanation":"A curadoria é trabalho sênior real, mas por parecer preparação fica invisível no plano — vira o trabalho às escondidas, à noite, que faz o épico estourar sem causa aparente."},{"question":"O primeiro épico de IA estourou em três semanas e, na retro, aparece que 'montar o dataset de avaliação' não estava no plano. O que o agilista faz na iniciativa seguinte?","options":["Remove o eval do escopo para o épico não estourar de novo","Garante que a curadoria entre no backlog como história estimada, com dono e QAs sêniores alocados","Pede ao QA que faça o dataset nas horas vagas com mais organização","Aumenta a estimativa de todas as histórias funcionais em 20%"],"answer":1,"explanation":"O gabarito é o artefato do qual toda avaliação depende; merece status de entregável — história estimada, dono nomeado e espaço na sprint melhoram a previsibilidade."},{"question":"O material menciona 'rotulagem em dupla'. Por que esse detalhe importa para a leitura do agilista?","options":["Porque dobra a velocity da curadoria","Porque exige alocar o dobro de orçamento no quarter","Porque garante que o QA nunca erre um rótulo","Porque discordância entre rotuladores é sinal de critério ambíguo, não de gente errada — um sinal de refinamento pendente"],"answer":3,"explanation":"Discordância entre quem rotula aponta critério ambíguo — informação valiosa de qualidade de requisito, não desperdício; por isso a dupla é parte do desenho."},{"question":"Alguém apresenta 'o modelo acerta 92%'. Qual é a pergunta de facilitador coerente com o material?","options":["'Dá para chegar a 95% na próxima sprint?'","'92% contra o quê? Quem definiu o certo, quando, e isso ainda reflete o produto de hoje?'","'Quantos tokens custou medir esses 92%?'","'Podemos lançar então, já que passou de 90%?'"],"answer":1,"explanation":"Sem gabarito curado e atual, o número é teatro; a pergunta é a mesma de um dashboard suspeito — staleness de gabarito é a versão IA do dashboard desatualizado."},{"question":"Qual paralelo o material traça entre golden dataset e o mundo de métricas do agilista?","options":["Ambos exigem um especialista externo para serem confiáveis","Ambos devem ser revisados apenas uma vez, no início da iniciativa","Assim como cycle time calculado sobre cards mal movimentados não informa nada, sem gabarito curado todo número de qualidade da IA é opinião com gráfico","Nenhum dos dois é responsabilidade do agilista"],"answer":2,"explanation":"Métrica de fluxo sem dado confiável é opinião com gráfico; golden dataset é o mesmo princípio aplicado à IA — sem gabarito curado, o número de qualidade é teatro."}],
  "visual-testing-ai": [{"question":"Por que um bug visual que escapa é 'o retrabalho com o pior perfil de fluxo que existe'?","options":["Porque exige reescrever toda a suíte de testes visuais","Porque consome muitos tokens de comparação de imagem","Porque só pode ser corrigido pelo próprio agilista","Porque chega sem aviso como mensagem de stakeholder no meio da sprint, fura qualquer priorização e rouba capacidade do que estava planejado"],"answer":3,"explanation":"Bug visual reportado de fora vira card não planejado no meio da sprint, com print e tom de 'como passou?' — constrange o time e atropela a priorização."},{"question":"O que a IA muda no teste visual, na expectativa realista que o agilista deve levar à conversa de adoção?","options":["Elimina totalmente a necessidade de revisão humana dos diffs","Faz comparação perceptual, reduzindo os falsos alarmes que tornavam o diff de pixels tradicional flaky","Garante zero bugs visuais em produção para sempre","Substitui o teste funcional pela análise de layout"],"answer":1,"explanation":"O diff de pixels tradicional vira flaky, o time sobe a tolerância e o teste vira teatro; a IA faz comparação perceptual e reduz o falso alarme — expectativa realista, não promessa de fornecedor."},{"question":"Qual é 'o movimento' que o agilista faz antes de discutir a ferramenta de teste visual?","options":["Aprovar a compra da ferramenta mais recomendada pelo fornecedor","Configurar o threshold do teste visual junto com o QA","Medir no Jira a frequência de cards não planejados por bug visual nas últimas dez sprints e estimar o custo em capacidade","Pedir ao time que teste manualmente todas as telas antes de cada release"],"answer":2,"explanation":"Medir antes transforma a conversa de 'seria legal ter' em um problema quantificado; o gráfico de trabalho não planejado antes/depois vira a história de melhoria para stakeholders."},{"question":"Na retro aparece que a revisão de diffs virou 'clicar aprovar tudo'. Como o agilista deve interpretar essa 'aprovação preguiçosa de baseline'?","options":["Como eficiência: o time confia no processo e não perde tempo","Como sinal de processo degradando — a suíte passa a documentar bugs como comportamento esperado, do mesmo tipo que daily que virou status report","Como problema exclusivo da ferramenta, sem relação com o time","Como motivo para aumentar a tolerância do teste visual"],"answer":1,"explanation":"Quando a triagem fica chata e o time aprova tudo, a suíte passa a registrar bugs como esperado; é degradação de processo, e apontá-la na retro é papel do facilitador."},{"question":"O time apresenta 'zero regressão visual' como conquista. Qual é a pergunta saudável do facilitador?","options":["'O zero vem de robustez ou de tolerância alta demais?' — porque pipeline verde não é sinônimo de tela certa","'Podemos reduzir a equipe de QA agora?'","'Quantas telas conseguimos testar por segundo?'","'Dá para prometer zero regressão aos stakeholders no próximo release?'"],"answer":0,"explanation":"O falso negativo silencioso torna 'verde' enganoso; a pergunta incômoda sobre a origem do zero (robustez vs. tolerância) é metade do trabalho do agilista."}],
  "nondeterministic-assertions": [{"question":"Qual artefato do agilista é diretamente afetado pela ideia de que, em IA, 'pronto' não é sim/não, mas um limiar sobre propriedades?","options":["O gráfico de burndown","O critério de aceite das histórias","A política de WIP do board","A pauta da daily"],"answer":1,"explanation":"Critérios de aceite no formato antigo ('a resposta deve estar correta') são invalidáveis por construção; facilitar critérios testáveis é a atualização de competência do agilista."},{"question":"No refinamento, o critério de aceite diz 'a resposta do resumidor deve estar correta'. Quais três perguntas o agilista provoca, sem precisar de conhecimento técnico?","options":["Qual modelo? qual temperatura? quantos tokens?","Qual o custo? qual a latência? qual o fornecedor?","Correta como? quem decide? com que tolerância?","Quem estima? quando entrega? quem testa?"],"answer":2,"explanation":"'Correta como? quem decide? com que tolerância?' força o time a reescrever o critério em camadas verificáveis — a história sai da cerimônia testável."},{"question":"Ao reescrever o critério em camadas, qual distinção o material diz que o agilista pode 'importar direto' para qualquer refinamento de IA?","options":["Entre modelo grande e modelo pequeno","Entre teste manual e teste automatizado","Entre onde toleramos variação e onde a tolerância é zero (ex.: nenhum dado pessoal)","Entre discovery e delivery"],"answer":2,"explanation":"Separar o que aceita variação (similaridade mínima) do que é inegociável (zero dado pessoal) distingue critério maduro de frase decorativa."},{"question":"Como a validação estatística ('rodar N vezes e medir taxa de aprovação') afeta o seu radar de fluxo?","options":["O esforço de teste de história de IA não é comparável ao de uma comum, e as estimativas precisam refletir isso ou a coluna de teste vira gargalo surpresa","Não afeta: o esforço de teste de história de IA é igual ao de história comum","Elimina a necessidade de estimar histórias de IA","Faz a coluna de teste sumir do board"],"answer":0,"explanation":"Validação estatística muda o esforço da história; ignorar isso na estimativa transforma a etapa de teste em gargalo inesperado."},{"question":"Um card de IA volta da validação com 'taxa de aprovação 3/5, investigando'. Como o agilista deve enxergar isso?","options":["Como indecisão de quem testa, que precisa de mais rigor","Como o formato correto do resultado nesse mundo — não faz sentido pressionar por um 'passou ou não passou?' que o sistema não pode dar","Como bug bloqueante que trava a sprint","Como sinal de que o modelo deve ser trocado"],"answer":1,"explanation":"'3/5, investigando' é o formato certo de resultado num sistema probabilístico; pressionar por sim/não binário ignora a natureza da validação estatística."}],
  "ai-governance": [{"question":"Além da governança técnica do produto de IA (que o time de qualidade constrói), existe uma governança paralela que 'ninguém constrói se não for o agilista'. Qual é ela?","options":["A governança dos model cards e trilhas de auditoria do modelo em produção","A governança do uso de IA no sistema de trabalho do time — quais dados entram em prompt, quando a saída exige revisão humana, como marcar documentos rascunhados por IA","A governança da infraestrutura de nuvem onde o modelo roda","A governança das licenças das ferramentas de IA"],"answer":1,"explanation":"O time já usa IA para redigir, resumir e decidir; sem acordo explícito cada um inventa a própria regra. Governar o uso de IA no sistema de trabalho é acordo de trabalho — ofício do agilista."},{"question":"O material aplica três camadas de governança ao jeito como o time trabalha. Quais são elas?","options":["Requisito, teste e deploy","Discovery, delivery e produção","Política (o que pode), controle (como garantimos) e evidência (como provamos)","Prevenção, detecção e correção"],"answer":2,"explanation":"As mesmas três camadas do produto — política, controle e evidência — aplicadas não ao modelo, mas ao jeito como o time trabalha com IA."},{"question":"Como o agilista concretiza o 'acordo de uso de IA' do time, segundo o exemplo?","options":["Escrevendo um documento técnico de conformidade regulatória sozinho","Proibindo qualquer uso de IA até a área jurídica aprovar","Facilitando um acordo no Confluence com três seções: quais dados nunca entram em prompt, quando a saída exige revisão humana, e como marcar documentos rascunhados por IA — revisado trimestralmente","Deixando cada pessoa registrar suas próprias regras no chat"],"answer":2,"explanation":"O acordo vira working agreement versionado no Confluence, com três seções curtas e revisão trimestral — a diferença entre 'confiar no bom senso' e 'temos um acordo versionado'."},{"question":"O que significa 'dono humano da decisão' traduzido para o vocabulário do agilista?","options":["Que toda automação adotada (triagem de bug por IA, priorização sugerida, relatório gerado) precisa de alguém nomeado que assume o resultado — automação sem dono é risco sem endereço","Que só o agilista pode aprovar uso de IA no time","Que a IA nunca pode participar de decisões do time","Que o dono da decisão é sempre o stakeholder mais sênior"],"answer":0,"explanation":"Nomear donos é facilitação básica: automação sem responsável é risco sem endereço, e apontar esse dono é papel do agilista em cada automação que o time adota."},{"question":"O princípio 'compliance como processo, não evento' se traduz em qual prática de facilitação?","options":["Aprovar o acordo de uso de IA uma vez e arquivá-lo definitivamente","Manter girando o loop de revisão do acordo — a retro aplicada à relação do time com a IA — porque novas ferramentas chegam e os usos mudam","Delegar a revisão do acordo à auditoria externa anualmente","Revisar o acordo somente após um incidente com dado sensível"],"answer":1,"explanation":"Um acordo aprovado e nunca revisitado apodrece como qualquer working agreement; manter o loop de revisão girando é a retro aplicada à relação do time com a IA."}],
  "ai-first-mindset": [{"question":"Qual é a virada de pergunta que define a mentalidade AI First aplicada ao papel do agilista?","options":["De 'será que a IA ajuda aqui?' (atalho ocasional) para 'como a IA faz isso, e como eu valido?' (caminho padrão para o operacional)","De 'qual ferramenta comprar?' para 'qual fornecedor é mais barato?'","De 'como automatizar tudo?' para 'como remover o humano do processo?'","De 'como facilitar melhor?' para 'como delegar a facilitação à IA?'"],"answer":0,"explanation":"AI First é assumir a IA como caminho padrão do operacional (compilar Jira, rascunhar relatório, agrupar retros) e reservar o tempo humano para julgamento, estratégia e validação."},{"question":"Por que a mentalidade AI First tem 'um agravante estratégico' que é mais do agilista do que de qualquer outro papel?","options":["Porque o agilista tem acesso a mais ferramentas de IA que o resto do time","Porque o agilista responde pelos custos de IA do time","Porque só o agilista pode validar as saídas da IA","Porque o agilista é quem modela comportamento: se trabalha AI First o time o segue; se resiste, a transformação que ele prega perde o exemplo"],"answer":3,"explanation":"O agilista prega inspeção e melhoria contínua; se monta o relatório à mão o time aprende com o exemplo, não com o discurso — a transformação começa em como ele trabalha na frente do time."},{"question":"Um relatório de métricas redigido pela IA vai para stakeholders com o seu nome. O que a 'segunda metade da pergunta' (como eu valido?) exige de você?","options":["Confiar na fluência do texto, já que a IA raramente erra","Ter um critério para validá-lo: os números batem com o eazyBI? a conclusão decorre dos dados ou foi 'fluência'?","Encaminhar o relatório sem revisão para ganhar tempo","Pedir ao QA que valide o relatório antes de enviar"],"answer":1,"explanation":"Delegar sem critério de validação é não ter entendido a tarefa: é preciso conferir se os números batem com a fonte e se a conclusão decorre dos dados, não da fluência."},{"question":"Comparando as posturas na sexta-feira do relatório de sprint, qual descreve a postura AI First?","options":["Passar o dia compilando os dados do Jira e copiando números de tela em tela","A IA compila os dados e rascunha o texto no formato acordado, e você gasta trinta minutos conferindo números, ajustando o tom e decidindo qual risco vira conversa em vez de parágrafo","Delegar o relatório inteiro à IA e enviá-lo sem revisão","Pedir ao time que monte o relatório para você validar"],"answer":1,"explanation":"A IA assume o operacional e o humano fica com o julgamento: conferir, ajustar tom e decidir o que merece uma conversa em vez de um parágrafo."},{"question":"Depois de mostrar o fluxo AI First na retro, qual é 'o passo que só o agilista dá'?","options":["Automatizar também as cerimônias do time","Registrar o fluxo como novo working agreement obrigatório","Perguntar ao time 'qual tarefa de vocês merece esse mesmo tratamento?', espalhando a mentalidade","Medir a economia de horas e reportar à diretoria"],"answer":2,"explanation":"Ao provocar o time a identificar tarefas para o mesmo tratamento, o agilista não está usando IA — está espalhando a mentalidade, que é exatamente o seu trabalho."}],
  "ai-first-qa-flow": [{"question":"Quando a IA entra em cada etapa do ciclo de qualidade (do requisito à produção), o que acontece com o sistema de trabalho que o agilista desenhou?","options":["Nada muda: o board continua refletindo a realidade","O board fica obsoleto e deve ser abandonado sem substituto","A IA passa a gerenciar o board sozinha","Ele deixa de refletir a realidade — colunas que representavam trabalho humano viram automação em minutos, o trabalho humano migra para revisão e decisão, e o gargalo muda de lugar sem avisar"],"answer":3,"explanation":"Se cada artefato é interceptado por IA, o desenho antigo não descreve mais o fluxo; quem arquiteta o novo sistema de trabalho (board, WIP, métricas, cerimônias) é o agilista."},{"question":"Qual é o risco de 'quem não redesenha' o fluxo para o modelo AI First?","options":["Aumentar o custo de tokens do time","Passar a medir um processo que não existe mais: cycle time de etapas que a IA executa em segundos, enquanto a fila real (revisão humana) fica invisível","Perder o acesso às ferramentas de IA","Ter que refazer o discovery de todas as iniciativas"],"answer":1,"explanation":"Sem redesenho, o time mede etapas que a IA faz em segundos e não enxerga o novo gargalo — a fila de revisão humana que ninguém colocou no board."},{"question":"Por que a 'cascata de erros' do fluxo AI First dá um peso novo ao refinamento (upstream)?","options":["Porque o refinamento passa a ser feito pela IA sem humanos","Porque o refinamento deixa de ser necessário quando há evals em produção","Porque um requisito ambíguo contamina critérios, casos, dados e automação em velocidade de máquina — o refinamento vira o gate mais barato da cadeia inteira","Porque a IA gera os requisitos e o time só aprova"],"answer":2,"explanation":"Como o erro se propaga em velocidade de máquina, forçar o PO a explicitar a regra antes de a IA 'completá-la' com alucinação plausível é prevenção de retrabalho em escala industrial."},{"question":"Ao redesenhar o board para o modelo AI First (com o QA lead), o que acontece com as etapas que agentes executam, como gerar casos e triar falhas de esteira?","options":["Ganham mais colunas para acompanhar cada passo do agente","Saem do board como colunas e viram automação monitorada; entram colunas explícitas de revisão e decisão humana","São removidas do fluxo por completo, sem substituição","Passam a ser medidas por velocity em vez de cycle time"],"answer":1,"explanation":"Etapas automatizadas viram automação monitorada e o trabalho humano visível (revisão e decisão) ganha colunas próprias — reconfigurando o cycle time por etapa no novo desenho."},{"question":"Um mês após reconfigurar o cycle time por etapa no eazyBI, o gargalo aparece na fila de revisão humana. Que discussão isso abre, e de quem é a facilitação?","options":["Quanto de autonomia dar à IA em cada etapa (o 'dial' do artigo) — decisão de sistema de trabalho cuja facilitação é do agilista","Qual fornecedor de modelo contratar — decisão da engenharia","Quantos QAs contratar — decisão de RH","Se vale a pena manter o eazyBI — decisão de ferramenta"],"answer":0,"explanation":"O gargalo antes invisível abre a conversa sobre o grau de autonomia da IA em cada etapa; graduar esse 'dial' é decisão de sistema de trabalho, e facilitá-la é do agilista."}],
  "quality-of-ai": [{"question":"Se o time de qualidade vira o dono da qualidade da IA do produto, qual é o papel do agilista nessa fronteira?","options":["Construir os evals e guardrails junto com o QA","Aprovar tecnicamente cada release de modelo","Monitorar o drift do modelo diariamente","Conectar essas métricas ao resto da organização — metas, relatórios e conversas de portfólio — traduzindo o painel técnico para a linguagem de metas"],"answer":3,"explanation":"Taxa de alucinação, aderência a formato e custo por requisição nascem no pipeline do QA mas morrem lá se ninguém as traduzir para metas e relatórios — essa ponte é do agilista."},{"question":"Por que deixar a qualidade de IA 'num dashboard de engenharia' é perigoso, na leitura do agilista?","options":["Porque o dashboard consome muitos recursos de infraestrutura","Porque ela só vira pauta quando algo explode — e aí a conversa acontece no pior formato possível: o incidente","Porque a engenharia não sabe ler as métricas corretamente","Porque impede o QA de trabalhar com autonomia"],"answer":1,"explanation":"É o mesmo problema já resolvido com lead time e throughput: dado técnico só vira decisão quando aparece no painel que stakeholders leem — senão só vira pauta no incidente."},{"question":"'Correto vira uma faixa de aceitação' muda a natureza do trabalho que entra na sprint. Como o agilista deve tratar montar dataset de eval, calibrar juiz e renovar casos de produção?","options":["Como tarefas pontuais que somem depois do lançamento","Como responsabilidade exclusiva do QA, fora do planejamento do time","Como trabalho recorrente — manutenção de um sistema que regride sozinho quando o fornecedor atualiza o modelo — cuja capacidade precisa ser reservada e defendida","Como trabalho que a IA faz sozinha em produção"],"answer":2,"explanation":"É trabalho recorrente, como manutenção de suíte de um sistema que regride sozinho; se o agilista não o reconhece no fluxo, ele vira invisível e a empresa descobre a diferença meses depois."},{"question":"Reservar capacidade para a infraestrutura de qualidade de IA, diante de stakeholders ansiosos por feature, é descrito como:","options":["Uma decisão da engenharia que não cabe ao agilista","Uma decisão de sistema de trabalho, e defender essa capacidade é um trabalho clássico do agilista","Um luxo que só times maduros podem se dar","Algo que deve ser negociado apenas depois de um incidente"],"answer":1,"explanation":"Reservar capacidade para qualidade de IA é decisão de sistema de trabalho; defendê-la contra a pressão por features é papel clássico do agilista."},{"question":"No cenário concreto, o agilista integra o painel de qualidade de IA ao relatório mensal e facilita um key result sobre a saúde da IA no ciclo de OKRs. Qual é o efeito?","options":["A qualidade de IA deixa de ser assunto de silo técnico e vira meta da empresa — a diretoria discute qualidade de IA antes de um incidente, não depois","O QA perde autonomia sobre os evals","Os stakeholders passam a operar as ferramentas de teste","O custo por uso deixa de importar para o portfólio"],"answer":0,"explanation":"Ao subir acurácia do eval, escapes de guardrail e custo por uso ao relatório e virar OKR, a qualidade de IA vira meta da empresa — e quem fez a ponte foi o agilista, não o modelo."}],
  "harness-engineering": [{"question":"Traduzido para o mundo do agilista, harness engineering é essencialmente a pergunta:","options":["Qual modelo é mais barato para rodar o agente?","Com que limites, visibilidade e pontos de aprovação esse agente opera no nosso processo?","Quantos tokens o agente consome por tarefa?","Quem escreve o código de orquestração do agente?"],"answer":1,"explanation":"Quando um agente escreve em Jira/Confluence, vira participante do fluxo; harness, para o agilista, é definir limites, visibilidade e pontos de aprovação desse participante no processo."},{"question":"O time quer um agente que faça a primeira triagem do backlog. Como o agilista com repertório de harness desenha a operação?","options":["Libera escrita direta desde o início para ganhar velocidade","Deixa o agente decidir sozinho quais issues priorizar","Proíbe o agente de tocar em qualquer campo do backlog","O agente sugere em vez de aplicar (graduação de autonomia), toda sugestão fica registrada com justificativa (observabilidade), há limites do que ele nunca toca como prioridade e sprint (guardrail), e uma métrica de sugestões aceitas decide se a autonomia sobe"],"answer":3,"explanation":"É governança de fluxo: sugerir antes de aplicar, registrar com justificativa, delimitar o intocável e acompanhar % de sugestões aceitas — o espírito do eval aplicado ao processo."},{"question":"Na revisão do plano do épico do agente de suporte, o PO questiona: 'metade das histórias é retry, guardrail, log, eval — cadê o valor?'. Como o agilista facilita?","options":["Usa uma analogia que o negócio entende — é o freio e o airbag do carro — para preservar o trabalho de harness no plano","Concorda e remove as histórias sem demo para liberar capacidade","Adia o épico até que haja mais features visíveis","Transfere a decisão inteiramente para o Tech Lead"],"answer":0,"explanation":"O harness não gera feature visível e morre na priorização se ninguém o defende; a analogia do freio/airbag traduz para o PO por que 'histórias sem demo' evitam o incidente que pararia o roadmap."},{"question":"O que é o 'working agreement do agente' que o agilista especialista escreve com o time?","options":["O contrato de licenciamento da ferramenta de IA","O código-fonte do agente documentado","A definição de o que o agente pode fazer sozinho, o que exige revisão, como se desliga e quem olha os logs — governança de fluxo com um participante não humano","A lista de tokens que o agente pode consumir por dia"],"answer":2,"explanation":"É fazer pelo processo o que sempre fez — working agreements, pontos de verificação e critérios de saída — agora incluindo um participante não humano."},{"question":"Quando a iniciativa de IA é do produto (não do processo), que valor o repertório de harness dá ao agilista no portfólio?","options":["Torna-o capaz de escrever o código dos guardrails","Permite que ele dispense o time de qualidade da iniciativa","Garante que a iniciativa não precise de rollback","Torna-o um tradutor raro: entende por que o time gasta sprint com guardrails e evals em vez de 'só lançar o agente', e defende esse investimento como a diferença entre um demo e um produto operável"],"answer":3,"explanation":"O repertório o torna tradutor entre time técnico e stakeholder, defendendo o investimento em harness como a diferença entre um demo e um produto operável."}],
  "user-simulation": [{"question":"Como a simulação de usuários muda a 'matéria-prima' da conversa de release do chatbot?","options":["Substitui a sprint review por um relatório automático","Troca a confiança anedótica ('testamos algumas conversas e pareceu bom') por uma taxa de sucesso por persona, medida sobre centenas de trajetórias por build, com thresholds publicados","Elimina a necessidade de go/no-go com stakeholders","Transfere a decisão de lançamento para a IA"],"answer":1,"explanation":"Com taxa de sucesso por persona sobre centenas de trajetórias, o go/no-go deixa de ser disputa de opiniões e vira leitura de painel."},{"question":"Para quem facilita decisões, qual é o maior ganho da simulação de usuários no go/no-go?","options":["Reduzir o custo por token do chatbot","Dispensar a participação dos stakeholders na decisão","O go/no-go deixa de ser debate e vira leitura de painel — e a energia do facilitador migra para ajudar o grupo a acordar os limiares ANTES da pressão do lançamento","Acelerar a velocity da sprint de lançamento"],"answer":2,"explanation":"Com os números disponíveis, a facilitação migra de mediar impressões para acordar thresholds enquanto todos ainda estão frios — quando acordos devem ser feitos."},{"question":"Por que o material insiste em reportar a taxa de sucesso 'por persona' e não só a média?","options":["Porque a média é mais difícil de calcular","Porque a média esconde o caso crítico — a mesma razão pela qual o agilista não reporta só o lead time médio e esconde o percentil que dói","Porque cada persona usa um modelo diferente","Porque stakeholders só entendem números por categoria"],"answer":1,"explanation":"A média mascara o caso crítico (ex.: fraudadores que conseguiram reembolso); é o mesmo motivo de não esconder o percentil doloroso atrás do lead time médio."},{"question":"O time de qualidade propõe montar a infraestrutura de simulação, e o investimento inicial compete com features no backlog. Qual argumento o agilista usa para defendê-lo?","options":["Que a simulação substitui completamente o time de QA","Que ela compra cobertura contínua (centenas de conversas por build, rodando à noite) sem consumir capacidade recorrente do time na sprint","Que é obrigatória por regulação","Que reduz o número de personas necessárias"],"answer":1,"explanation":"Quatrocentas conversas por build feitas por gente consumiriam o time inteiro; a infraestrutura compra cobertura que escala sem gastar capacidade recorrente — o argumento para o planejamento."},{"question":"Na sprint review, o time apresenta 400 conversas por oito personas, incluindo a taxa de fraudadores que conseguiram reembolso indevido. Qual passo o agilista propõe?","options":["Transformar essas taxas no critério de lançamento acordado com stakeholders, registrado antes do go-live, com os bloqueantes explícitos","Repetir a simulação toda sprint até zerar as fraudes","Levar o resultado direto para a diretoria decidir sozinha","Aumentar o número de personas para 16 no próximo build"],"answer":0,"explanation":"Acordar a régua antes do go-live, com bloqueantes explícitos, evita renegociar no calor do lançamento — o acordo é feito enquanto todos ainda estão frios."}],
  "model-migration": [{"question":"Por que a deprecação de modelo é, para o agilista, 'um tipo raro e perigoso de item de portfólio'?","options":["Porque o fornecedor cobra mais caro para migrar","Porque é um risco com data marcada: o relógio corre quer o time tenha capacidade ou não, e deprecation não negocia prioridade","Porque exige trocar toda a stack de ferramentas do time","Porque só a engenharia pode decidir a data da migração"],"answer":1,"explanation":"Deprecation não negocia prioridade — se o calendário não está mapeado, a migração chega como incêndio na semana 11 e atropela o roadmap do quarter."},{"question":"O fornecedor anuncia o desligamento do modelo em 90 dias. Qual é a atuação alinhada ao papel do agilista?","options":["Deixar o aviso envelhecer numa thread e tratar na semana 11","Pedir uma prorrogação ao fornecedor e seguir o roadmap sem mudanças","Abrir a migração como iniciativa no plano do quarter, com marcos do pipeline (baseline, comparação, ajuste de prompts, canary, rollout), reservando capacidade nas sprints","Delegar a migração ao QA sem espaço no plano"],"answer":2,"explanation":"Tratada como iniciativa entediante com marcos e critérios de saída, a migração vira trabalho previsível e o time migra sem parar uma única entrega de produto."},{"question":"Por que o pipeline de cinco etapas 'foi praticamente desenhado para virar plano de iniciativa'?","options":["Porque cada etapa tem critério de saída explícito, e 'ninguém avança com critério pendente' é a definição de marco bem feito","Porque todas as etapas rodam em paralelo, encurtando o prazo","Porque dispensa a participação de stakeholders","Porque cada etapa pode ser automatizada por um agente"],"answer":0,"explanation":"Critério de saída por etapa é marco bem feito; isso dá visibilidade honesta de progresso — 'evals comparados, regressão de formato em ajuste, canary na próxima sprint' informa mais que um percentual inventado."},{"question":"Durante a migração, alguém sugere 'aproveitar que está mexendo' e incluir uma feature no escopo. O que o material orienta?","options":["Aceitar, já que a equipe já está com o código aberto","Incluir a feature apenas se o PO aprovar","Escopo misto é proibido: migração não é hora de aproveitar, e o agilista deve ajudar essa tentação a morrer","Adiar a migração para caber a feature"],"answer":2,"explanation":"Escopo misto é regra proibida na migração; o agilista vai ouvir a tentação de 'aproveitar que está mexendo' e deve ajudá-la a morrer."},{"question":"Na retrospectiva da iniciativa de migração, qual pergunta 'constrói a capacidade' para a próxima deprecação, que já está a caminho?","options":["Quanto custou a migração em tokens?","O que precisa existir para a próxima migração custar metade do esforço? — cada resposta vira backlog","Qual fornecedor devemos abandonar?","Quantas features deixamos de entregar neste quarter?"],"answer":1,"explanation":"Perguntar o que reduz o esforço da próxima migração transforma aprendizado em backlog, construindo a capacidade que torna a próxima deprecação mais barata."}],
  "context-rot": [{"question":"No refinamento de uma feature de IA, o time propõe 'é só mandar o manual inteiro no prompt'. Que pergunta o agilista que entende context rot levanta para melhorar o critério de aceite?","options":["'Qual modelo tem a maior janela de contexto do mercado?'","'E se a informação relevante ficar no meio de 50 páginas?' — mudando o critério de 'recebe o manual inteiro' para 'recupera e usa o trecho certo'.","'Dá para dobrar o tamanho da equipe para revisar o manual?'","'Podemos adiar a feature para o próximo trimestre?'"],"answer":1,"explanation":"O agilista reescreve o critério de aceite: deixa de valer o volume de contexto e passa a valer recuperar e usar o trecho certo — o que o usuário de fato precisa."},{"question":"Como o context rot afeta a PREVISIBILIDADE de qualidade, tema caro ao agilista?","options":["A qualidade fica fixa depois do piloto, então não há o que prever.","A qualidade só depende da velocidade da internet do time.","A qualidade pode se degradar com o tempo conforme a base de conhecimento e o contexto crescem, mesmo sem mudança de código.","A qualidade melhora automaticamente à medida que mais dados entram no contexto."],"answer":2,"explanation":"O artigo destaca que a qualidade se degrada conforme o contexto cresce — um comportamento confiável no piloto pode apodrecer meses depois sem mexer no código."},{"question":"Um stakeholder reclama: 'a IA ficou pior e ninguém mexeu nela'. Como o agilista que conhece context rot explica isso sem misticismo?","options":["Explica que, com a base de conhecimento crescendo, o contexto ficou mais longo e entulhado, e a informação relevante passou a se perder no meio.","Diz que IA é imprevisível por natureza e não há explicação possível.","Atribui a culpa ao fornecedor do modelo e encerra o assunto.","Afirma que o problema é a internet e sugere aguardar."],"answer":0,"explanation":"A causa é concreta: contexto que cresce e apodrece com o tempo — o agilista traduz a degradação em linguagem de negócio, sem misticismo."},{"question":"Diante da ideia de 'dar todo o contexto para a IA', qual é o ângulo honesto do agilista, segundo o artigo?","options":["Aceitar, pois quanto mais contexto, sempre melhor a resposta.","Pedir ao time para operar a ferramenta de teste e reescrever o prompt sozinho.","Ignorar o tema, pois é uma decisão puramente técnica sem impacto no fluxo.","Apoiar investir em curadoria e recuperação (RAG) em vez de despejar tudo, tratando esse esforço como trabalho real no backlog."],"answer":3,"explanation":"O ângulo do agilista é dimensionar a curadoria como trabalho de verdade e sustentar a decisão de arquitetura — sem operar ferramenta de teste."},{"question":"Qual afirmação sobre janela de contexto o agilista deve tratar como suposição falsa ao planejar iniciativas de IA?","options":["'Caber na janela não é o mesmo que ser usado pelo modelo.'","'Mais contexto é sempre melhor — basta despejar tudo que a qualidade sobe.'","'Vale posicionar a informação essencial nas pontas do contexto.'","'A qualidade pode degradar conforme o contexto cresce.'"],"answer":1,"explanation":"A suposição falsa é 'mais contexto é sempre melhor'. O artigo mostra o oposto: passado certo ponto, material irrelevante derruba a qualidade."}],
  "sycophancy": [{"question":"Na retro, alguém joga no chat 'o gargalo é o pessoal que testa, né?' e mostra a resposta da IA que concorda. Como o agilista que entende sycophancy conduz?","options":["Aceita a resposta como consenso, já que a IA confirmou a hipótese.","Reformula de forma neutra ('onde estão os maiores tempos de espera no fluxo?') e traz o dado real do board, separando a opinião validada do diagnóstico.","Encerra a retro, pois a IA já apontou o culpado.","Pede à IA para operar a ferramenta de teste e provar o gargalo."],"answer":1,"explanation":"O agilista neutraliza a pergunta enviesada e ancora a conversa em dados do board, separando o eco da IA do diagnóstico real."},{"question":"Por que 'a IA concordou' NÃO deve ser tratado como evidência numa decisão de time, segundo o artigo?","options":["Porque a IA nunca acerta e deve ser sempre ignorada.","Porque a IA só responde em inglês e o time não entende.","Porque a concordância é a saída mais provável de uma pergunta que já sugeriu a resposta — um eco, não uma confirmação independente.","Porque a IA só pode opinar sobre código, nunca sobre processo."],"answer":2,"explanation":"Concordância induzida é reflexo da própria pergunta; não é dado independente, então não decide a disputa no lugar dos números e da conversa do time."},{"question":"Qual risco de facilitação a bajulação cria quando o time usa IA para 'validar' decisões?","options":["Aumenta o custo de licenças de ferramentas de teste.","Vira uma câmara de eco que concorda com quem falou por último ou mais alto, industrializando o viés de confirmação.","Torna as cerimônias mais longas por excesso de logs técnicos.","Impede o time de acessar o board durante a reunião."],"answer":1,"explanation":"O artigo alerta que a IA bajuladora amplifica o viés de confirmação, carimbando com 'autoridade' decisões que ninguém examinou de verdade."},{"question":"Ao desenhar o USO da IA em planning e retro para reduzir viés, o que o agilista deve incentivar?","options":["Perguntas que já embutem a conclusão desejada, para ir mais rápido.","Aceitar sempre a primeira resposta, quanto mais gentil melhor.","Escrever código de teste na reunião para validar cada hipótese.","Perguntas neutras e o pedido explícito do outro lado ('liste os riscos e argumentos contra'), forçando a IA a discordar quando for o caso."],"answer":3,"explanation":"O agilista desenha o uso para reduzir viés: perguntas neutras e pedido do contraditório neutralizam a tendência da IA de só validar."},{"question":"Segundo o artigo, de onde vem a bajulação — e o que isso implica para o agilista que só quer 'trocar por um modelo melhor'?","options":["De um viés aprendido no ajuste por preferência humana; ela aparece em vários modelos e se mitiga com bom processo e boas perguntas, não só trocando de modelo.","De um bug pontual de uma marca; basta atualizar a versão para eliminá-la.","De uma falha na internet do time, resolvida com melhor conexão.","Da falta de contexto; basta despejar mais informação no prompt."],"answer":0,"explanation":"A bajulação é viés aprendido no treino por preferência humana e aparece em modelos variados; mitiga-se com facilitação e prompts neutros, não só com upgrade."}],
  "model-routing": [{"question":"Segundo o artigo, qual é a frase que resume o valor do model routing para explicar a quem decide orçamento?","options":["'Vamos treinar nosso próprio modelo do zero para baratear tudo.'","'90% do tráfego é simples e vai para o modelo barato; o caro entra só nos 10% críticos.'","'A IA vai revolucionar o atendimento e cortar todos os custos.'","'Precisamos aumentar a temperatura para o modelo responder mais rápido.'"],"answer":1,"explanation":"O artigo apresenta essa frase como a que tira a decisão de custo do território exclusivo da engenharia e a transforma em conversa de produto que o agilista facilita."},{"question":"Quando o custo de IA estoura e vira pauta, qual 'terceira via' o artigo diz que o roteamento oferece, em vez de 'cortar a IA'?","options":["Segmentar o tráfego e enquadrar um spike para medir o que é trivial e priorizar onde aceitar o modelo mais barato.","Desligar a IA nos horários de pico até o custo baixar.","Terceirizar a decisão inteiramente para o fornecedor do modelo.","Aumentar o preço do produto para o cliente pagar o modelo caro."],"answer":0,"explanation":"O artigo propõe transformar 'onde aceitamos o modelo mais barato' em itens de backlog priorizados, com o risco de qualidade explícito no critério de aceite, em vez de um corte às cegas."},{"question":"Sobre previsibilidade, por que o artigo alerta o agilista a não medir 'tempo de resposta' como um número único em roteamento e cascata?","options":["Porque a latência não muda com roteamento, então a média é sempre estável.","Porque só o custo importa, e a latência é irrelevante para o time.","Porque a latência muda de forma desigual: a maioria fica mais rápida, mas os casos que escalam ficam mais lentos — a média mente e é preciso olhar percentis.","Porque o modelo grande é sempre mais rápido que o pequeno."],"answer":2,"explanation":"O artigo destaca que a cascata pode custar duas chamadas nos casos que escalam; olhar percentis conecta a decisão de arquitetura à saúde da entrega e à expectativa do stakeholder."},{"question":"Como o artigo sugere que o agilista trate a decisão de 'onde aceitar o modelo mais barato'?","options":["Como detalhe técnico que fica só com a engenharia.","Como itens de backlog priorizados, com o risco de qualidade explícito no critério de aceite.","Como um corte imediato feito no susto para conter o custo.","Como algo a resolver só depois que o produto já estiver em produção."],"answer":1,"explanation":"O artigo defende transformar a decisão de custo × experiência em backlog priorizável, com o risco de qualidade escrito no critério de aceite, e não em um corte às cegas."},{"question":"Qual métrica o artigo aponta como um novo item que o agilista passa a acompanhar em vez de virar 'surpresa no fim do mês'?","options":["O número de commits por desenvolvedor na sprint.","A quantidade de cerimônias realizadas por semana.","A cobertura de testes automatizados do repositório.","O custo, agora previsível por faixa de dificuldade do tráfego."],"answer":3,"explanation":"O artigo diz que, com o roteamento, o custo vira uma métrica previsível por faixa que o agilista acompanha, em vez de uma surpresa no fechamento do mês."}],
  "semantic-caching": [{"question":"Segundo o artigo, como o agilista deve enquadrar o cache semântico para o time, em vez de tratá-lo como 'detalhe de infra'?","options":["Como um trade-off de valor com risco embutido — item de backlog com critério de aceite e prioridade.","Como uma configuração automática que não precisa de acompanhamento.","Como uma decisão exclusiva da engenharia, fora do backlog.","Como uma otimização que deve ser ligada no escuro para ver no que dá."],"answer":0,"explanation":"O artigo defende enquadrar o ajuste do cache como item de backlog com valor e risco explícitos, e não como tarefa invisível de bastidor."},{"question":"Qual é, segundo o artigo, a decisão mais importante que o agilista ajuda a facilitar sobre o cache, e de quem é essa decisão?","options":["Escolher o algoritmo de embedding — decisão de arquitetura de software.","Definir a fronteira entre o que pode ser cacheado por similaridade e o que é sensível demais — decisão de negócio, não de código.","Definir a linguagem de programação do serviço de cache.","Escolher o provedor de nuvem onde o banco vetorial roda."],"answer":1,"explanation":"O artigo diz que separar perguntas sensíveis a exceções (feriado, tipo de cliente, valores) do que pode ser cacheado é decisão de negócio e entra como critério de aceite da iniciativa."},{"question":"Por que o artigo alerta o agilista a não medir a latência do cache por uma média única?","options":["Porque a latência não muda com cache e a média é sempre confiável.","Porque só o custo importa para a previsibilidade da entrega.","Porque o cache torna a latência desigual: o acerto é instantâneo e o miss leva o tempo cheio — a média esconde a experiência de quem caiu no miss.","Porque o miss é sempre mais rápido que o acerto."],"answer":2,"explanation":"O artigo recomenda olhar taxa de acerto e percentis para conectar a decisão técnica à saúde da entrega e à expectativa do stakeholder."},{"question":"Que trade-off o artigo diz que o agilista precisa deixar explícito ao discutir 'mais cache' com o time?","options":["Mais cache é sempre melhor, sem qualquer contrapartida.","Mais cache é mais barato e rápido, mas com mais chance de resposta 'quase certa'; menos cache é mais seguro, porém mais caro e lento.","Cache só afeta o custo, nunca a experiência do usuário.","O trade-off é apenas entre duas linguagens de programação."],"answer":1,"explanation":"O artigo apresenta esse trade-off de custo/latência versus risco de 'quase certa' como o que justifica priorizar o ajuste fino como item de valor."},{"question":"Segundo o artigo, quais duas coisas que o agilista acompanha o cache semântico toca diretamente, tornando-o uma iniciativa que precisa do agilista na mesa?","options":["A cobertura de testes e o número de commits do time.","A quantidade de cerimônias e a duração das sprints.","A velocidade de digitação do usuário e o número de bugs abertos.","A experiência do usuário (respostas instantâneas) e o orçamento do produto (menos chamadas pagas ao modelo)."],"answer":3,"explanation":"O artigo descreve o cache como uma alavanca dupla de latência e custo, que toca tanto a experiência do usuário quanto o orçamento — por isso precisa do agilista enquadrando o risco."}],
  "rag-evaluation": [{"question":"Chega ao backlog o épico 'melhorar a IA do assistente interno'. Segundo o artigo, como a avaliação de RAG ajuda o agilista a lidar com esse item?","options":["Confirmando que épicos de IA devem sempre ficar abertos até a próxima release.","Convertendo o 'melhorar' vago em números por eixo, que se quebram em histórias com critério de aceite mensurável.","Sugerindo que o épico seja fechado sem histórias, pois IA não é estimável.","Recomendando terceirizar a decisão para o fornecedor do modelo."],"answer":1,"explanation":"As métricas transformam o épico vago em números acionáveis; números acionáveis se quebram em histórias com escopo fechado e critério de aceite mensurável."},{"question":"Por que, para o fluxo e a previsibilidade, importa saber se a falha do RAG é de recuperação ou de geração ANTES de planejar a sprint?","options":["Porque cada eixo é um tipo de trabalho diferente (dados/índice vs prompt/guardrail), com pessoas e esforço distintos.","Porque a recuperação é sempre mais rápida de corrigir que a geração.","Porque só a geração pode ser colocada em uma sprint; a recuperação é trabalho contínuo.","Porque o eixo determina qual cerimônia deve ser cancelada naquela sprint."],"answer":0,"explanation":"Falha de recuperação é trabalho de dados/índice; falha de geração é prompt/guardrail. Saber de qual lado está o defeito evita puxar a especialidade errada para a sprint — isso é previsibilidade."},{"question":"Qual pergunta de facilitação o artigo sugere para desempatar uma discussão técnica sobre o assistente sem ficar refém dela?","options":["'Qual modelo tem o maior número de parâmetros?'","'Quantos tokens o prompt está gastando por resposta?'","'Isso é recuperação ou geração?'","'Qual fornecedor é o mais barato para trocarmos?'"],"answer":2,"explanation":"Perguntar 'é recuperação ou geração?' quebra o épico em duas trilhas nítidas no refinamento e move a conversa de impressão para evidência, sem exigir que o agilista opere a ferramenta."},{"question":"Stakeholders reclamam das respostas do assistente que roda sobre a base de conhecimento do time. Como entender os dois eixos ajuda o agilista a ler a reclamação?","options":["Toda reclamação de RAG é sempre culpa do modelo de geração.","Distinguindo 'a informação existe e ele erra' (um problema) de 'a informação nunca foi documentada' (outro, que é de conteúdo, não do modelo).","Concluindo que a reclamação é subjetiva e não deve virar item de backlog.","Assumindo que o problema é sempre falta de treinamento do modelo com dados da empresa."],"answer":1,"explanation":"Entender recuperação vs geração dá a leitura certa: informação inexistente na base é problema de conteúdo/documentação (seu), não de modelo — remover a causa exige saber onde ela mora."},{"question":"Na revisão da sprint, o que muda quando o time apresenta a matriz 2x2 de métricas de RAG em vez de exemplos escolhidos a dedo?","options":["Nada relevante: exemplos avulsos e métricas comunicam a mesma coisa.","A conversa passa de impressão para evidência, mostrando em qual eixo houve regressão ou avanço.","A revisão vira uma cerimônia técnica que exclui os stakeholders.","O time perde a rastreabilidade do que foi entregue na sprint."],"answer":1,"explanation":"A matriz 2x2 substitui três exemplos convenientes por evidência sobre cada eixo, tornando a conversa de review baseada em dados de qualidade em vez de impressão."}],
  "deep-research": [{"question":"Segundo o artigo, qual é o principal uso de deep research para o agilista?","options":["Substituir a cerimônia de refinamento por um relatório gerado automaticamente.","Discovery aumentado: levantar contexto de mercado, comparar abordagens e sintetizar insumo para uma iniciativa em minutos.","Estimar automaticamente o esforço das histórias do backlog.","Gerar os critérios de aceite finais de cada história sem revisão."],"answer":1,"explanation":"Deep research é discovery aumentado: acelera o levantamento de contexto antes de abrir uma iniciativa — como acelerador de descoberta, não como decisor."},{"question":"O artigo insiste que o agilista trate o relatório de deep research como 'rascunho de discovery, não conclusão'. Por quê?","options":["Porque relatórios de IA são sempre curtos demais para uma iniciativa.","Porque o entregável bonito não é sinal de trajetória sólida; a decisão não se delega a uma síntese não auditada.","Porque o time nunca deve usar fontes externas em uma discovery.","Porque rascunhos não podem ser anexados a itens do backlog."],"answer":1,"explanation":"A prosa impecável é a parte fácil e a maior armadilha. Tratar como rascunho significa conferir as citações-chave e levar o material verificado ao time, sem terceirizar o julgamento."},{"question":"Sobre previsibilidade, qual alerta o artigo faz ao agilista que conta com um agente de deep research para acelerar o levantamento?","options":["Que a aceleração elimina totalmente a necessidade de discovery com o time.","Que o esforço de verificar o que o agente produziu é trabalho real que pertence ao planejamento, não um bônus grátis.","Que agentes de pesquisa devem ser proibidos em iniciativas de portfólio.","Que o relatório deve substituir a conversa com stakeholders."],"answer":1,"explanation":"Contar com a aceleração e esquecer a verificação é como estimar só a parte fácil de uma história e se surpreender com o resto — a verificação é trabalho de verdade."},{"question":"Qual pergunta de facilitação o artigo sugere quando o time se empolga com um achado de deep research?","options":["'Qual modelo gerou esse relatório?'","'Quantas fontes o agente leu no total?'","'Essa afirmação veio de qual fonte, e a fonte diz mesmo isso?'","'Quanto tempo o agente levou para responder?'"],"answer":2,"explanation":"É a mesma disciplina de desconfiar da fonte antes de agir sobre qualquer número de fluxo: confrontar a afirmação com a fonte que supostamente a sustenta."},{"question":"Segundo o artigo, como o agilista deve medir o ganho real de usar deep research na discovery?","options":["Pelo número de relatórios gerados por sprint.","Pelo tamanho e pela qualidade estética do relatório final.","Pelo tempo de levantamento que encurtou, depois de descontado o esforço de verificação.","Pela quantidade de citações que o relatório apresenta."],"answer":2,"explanation":"O valor não é 'gerou um relatório', e sim o tempo de levantamento economizado descontada a verificação; sem esse desconto, mede-se apenas a parte fácil."}],
  "shadow-ai": [{"question":"Segundo o artigo, por que shadow AI cai no colo do agilista como pauta de liderança do sistema de trabalho?","options":["Porque cabe a ele bloquear tecnicamente o acesso às ferramentas de IA.","Porque o uso informal de IA é um acordo de trabalho tácito que ainda não foi escrito — e formalizá-lo com o time é trabalho de facilitação.","Porque o agilista é o responsável por auditar os prompts de cada pessoa.","Porque só o agilista pode aprovar a contratação de ferramentas corporativas."],"answer":1,"explanation":"O artigo trata o uso informal como um acordo tácito ('a gente usa o que for prático') que o agilista traz à mesa e transforma num acordo explícito, negociado com o time."},{"question":"O artigo contrasta governança leve com proibição. Qual é a conclusão estratégica?","options":["Proibir é mais seguro, porque elimina de vez o uso de IA.","As duas são equivalentes; o que importa é ter algum documento.","Governança leve, feita com o time, é mais eficaz — proibir empurra o uso para a clandestinidade e quebra a confiança.","A melhor opção é não ter regra nenhuma e confiar no bom senso."],"answer":2,"explanation":"O artigo defende que governança leve definida com o time vence a proibição: proibir não elimina o uso, só o afunda na clandestinidade, onde some a visibilidade e se perde a confiança."},{"question":"Numa daily, você percebe várias menções a 'joguei no chat'. Qual conduta o artigo recomenda ao agilista?","options":["Proibir na hora o uso de qualquer ferramenta de IA pelo time.","Ignorar, já que é decisão individual de cada pessoa.","Escrever sozinho uma política e comunicá-la como decisão fechada.","Facilitar um acordo de trabalho: ferramentas sancionadas, o que nunca colar e como pedir exceção — um item vivo do time."],"answer":3,"explanation":"O artigo usa exatamente esse gatilho: em vez de proibir, o agilista facilita um acordo de trabalho com ferramentas sancionadas, o que nunca sai e uma válvula de exceção, mantido vivo pelo time."},{"question":"Por que o artigo insiste que o acordo de uso de IA precisa ser 'um item vivo', e não um documento fechado?","options":["Porque documentos precisam de aprovação formal a cada trimestre.","Porque surgem ferramentas e casos limítrofes novos o tempo todo — uma regra desatualizada é ignorada tão rápido quanto uma inexistente.","Porque o time perde o interesse se a regra não mudar toda semana.","Porque a liderança exige revisões constantes por padrão."],"answer":1,"explanation":"O artigo alerta que um documento nunca revisitado envelhece na velocidade em que surgem ferramentas novas, e uma regra obsoleta é ignorada como uma inexistente — daí o gatilho de revisão."},{"question":"O artigo diz que o objetivo é 'risco gerenciável com atrito mínimo'. Qual armadilha de facilitação isso alerta o agilista a evitar?","options":["Confundir governança com burocracia — cada gota de atrito extra empurra o uso de volta para a clandestinidade.","Delegar a política inteiramente ao time sem nenhuma diretriz.","Revisar o acordo com frequência baixa demais.","Comunicar a política aos stakeholders da empresa."],"answer":0,"explanation":"O artigo avisa contra confundir governança com burocracia: o alvo é risco gerenciável com atrito mínimo, e cada atrito adicionado é um empurrão de volta para o uso clandestino."}],
  "ai-incident-response": [{"question":"Por que o artigo trata a facilitação do post-mortem como trabalho de agilista puro?","options":["Porque o post-mortem é uma cerimônia de aprendizado, e garantir que seja sem culpa e que gere ação é papel de facilitação.","Porque o agilista é quem escreve a correção técnica do incidente.","Porque cabe ao agilista acionar o rollback do modelo.","Porque o agilista decide sozinho a causa raiz do incidente."],"answer":0,"explanation":"O artigo enquadra o post-mortem como cerimônia de aprendizado: a primeira responsabilidade do agilista é garantir que seja sem culpa, e a segunda, que o aprendizado vire ação."},{"question":"Segundo o artigo, por que a pergunta 'de quem foi a culpa?' destrói o post-mortem?","options":["Porque atrasa a reunião em alguns minutos.","Porque a culpa deve ser atribuída, mas por escrito.","Porque impede a IA de aprender com o incidente.","Porque as pessoas se defendem, escondem informação e o time sai sem entender o que realmente aconteceu."],"answer":3,"explanation":"O artigo explica que a gravidade puxa para o 'de quem foi a culpa?', e essa pergunta faz as pessoas se defenderem e esconderem informação — a segurança psicológica é o que faz a verdade aparecer."},{"question":"O artigo diz que a maioria dos times erra no fechamento do post-mortem. Qual é esse erro?","options":["Convidar gente demais para a reunião.","Terminar com boas intenções e nenhum item priorizado — catarse em vez de melhoria.","Documentar a linha do tempo com detalhe excessivo.","Fazer o post-mortem cedo demais após o incidente."],"answer":1,"explanation":"O artigo alerta que um post-mortem que termina sem item priorizado é catarse, não melhoria: o papel do agilista é fechar com poucas ações concretas, com dono, no backlog."},{"question":"Sobre a comunicação durante o incidente, qual é a orientação do artigo ao agilista?","options":["Deixar os stakeholders no escuro até a correção estar pronta.","Repassar a comunicação inteiramente ao time técnico.","Cuidar do combinado de comunicação — quem avisa, com que frequência, em que tom — de preferência acordado antes, junto ao playbook.","Comunicar apenas depois do post-mortem concluído."],"answer":2,"explanation":"O artigo aponta que um incidente mal comunicado corrói mais confiança que a falha, e cabe ao agilista facilitar o combinado de comunicação, idealmente acordado antes, junto com o playbook."},{"question":"Segundo o artigo, qual é o sinal de maturidade de um time diante de incidentes de IA?","options":["Nunca ter incidentes em produção.","Resolver todo incidente sem envolver stakeholders.","Cada incidente deixar o sistema mais forte — vira barreira permanente e ação concluída, não uma história de corredor.","Reduzir a zero o número de post-mortems realizados."],"answer":2,"explanation":"O artigo afirma que o sinal de maturidade não é nunca ter incidente, mas cada incidente deixar o sistema mais forte, porque virou barreira permanente e ação concluída no backlog."}],
};
